function facilityViewMode(page) {
  if (page === "training" && app.trainingScene === "position_training") return "visual";
  return app.facilityViewModes?.[page] === "text" ? "text" : "visual";
}

function facilityViewBusy(page) {
  if (page === "activity") return Boolean(app.activityActionBusy);
  if (page === "training") return Boolean(app.trainingActionBusy || app.positionTrainingBusy);
  if (page === "canteen") return Boolean(app.canteenActionBusy || app.canteenSyncPromise);
  return false;
}

function syncFacilityViewMode(page) {
  const mode = facilityViewMode(page);
  const root = $(`#page-${page}`);
  if (!root) return mode;
  root.dataset.facilityView = mode;
  root.classList.toggle("facility-text-view", mode === "text");
  root.querySelectorAll(`[data-facility-view-page="${page}"]`).forEach((checkbox) => {
    checkbox.checked = mode === "text";
    checkbox.disabled = facilityViewBusy(page)
      || (page === "training" && app.trainingScene === "position_training");
  });
  return mode;
}

function setFacilityViewMode(page, requestedMode) {
  if (!FACILITY_VIEW_PAGES.includes(page) || facilityViewBusy(page)) return;
  const mode = requestedMode === "text" ? "text" : "visual";
  if (facilityViewMode(page) === mode) return;
  app.facilityViewModes[page] = mode;
  try { localStorage.setItem(`${FACILITY_VIEW_STORAGE_PREFIX}${page}`, mode); } catch (_error) { /* local preference only */ }
  if (page === "activity") {
    app.activityRenderSignature = null;
    renderActivity();
  } else if (page === "training") {
    if (mode === "text") app.trainingEditing = false;
    app._lastStageHash = null;
    app._lastDockHash = null;
    app._lastSelHash = null;
    renderTraining();
  } else if (page === "canteen") {
    app.canteenRenderSignature = null;
    renderCanteen();
  }
}
