const $ = (selector) => document.querySelector(selector);
const escapeHtml = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char]));

const customSelectState = {
  openKey: null,
  menu: null,
  observer: null,
  syncQueued: false,
  pendingRoots: new Set(),
  renderStates: new WeakMap(),
  pendingValues: new Map(),
  menuSignature: null,
  menuInteracting: false,
  scrollTop: new Map(),
};

function customSelectContextKey() {
  const data = app.state?.output || app.state || {};
  return [data.save_instance_id || data.data_scope_id || "startup", data.selected_manager_id || 0].join(":");
}

function customSelectKey(select) {
  if (select.id) return `${customSelectContextKey()}:id:${select.id}`;
  const identity = [...select.attributes]
    .filter((attribute) => attribute.name === "name" || attribute.name.startsWith("data-"))
    .map((attribute) => `${attribute.name}=${attribute.value}`)
    .sort()
    .join("&");
  const owner = select.closest("[id]");
  const index = owner ? [...owner.querySelectorAll("select")].indexOf(select) : [...document.querySelectorAll("select")].indexOf(select);
  if (identity) return `${customSelectContextKey()}:attrs:${owner?.id || "document"}:${index}:${identity}`;
  return `${customSelectContextKey()}:path:${owner?.id || "document"}:${index}`;
}

function ensureCustomSelectMenu() {
  if (customSelectState.menu?.isConnected) return customSelectState.menu;
  const menu = document.createElement("div");
  menu.id = "fmodd-select-menu";
  menu.className = "fmodd-select-menu";
  menu.setAttribute("popover", "manual");
  menu.setAttribute("role", "listbox");
  menu.hidden = true;
  menu.addEventListener("pointerdown", () => { customSelectState.menuInteracting = true; });
  menu.addEventListener("scroll", () => {
    if (customSelectState.openKey) customSelectState.scrollTop.set(customSelectState.openKey, menu.scrollTop);
  }, {passive:true});
  menu.addEventListener("click", (event) => {
    const optionButton = event.target.closest("[data-fmodd-select-option]");
    if (!optionButton || optionButton.disabled) {
      customSelectState.menuInteracting = false;
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    const select = activeCustomSelect();
    if (!select) return;
    const key = customSelectKey(select);
    select.value = optionButton.dataset.fmoddSelectOption;
    select.dispatchEvent(new Event("input", {bubbles:true}));
    select.dispatchEvent(new Event("change", {bubbles:true}));
    closeCustomSelect();
    syncCustomSelects();
    [...document.querySelectorAll("select")]
      .find((candidate) => customSelectKey(candidate) === key)
      ?.closest(".fmodd-select")
      ?.querySelector(".fmodd-select-trigger")
      ?.focus();
    customSelectState.menuInteracting = false;
  });
  document.body.appendChild(menu);
  customSelectState.menu = menu;
  return menu;
}

function mountCustomSelectMenu(menu, select) {
  const host = select.closest("dialog[open]") || document.body;
  if (menu.parentNode === host) return;
  if (typeof menu.hidePopover === "function" && menu.matches(":popover-open")) menu.hidePopover();
  host.appendChild(menu);
}

function showCustomSelectMenu(menu) {
  menu.hidden = false;
  if (typeof menu.showPopover !== "function") return;
  if (!menu.matches(":popover-open")) menu.showPopover();
}

function hideCustomSelectMenu(menu) {
  if (typeof menu.hidePopover === "function" && menu.matches(":popover-open")) menu.hidePopover();
  menu.hidden = true;
}

function activeCustomSelect() {
  if (!customSelectState.openKey) return null;
  return [...document.querySelectorAll("select")].find((select) => customSelectKey(select) === customSelectState.openKey) || null;
}

function customSelectOptionRows(select) {
  const rows = [];
  [...select.children].forEach((child) => {
    if (child.tagName === "OPTGROUP") {
      rows.push(`<div class="fmodd-select-group">${escapeHtml(child.label)}</div>`);
      [...child.children].forEach((option) => rows.push(customSelectOptionRow(select, option)));
    } else if (child.tagName === "OPTION") {
      rows.push(customSelectOptionRow(select, child));
    }
  });
  return rows.join("");
}

function customSelectFontPreviewFamily(select, option) {
  if (!option) return "";
  if (!["chinese-font", "english-font"].includes(select.id)) return "";
  return FONT_OPTIONS[option.value]?.source || "";
}

function customSelectOptionRow(select, option) {
  const selected = option.value === select.value;
  const previewFamily = customSelectFontPreviewFamily(select, option);
  const previewClass = previewFamily ? " font-preview-option" : "";
  const previewStyle = previewFamily
    ? ` style="--font-preview-family:${escapeHtml(previewFamily)}"`
    : "";
  return `<button class="fmodd-select-option${selected ? " selected" : ""}${previewClass}" type="button" role="option" aria-selected="${selected}" data-fmodd-select-option="${escapeHtml(option.value)}"${previewStyle} ${option.disabled ? "disabled" : ""}><span>${escapeHtml(option.textContent)}</span>${selected ? '<i aria-hidden="true">✓</i>' : ""}</button>`;
}

function customSelectMenuSignature(select) {
  const options = [...select.children].map((child) => {
    if (child.tagName === "OPTGROUP") {
      return ["group", child.label, child.disabled, [...child.children].map((option) => [option.value, option.textContent, option.disabled])];
    }
    return ["option", child.value, child.textContent, child.disabled];
  });
  return JSON.stringify([customSelectKey(select), select.value, select.disabled, options]);
}

function positionCustomSelectMenu(select) {
  const menu = ensureCustomSelectMenu();
  const trigger = select.closest(".fmodd-select")?.querySelector(".fmodd-select-trigger");
  if (!trigger || menu.hidden) return;
  const rect = trigger.getBoundingClientRect();
  const margin = 8;
  const width = Math.min(Math.max(rect.width, 180), window.innerWidth - margin * 2);
  menu.style.width = `${width}px`;
  menu.style.left = `${Math.min(Math.max(margin, rect.left), window.innerWidth - width - margin)}px`;
  const below = window.innerHeight - rect.bottom - margin;
  const above = rect.top - margin;
  const requestedMaxHeight = Number(select.dataset.menuMaxHeight);
  const maxMenuHeight = Number.isFinite(requestedMaxHeight) && requestedMaxHeight > 0 ? requestedMaxHeight : 320;
  const desiredHeight = Math.min(menu.scrollHeight, maxMenuHeight, window.innerHeight - margin * 2);
  const placeBelow = below >= desiredHeight || (above < desiredHeight && below >= above);
  const availableHeight = Math.max(60, placeBelow ? below : above);
  const menuHeight = Math.min(desiredHeight, availableHeight);
  menu.style.maxHeight = `${menuHeight}px`;
  menu.style.top = placeBelow ? `${rect.bottom + 5}px` : `${rect.top - menuHeight - 5}px`;
}

function renderCustomSelectMenu(select) {
  const menu = ensureCustomSelectMenu();
  mountCustomSelectMenu(menu, select);
  const signature = customSelectMenuSignature(select);
  const rebuild = signature !== customSelectState.menuSignature && !customSelectState.menuInteracting;
  if (rebuild) {
    menu.innerHTML = customSelectOptionRows(select) || `<div class="fmodd-select-empty">${escapeHtml(uiText("shell.select.empty"))}</div>`;
    customSelectState.menuSignature = signature;
  }
  menu.setAttribute("aria-label", select.getAttribute("aria-label") || select.closest("label")?.textContent?.trim() || uiText("shell.select.aria"));
  showCustomSelectMenu(menu);
  positionCustomSelectMenu(select);
  if (rebuild) {
    menu.scrollTop = customSelectState.scrollTop.get(customSelectState.openKey) || 0;
    menu.querySelector(".selected")?.scrollIntoView({block:"nearest"});
  }
}

function openCustomSelect(select) {
  if (select.disabled) return;
  customSelectState.openKey = customSelectKey(select);
  syncCustomSelects();
}

function closeCustomSelect({restoreFocus = false} = {}) {
  const select = activeCustomSelect();
  const trigger = select?.closest(".fmodd-select")?.querySelector(".fmodd-select-trigger");
  customSelectState.openKey = null;
  const menu = ensureCustomSelectMenu();
  hideCustomSelectMenu(menu);
  customSelectState.menuSignature = null;
  customSelectState.menuInteracting = false;
  document.querySelectorAll(".fmodd-select.open").forEach((wrapper) => {
    wrapper.classList.remove("open");
    wrapper.querySelector(".fmodd-select-trigger")?.setAttribute("aria-expanded", "false");
  });
  if (restoreFocus) trigger?.focus();
}

function moveCustomSelect(select, direction) {
  const options = [...select.options].filter((option) => !option.disabled);
  if (!options.length) return;
  const current = Math.max(0, options.findIndex((option) => option.value === select.value));
  const target = options[Math.min(options.length - 1, Math.max(0, current + direction))];
  if (!target || target.value === select.value) return;
  select.value = target.value;
  select.dispatchEvent(new Event("input", {bubbles:true}));
  select.dispatchEvent(new Event("change", {bubbles:true}));
  syncCustomSelect(select);
  if (customSelectKey(select) === customSelectState.openKey) renderCustomSelectMenu(select);
}

function enhanceCustomSelect(select) {
  if (select.multiple || select.closest(".fmodd-select")) return;
  const wrapper = document.createElement("span");
  wrapper.className = "fmodd-select";
  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "fmodd-select-trigger";
  trigger.setAttribute("aria-haspopup", "listbox");
  trigger.setAttribute("aria-controls", "fmodd-select-menu");
  trigger.setAttribute("aria-expanded", "false");
  trigger.innerHTML = '<span class="fmodd-select-value"></span><i class="fmodd-select-chevron" aria-hidden="true"></i>';
  select.parentNode.insertBefore(wrapper, select);
  wrapper.append(select, trigger);
  select.classList.add("fmodd-select-native");
  select.tabIndex = -1;
  trigger.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const same = customSelectState.openKey === customSelectKey(select);
    if (same) closeCustomSelect();
    else openCustomSelect(select);
  });
  trigger.addEventListener("keydown", (event) => {
    if (["Enter", " ", "ArrowDown", "ArrowUp", "Home", "End", "Escape"].includes(event.key)) event.preventDefault();
    if (event.key === "Escape") { closeCustomSelect({restoreFocus:true}); return; }
    if (event.key === "Enter" || event.key === " ") {
      if (customSelectState.openKey === customSelectKey(select)) closeCustomSelect();
      else openCustomSelect(select);
      return;
    }
    if (event.key === "Home") moveCustomSelect(select, -select.options.length);
    if (event.key === "End") moveCustomSelect(select, select.options.length);
    if (event.key === "ArrowDown") moveCustomSelect(select, 1);
    if (event.key === "ArrowUp") moveCustomSelect(select, -1);
  });
  // Some change handlers synchronously rebuild the surrounding card/page. Keep
  // the user's value long enough for the replacement select to inherit it.
  select.addEventListener("change", () => {
    const key = customSelectKey(select);
    const value = String(select.value);
    customSelectState.pendingValues.set(key, value);
    setTimeout(() => {
      if (customSelectState.pendingValues.get(key) === value) {
        customSelectState.pendingValues.delete(key);
      }
    }, 0);
  });
  select.addEventListener("invalid", () => openCustomSelect(select));
}

function syncCustomSelect(select) {
  enhanceCustomSelect(select);
  const wrapper = select.closest(".fmodd-select");
  const trigger = wrapper?.querySelector(".fmodd-select-trigger");
  if (!wrapper || !trigger) return;
  const pendingKey = customSelectKey(select);
  const pendingValue = customSelectState.pendingValues.get(pendingKey);
  if (pendingValue !== undefined) {
    if ([...select.options].some((option) => option.value === pendingValue)) {
      select.value = pendingValue;
    }
    customSelectState.pendingValues.delete(pendingKey);
  }
  const selected = select.selectedOptions[0];
  const previewFamily = customSelectFontPreviewFamily(select, selected);
  const open = customSelectState.openKey === customSelectKey(select);
  const selectedText = selected?.textContent || uiText("shell.select.placeholder");
  const ariaLabel = select.getAttribute("aria-label") || selected?.textContent || uiText("shell.select.aria");
  const previous = customSelectState.renderStates.get(select);
  if (
    previous
    && previous.value === String(select.value)
    && previous.selectedText === selectedText
    && previous.disabled === Boolean(select.disabled)
    && previous.open === open
    && previous.ariaLabel === ariaLabel
    && previous.previewFamily === previewFamily
  ) return;
  trigger.querySelector(".fmodd-select-value").textContent = selectedText;
  trigger.classList.toggle("font-preview-trigger", Boolean(previewFamily));
  if (previewFamily) trigger.style.setProperty("--font-preview-family", previewFamily);
  else trigger.style.removeProperty("--font-preview-family");
  trigger.disabled = select.disabled;
  trigger.title = selected?.textContent || "";
  wrapper.classList.toggle("open", open);
  trigger.setAttribute("aria-expanded", String(open));
  trigger.setAttribute("aria-label", ariaLabel);
  customSelectState.renderStates.set(select, {
    value:String(select.value), selectedText, disabled:Boolean(select.disabled), open, ariaLabel, previewFamily,
  });
}

function customSelectsWithin(root = document) {
  const selects = new Set();
  if (root?.matches?.("select")) selects.add(root);
  root?.querySelectorAll?.("select").forEach((select) => selects.add(select));
  const owner = root?.matches?.("option, optgroup") ? root.closest("select") : null;
  if (owner) selects.add(owner);
  return selects;
}

function syncCustomSelects(root = document) {
  const selects = customSelectsWithin(root);
  selects.forEach(syncCustomSelect);
  const select = activeCustomSelect();
  if (select) {
    if (root === document || selects.has(select)) renderCustomSelectMenu(select);
  } else if (customSelectState.openKey) closeCustomSelect();
}

function queueCustomSelectSync(roots) {
  for (const root of roots || []) {
    if (root) customSelectState.pendingRoots.add(root);
  }
  if (customSelectState.syncQueued) return;
  customSelectState.syncQueued = true;
  queueMicrotask(() => {
    customSelectState.syncQueued = false;
    const pendingRoots = [...customSelectState.pendingRoots];
    customSelectState.pendingRoots.clear();
    pendingRoots.forEach((root) => {
      if (root === document || root.isConnected) syncCustomSelects(root);
    });
    if (customSelectState.openKey && !activeCustomSelect()) closeCustomSelect();
  });
}

function customSelectMutationRoots(mutations) {
  const roots = new Set();
  mutations.forEach((mutation) => {
    if (mutation.target.closest?.(".fmodd-select-menu")) return;
    if (mutation.type === "attributes") {
      if (mutation.target.matches?.("select, option, optgroup")) roots.add(mutation.target);
      return;
    }
    const owner = mutation.target.matches?.("select, option, optgroup")
      ? mutation.target.closest("select") : null;
    if (owner) roots.add(owner);
    mutation.addedNodes.forEach((node) => {
      if (node.nodeType === Node.ELEMENT_NODE && (node.matches?.("select, option, optgroup") || node.querySelector?.("select"))) {
        roots.add(node);
      }
    });
  });
  return roots;
}

function initializeCustomSelects() {
  ensureCustomSelectMenu();
  syncCustomSelects();
  customSelectState.observer = new MutationObserver((mutations) => {
    const roots = customSelectMutationRoots(mutations);
    if (roots.size) queueCustomSelectSync(roots);
  });
  customSelectState.observer.observe(document.body, {
    childList:true,
    subtree:true,
    attributes:true,
    attributeFilter:["disabled", "hidden", "label", "selected", "value"],
  });
  document.addEventListener("change", (event) => {
    if (event.target.matches?.("select")) syncCustomSelect(event.target);
  });
  document.addEventListener("click", (event) => {
    const label = event.target.closest?.("label");
    const labeledControl = label && (
      label.querySelector(":scope > .fmodd-select > select")
      || (label.htmlFor ? document.getElementById(label.htmlFor) : null)
    );
    const select = labeledControl?.matches?.("select") ? labeledControl : null;
    if (select && !event.target.closest(".fmodd-select")) {
      event.preventDefault();
      openCustomSelect(select);
      select.closest(".fmodd-select")?.querySelector(".fmodd-select-trigger")?.focus();
      return;
    }
    if (!event.target.closest?.(".fmodd-select, .fmodd-select-menu")) closeCustomSelect();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && customSelectState.openKey) closeCustomSelect({restoreFocus:true});
  });
  document.addEventListener("pointerup", () => {
    if (!customSelectState.menuInteracting) return;
    setTimeout(() => {
      customSelectState.menuInteracting = false;
      const select = activeCustomSelect();
      if (select) renderCustomSelectMenu(select);
    }, 0);
  }, {passive:true});
  window.addEventListener("resize", () => {
    const select = activeCustomSelect();
    if (select) positionCustomSelectMenu(select);
  }, {passive:true});
  document.addEventListener("scroll", () => {
    const select = activeCustomSelect();
    if (select) positionCustomSelectMenu(select);
  }, {capture:true, passive:true});
}

const round = (value) => Math.round((value + Number.EPSILON) * 100) / 100;
const moneySettings = () => app.state?.settings || {};
const moneyRate = () => Number(moneySettings().money_rate || 1);
const moneySymbol = () => String(moneySettings().money_symbol || "£");
const moneyDecimalDigits = () => Math.max(0, Math.min(2, Number(moneySettings().money_decimal_digits ?? 2)));
const toDisplayMoney = (value) => Number(value || 0) * moneyRate();
const toInternalMoney = (value) => round(Number(value || 0) / moneyRate());
const purchaseMoneyScale = () => Number(moneySettings().purchase_money_scale || 1);
const toPurchaseInternalMoney = (value) => round(
  Number(value || 0) * purchaseMoneyScale() / moneyRate(),
);
const toSpendableDisplayMoney = (value) => {
  const scale = 10 ** moneyDecimalDigits();
  return Math.floor((toDisplayMoney(value) + Number.EPSILON) * scale) / scale;
};
const availableWalletBalance = () => {
  const economyBalance = Number(app.state?.economy?.casino_balance);
  if (Number.isFinite(economyBalance)) return Math.max(0, economyBalance);
  const stateBalance = Number(app.state?.balance);
  return Number.isFinite(stateBalance) ? Math.max(0, stateBalance) : 0;
};
const defaultBetMaxProfit = (mode) => Number(
  moneySettings()[mode === "single" ? "default_betting_limit_single" : "default_betting_limit_parlay"]
  || DEFAULT_BET_MAX_PROFIT[mode === "single" ? "single" : "parlay"]
);
const keyOf = (selection) => [selection.fixture_date, selection.competition_id, selection.home_id, selection.away_id, selection.market, selection.selection_code, selection.line ?? ""].join("|");
const selectionMatchKey = (selection) => [selection.fixture_date, selection.competition_id, selection.home_id, selection.away_id].join("|");
const formatOdds = (value, market = "") => {
  const odds = Number(value || 0);
  if (!Number.isFinite(odds)) return "-";
  if (market && odds > 5) return odds.toFixed(1);
  return odds.toFixed(2);
};
const formatAsianLine = (value) => {
  const line = Number(value);
  if (!Number.isFinite(line)) return "-";
  if (Math.abs(line) < 0.001) return "0";
  const absolute = Math.abs(line);
  const decimals = Number.isInteger(absolute) ? 0 : Number.isInteger(absolute * 2) ? 1 : 2;
  return `${line > 0 ? "+" : "-"}${absolute.toFixed(decimals)}`;
};
const formatGoalLine = (value) => {
  const line = Number(value);
  if (!Number.isFinite(line)) return "-";
  if (Number.isInteger(line)) return line.toFixed(0);
  return Number.isInteger(line * 2) ? line.toFixed(1) : line.toFixed(2);
};
const formatFullMoney = (value) => {
  const amount = toDisplayMoney(value);
  const digits = moneyDecimalDigits();
  return `${moneySymbol()}${amount.toLocaleString(activeUiLocale(), {minimumFractionDigits:digits, maximumFractionDigits:digits})}`;
};
const MONEY_ABBREVIATION_UNITS = Object.freeze([
  [1e30, "Q"],
  [1e27, "R"],
  [1e24, "Y"],
  [1e21, "Z"],
  [1e18, "E"],
  [1e15, "P"],
  [1e12, "T"],
  [1e9, "B"],
  [1e6, "M"],
  [1e3, "K"],
]);
const MONEY_ABBREVIATION_MULTIPLIERS = Object.freeze(Object.fromEntries(
  MONEY_ABBREVIATION_UNITS.map(([threshold, suffix]) => [suffix, threshold]),
));
const moneyAbbreviationUnit = (value) => (
  MONEY_ABBREVIATION_UNITS.find(([threshold]) => Math.abs(Number(value)) >= threshold) || null
);
const formatGlobalStatisticMoney = (value) => {
  const internalAmount = Number(value || 0);
  const amount = toDisplayMoney(internalAmount);
  const absolute = Math.abs(amount);
  const unit = moneyAbbreviationUnit(absolute);
  if (!unit) return formatFullMoney(internalAmount);
  const number = (absolute / unit[0]).toLocaleString(activeUiLocale(), {minimumFractionDigits:1, maximumFractionDigits:1});
  return `${amount < 0 ? "-" : ""}${moneySymbol()}${number}${unit[1]}`;
};
const formatMoney = (value) => {
  const internalAmount = Number(value || 0);
  const amount = toDisplayMoney(internalAmount);
  if (!app.compactMoney) return formatFullMoney(internalAmount);
  const absolute = Math.abs(amount);
  const unit = moneyAbbreviationUnit(absolute);
  if (!unit) return formatFullMoney(internalAmount);
  const compact = absolute / unit[0];
  const number = compact.toLocaleString(activeUiLocale(), {minimumFractionDigits:1, maximumFractionDigits:1});
  return `${amount < 0 ? "-" : ""}${moneySymbol()}${number}${unit[1]}`;
};
const formatCompactMoney = (value, fractionDigits = 1) => {
  const internalAmount = Number(value || 0);
  const amount = toDisplayMoney(internalAmount);
  const absolute = Math.abs(amount);
  const unit = moneyAbbreviationUnit(absolute);
  if (!unit) return formatFullMoney(internalAmount);
  const compact = absolute / unit[0];
  const number = compact.toLocaleString(activeUiLocale(), {minimumFractionDigits:fractionDigits, maximumFractionDigits:fractionDigits});
  return `${amount < 0 ? "-" : ""}${moneySymbol()}${number}${unit[1]}`;
};
const formatChartAxisMoney = (value, scaleValue = value) => {
  const internalAmount = Number(value || 0);
  const amount = toDisplayMoney(internalAmount);
  const scale = Math.abs(toDisplayMoney(Number(scaleValue || 0)));
  const unit = moneyAbbreviationUnit(scale);
  if (!unit) return formatFullMoney(internalAmount);
  const scaled = amount / unit[0];
  const rounded = Math.abs(scaled) < .05 ? 0 : scaled;
  const number = Math.abs(rounded).toLocaleString(activeUiLocale(), {minimumFractionDigits:1, maximumFractionDigits:1});
  return `${rounded < 0 ? "-" : ""}${moneySymbol()}${number}${unit[1]}`;
};
const formatPounds = formatMoney;

function economyFundingSnapshot() {
  const economy = app.state?.economy || {};
  const bank = Math.max(0, Number(economy.bank_balance || 0));
  const wallet = Math.max(0, Number(economy.casino_balance || 0));
  const reportedTotal = Number(economy.total_balance);
  const total = Number.isFinite(reportedTotal) ? Math.max(0, reportedTotal) : bank + wallet;
  return {bank, wallet, total};
}

const EMPTY_ECONOMY_DATA = {catalog:[], inventory:[], transactions:[]};
function economyData() { return app.state?.economy || EMPTY_ECONOMY_DATA; }
function economyDataIndex() {
  const economy = economyData();
  if (app.economyIndexSource === economy && app.economyIndex) return app.economyIndex;
  const catalogBySku = new Map();
  const descriptionsBySku = new Map();
  for (const product of economy.catalog || []) {
    if (!catalogBySku.has(product.sku)) catalogBySku.set(product.sku, product);
    if (!descriptionsBySku.has(product.sku)) {
      descriptionsBySku.set(product.sku, product.description);
    }
  }
  const inventoryById = new Map();
  const availableBySku = new Map();
  const available = [];
  const inUse = [];
  const stackedAvailable = new Map();
  for (const item of economy.inventory || []) {
    if (!inventoryById.has(item.id)) inventoryById.set(item.id, item);
    if (item.status === "available") {
      available.push(item);
      const skuRows = availableBySku.get(item.sku) || [];
      skuRows.push(item);
      availableBySku.set(item.sku, skuRows);
      const stackKey = String(item.sku || item.name || item.id);
      const stack = stackedAvailable.get(stackKey);
      if (stack) stack.quantity += 1;
      else stackedAvailable.set(stackKey, {...item, quantity:1});
    } else if (["scheduled", "active"].includes(item.status)) {
      inUse.push(item);
    }
  }
  app.economyIndexSource = economy;
  app.economyIndex = {
    catalogBySku, descriptionsBySku, inventoryById, availableBySku,
    available, inUse, availableStacks:[...stackedAvailable.values()],
  };
  return app.economyIndex;
}
function shopProduct(sku) { return economyDataIndex().catalogBySku.get(sku) || null; }
function economyItem(itemId) { return economyDataIndex().inventoryById.get(itemId) || null; }
function availableEconomyItems(sku) { return economyDataIndex().availableBySku.get(sku) || []; }
function localizedItemField(item, field) {
  const sku = String(item?.sku || "").trim();
  const key = sku ? `item.${sku}.${field}` : "";
  const translated = key ? uiText(key) : "";
  if (translated && translated !== key) return translated;
  return String(item?.[field] || (field === "name" ? sku : ""));
}
function localizedItemName(item) { return localizedItemField(item, "name"); }
function localizedItemDescription(item) { return localizedItemField(item, "description"); }
function localizedItemTier(tier) {
  const key = ITEM_TIER_LABEL_KEYS[String(tier || "")] || "";
  return key ? uiText(key) : String(tier || "");
}
function moneyRenderSignature() {
  return [moneySymbol(), moneyRate(), moneyDecimalDigits(), Boolean(app.compactMoney)].join("|");
}

function fundingPaymentSplit(price) {
  const amount = Math.max(0, Number(price || 0));
  const funding = economyFundingSnapshot();
  const bank = Math.min(funding.bank, amount);
  return {...funding, price:amount, bank, wallet:Math.max(0, amount - bank)};
}

function renderFundingSummary(target, {recurringAmount = null, recurringLabel = uiText("funding.daily_spend")} = {}) {
  const root = typeof target === "string" ? $(target) : target;
  if (!root) return;
  const {bank, wallet, total} = economyFundingSnapshot();
  const recurring = recurringAmount == null
    ? ""
    : `<span class="funding-summary-recurring">${escapeHtml(uiText("funding.recurring", {label:uiLegacy(recurringLabel), amount:formatPounds(Math.max(0, Number(recurringAmount || 0)))}))}</span>`;
  root.classList.add("funding-summary");
  root.innerHTML = `<span class="funding-summary-total"><small>${uiText("funding.available")}</small><strong>${formatPounds(total)}</strong></span><span class="funding-summary-sources"><b>${uiText("funding.bank", {amount:formatPounds(bank)})}</b><b>${uiText("funding.wallet", {amount:formatPounds(wallet)})}</b></span>${recurring}`;
}

const formatBettingLimitInput = (value) => {
  const amount = round(toDisplayMoney(value));
  const compact = (unit, suffix) => `${(amount / unit).toFixed(1)}${suffix}`;
  const unit = MONEY_ABBREVIATION_UNITS.find(([threshold]) => (
    amount >= threshold && amount % threshold === 0
  ));
  if (unit) return compact(unit[0], unit[1]);
  return String(amount);
};
const parseBettingLimitInput = (value) => {
  const normalized = String(value || "").trim().replaceAll(",", "").toUpperCase();
  const match = normalized.match(/^(\d+(?:\.\d+)?)\s*([KMBTPEZYRQ]?)$/);
  if (!match) return 0;
  const multiplier = match[2] ? MONEY_ABBREVIATION_MULTIPLIERS[match[2]] : 1;
  const amount = Number(match[1]) * multiplier;
  return Number.isFinite(amount) && amount > 0 ? toInternalMoney(amount) : 0;
};
const formatFixtureTime = (item) => {
  const date = String(item?.fixture_date || "-").replaceAll("-", "/");
  let time = String(item?.kickoff_time || "").trim();
  const minutes = Number(item?.kickoff_minutes);
  if (!time && item?.kickoff_minutes != null && Number.isFinite(minutes) && minutes >= 0) {
    time = `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
  }
  return `${date} ${time || uiText("time.tbc")}`;
};

function loadLegacyFavoriteTeamIds() {
  try {
    const values = JSON.parse(localStorage.getItem("fm-odds-favorite-teams") || "[]");
    return new Set(Array.isArray(values) ? values.map(Number).filter(Number.isFinite) : []);
  } catch (_error) {
    return new Set();
  }
}

const legacyFavoriteTeamIds = loadLegacyFavoriteTeamIds();
const legacyFavoriteMarketKeys = new Set(storedFavoriteMarkets());

function rememberActionControl(control) {
  if (!(control instanceof HTMLButtonElement) || control.disabled) return;
  app.lastActionControl = control;
  app.lastActionControlAt = performance.now();
}

document.addEventListener("click", (event) => {
  rememberActionControl(event.target.closest?.("button"));
}, true);

document.addEventListener("submit", (event) => {
  rememberActionControl(event.submitter);
}, true);

function beginMutationRequestFeedback() {
  const control = app.lastActionControl;
  const recent = performance.now() - Number(app.lastActionControlAt || 0) < 1500;
  app.lastActionControl = null;
  app.lastActionControlAt = 0;
  if (!recent || !control?.isConnected || control.getAttribute("aria-busy") === "true") {
    return () => {};
  }
  const originallyDisabled = control.disabled;
  control.disabled = true;
  control.dataset.requestBusy = "true";
  control.setAttribute("aria-busy", "true");
  control.classList.add("request-busy");
  return () => {
    if (control.dataset.requestBusy !== "true") return;
    delete control.dataset.requestBusy;
    control.classList.remove("request-busy");
    control.removeAttribute("aria-busy");
    control.disabled = originallyDisabled;
  };
}

const INSTANT_CLICK_FEEDBACK_SELECTOR = [
  "button", "a[href]", "[role=button]", "summary", "label[for]",
  "input[type=checkbox]", "input[type=radio]", "[tabindex]:not([tabindex='-1'])",
  "[data-match]", "[data-click-feedback]",
].join(",");
const instantClickFeedbackTimers = new WeakMap();

function instantClickFeedbackControl(target) {
  const control = target?.closest?.(INSTANT_CLICK_FEEDBACK_SELECTOR);
  if (!control || control.matches(":disabled,[aria-disabled='true']")) return null;
  return control;
}

function showInstantClickFeedback(control) {
  if (!control) return;
  const previousTimer = instantClickFeedbackTimers.get(control);
  if (previousTimer) clearTimeout(previousTimer);
  control.classList.add("instant-click-feedback");
  instantClickFeedbackTimers.set(control, setTimeout(() => {
    control.classList.remove("instant-click-feedback");
    instantClickFeedbackTimers.delete(control);
  }, 140));
}

function initializeInstantClickFeedback() {
  document.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    showInstantClickFeedback(instantClickFeedbackControl(event.target));
  }, {capture:true, passive:true});
  document.addEventListener("keydown", (event) => {
    if (event.repeat || !["Enter", " "].includes(event.key)) return;
    showInstantClickFeedback(instantClickFeedbackControl(event.target));
  }, true);
}

