function loadOperationRecords() {
  try {
    const parsed = JSON.parse(localStorage.getItem(OPERATION_LOG_STORAGE_KEY) || "[]");
    if (!Array.isArray(parsed)) return [];
    let changed = false;
    const records = parsed.slice(0, OPERATION_LOG_LIMIT).map((row) => {
      if (row?.status !== "running") return row;
      changed = true;
      return {...row, status:"interrupted", finished_at:new Date().toISOString(), detail:uiText("operations.unconfirmed_detail")};
    }).filter((row) => row && row.id && row.title && row.started_at);
    if (changed) localStorage.setItem(OPERATION_LOG_STORAGE_KEY, JSON.stringify(records));
    return records;
  } catch (_error) {
    return [];
  }
}

const OPERATION_ROUTE_LABELS = [
  [/^\/api\/connect$/, "operations.route.connect", "operations.location.connect"],
  [/^\/api\/save-account\/merge-same-manager$/, "operations.route.merge_accounts", "operations.location.save_account"],
  [/^\/api\/refresh\/full$/, "operations.route.refresh_save", "operations.location.settings_markets"],
  [/^\/api\/refresh$/, "operations.route.refresh_markets", "operations.location.markets_refresh"],
  [/^\/api\/club\/refresh$/, "operations.route.refresh_club", "operations.location.club_details"],
  [/^\/api\/world-clubs\/scan$/, "operations.route.scan_world_clubs", "operations.location.world_club_directory"],
  [/^\/api\/world-clubs\/owned-refresh$/, "operations.route.refresh_group", "operations.location.group_details"],
  [/^\/api\/world-clubs\/finance-transfer$/, "operations.route.transfer_club_funds", "operations.location.group_funds"],
  [/^\/api\/shop\/buy-batch$/, "operations.route.buy_shop_items", "operations.location.shop_cart"],
  [/^\/api\/training\/purchase$/, "operations.route.buy_training_equipment", "operations.location.training_equipment"],
  [/^\/api\/training\/floor\/purchase$/, "operations.route.unlock_training_floor", "operations.location.training_floor"],
  [/^\/api\/training\/(?:place|store|sell)$/, "operations.route.manage_training_equipment", "operations.location.training_equipment"],
  [/^\/api\/training\/run$/, "operations.route.arrange_training", "operations.location.training_tasks"],
  [/^\/api\/training\/cancel$/, "operations.route.cancel_training", "operations.location.training_tasks"],
  [/^\/api\/activity\/centre\/purchase$/, "operations.route.unlock_activity_centre", "operations.location.activity_floor"],
  [/^\/api\/activity\/facility\/purchase$/, "operations.route.buy_activity_facility", "operations.location.activity_facilities"],
  [/^\/api\/activity\/language-learning$/, "operations.route.learn_player_language", "operations.location.activity_language"],
  [/^\/api\/activity(?:\/|$)/, "operations.route.run_player_activity", "operations.location.activity_players"],
  [/^\/api\/hospital\/treatment$/, "operations.route.adjust_treatment", "operations.location.medical_treatment"],
  [/^\/api\/canteen\/plan$/, "operations.route.switch_canteen_plan", "operations.location.canteen_plan"],
  [/^\/api\/canteen\/sea-cucumbers?$/, "operations.route.grant_sea_cucumber", "operations.location.canteen_rewards"],
  [/^\/api\/inventory\//, "operations.route.manage_inventory", "operations.location.inventory"],
  [/^\/api\/world-clubs\//, "operations.route.run_group_operation", "operations.location.group_operations"],
  [/^\/api\/bank\/(?!default-notice)/, "operations.route.run_fund_operation", "operations.location.bank_operations"],
  [/^\/api\/salary\/schedule$/, "operations.route.schedule_salary", "operations.location.salary"],
  [/^\/api\/league-points\//, "operations.route.adjust_league_points", "operations.location.league_points"],
];

const DEFERRED_OPERATION_PATHS = new Set([
  "/api/connect",
  "/api/refresh",
  "/api/refresh/full",
]);

function operationRouteTitle(path) {
  const cleanPath = String(path || "").split("?")[0];
  const key = OPERATION_ROUTE_LABELS.find(([pattern]) => pattern.test(cleanPath))?.[1];
  return key ? uiText(key) : "";
}

function operationRouteLocation(path) {
  const cleanPath = String(path || "").split("?")[0];
  const key = OPERATION_ROUTE_LABELS.find(([pattern]) => pattern.test(cleanPath))?.[2];
  return key ? uiText(key) : "";
}

function persistOperationRecords() {
  app.operationRecords = (app.operationRecords || []).slice(0, OPERATION_LOG_LIMIT);
  try {
    localStorage.setItem(OPERATION_LOG_STORAGE_KEY, JSON.stringify(app.operationRecords));
  } catch (_error) {
    // The in-memory log remains usable when WebView storage is unavailable.
  }
}

let operationRecordPersistenceQueued = false;
function scheduleOperationRecordPersistence() {
  if (operationRecordPersistenceQueued) return;
  operationRecordPersistenceQueued = true;
  queueMicrotask(() => {
    operationRecordPersistenceQueued = false;
    persistOperationRecords();
  });
}

function beginOperationRecord(path, method) {
  const title = operationRouteTitle(path);
  if (!title) return null;
  const record = {
    id:`${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    title,
    location:operationRouteLocation(path),
    path:String(path || "").split("?")[0],
    method,
    status:"running",
    started_at:new Date().toISOString(),
    finished_at:null,
    detail:"",
    scope_id:String(app.state?.data_scope_id || ""),
    save_name:String(output()?.save_name || uiText("shell.not_connected")),
  };
  app.operationRecords.unshift(record);
  scheduleOperationRecordPersistence();
  renderOperationRecords({visibleOnly:true});
  renderTopbarRefreshStatus();
  return record.id;
}

function finishOperationRecord(recordId, status, detail = "") {
  if (!recordId) return;
  const record = app.operationRecords.find((row) => row.id === recordId);
  if (!record) return;
  record.status = status;
  record.finished_at = new Date().toISOString();
  record.detail = String(detail || "").slice(0, 240);
  scheduleOperationRecordPersistence();
  renderOperationRecords({visibleOnly:true});
  renderTopbarRefreshStatus();
}

function finishAcceptedOperationRecord(recordId, path, payload) {
  const cleanPath = String(path || "").split("?")[0];
  if (!DEFERRED_OPERATION_PATHS.has(cleanPath)) {
    finishOperationRecord(recordId, "success", payload?.message || "");
    return;
  }
  if (payload?.started === true) return;
  finishOperationRecord(
    recordId,
    "interrupted",
    payload?.message || uiText("operations.background_not_started"),
  );
}

function reconcileDeferredOperationRecords(state = app.state) {
  const records = (app.operationRecords || []).filter(
    (record) => record.status === "running" && DEFERRED_OPERATION_PATHS.has(record.path),
  );
  if (!records.length || !state) return;
  const busy = Boolean(state.refreshing || state.reconciling || state.connection_pending);
  const connection = state.connection || {};
  records.forEach((record) => {
    if (busy) return;
    if (record.path === "/api/connect") {
      if (connection.connected) {
        finishOperationRecord(record.id, "success", uiText("operations.connection_success"));
      } else {
        finishOperationRecord(
          record.id,
          "failed",
          uiText("operations.connection_incomplete"),
        );
      }
      return;
    }
    if (state.error) {
      finishOperationRecord(record.id, "failed", uiText("refresh.status_failed"));
    } else {
      finishOperationRecord(record.id, "success", uiText("operations.refresh_completed"));
    }
  });
}

function refreshRequiredMessage(message) {
  return /请(?:先)?[^。！？\n]{0,30}(?:刷新|扫描)|请.*(?:重新扫描|刷新后重试)|已变化.*(?:刷新|重试)|地址已失效/.test(
    String(message || ""),
  );
}

function refreshIsSafeToRetry(message) {
  return /请(?:先)?[^。！？\n]{0,30}(?:刷新|扫描)|尚未读取|尚未识别|地址已失效|重新扫描/.test(
    String(message || ""),
  ) && !/已变化.*(?:刷新|重试)|刷新后重试/.test(String(message || ""));
}

async function ensureOddsDataRefresh() {
  let status = await request("/api/refresh/status");
  if (!status.refreshing && !status.reconciling) {
    await request("/api/refresh", {
      method: "POST", headers: {"Content-Type": "application/json"}, body: "{}",
    });
  }
  for (let attempt = 0; attempt < 180; attempt += 1) {
    status = await request("/api/refresh/status");
    if (!status.refreshing && !status.reconciling) {
      if (status.error) throw new Error(status.error);
      await loadState({fresh:true});
      return status;
    }
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  throw new Error(uiText("refresh.timeout"));
}

async function refreshForRequestError(path, message) {
  if (app.autoRefreshRecovery) return false;
  app.autoRefreshRecovery = true;
  const text = String(message || "");
  try {
    if (path === "/api/state" || path.startsWith("/api/refresh")) return false;
    if (/盘口|赔率|比赛日期/.test(text)) {
      await ensureOddsDataRefresh();
      return true;
    }
    if (/世界数据|世界国家|世界俱乐部|重新扫描世界|扫描俱乐部|俱乐部地址/.test(text)) {
      await ensureWorldDataScan();
      return true;
    }
    if (/队伍|球队|球员|职员|执教俱乐部/.test(text)) {
      // A precondition error means the currently held roster snapshot is
      // stale, so wait for a real forced refresh before retrying the request.
      await ensureManagedRostersLoaded(true, true);
      return true;
    }
    await loadState({fresh:true});
    return true;
  } finally {
    app.autoRefreshRecovery = false;
  }
}

async function request(path, options = {}) {
  const fetchOptions = {...options};
  const autoRefreshRetry = Boolean(fetchOptions.__autoRefreshRetry);
  const skipAutoRefresh = Boolean(fetchOptions.__skipAutoRefresh);
  const backgroundRead = Boolean(fetchOptions.__backgroundRead);
  delete fetchOptions.__autoRefreshRetry;
  delete fetchOptions.__skipAutoRefresh;
  delete fetchOptions.__backgroundRead;
  const requestHeaders = new Headers(fetchOptions.headers || {});
  if (!requestHeaders.has("X-FMODD-Locale")) requestHeaders.set("X-FMODD-Locale", activeUiLocale());
  fetchOptions.headers = requestHeaders;
  const method = String(fetchOptions.method || "GET").toUpperCase();
  const readOnlyPreview = path === "/api/inventory/reallocate-attributes/preview";
  const mutating = !readOnlyPreview && !backgroundRead
    && !["GET", "HEAD", "OPTIONS"].includes(method);
  const mutationKey = mutating
    ? `${method}:${path}:${String(fetchOptions.body || "")}`
    : "";
  if (mutationKey && !autoRefreshRetry && app.mutationRequestsInFlight.has(mutationKey)) {
    app.lastActionControl = null;
    app.lastActionControlAt = 0;
    throw new Error(uiText("request.in_progress"));
  }
  const finishFeedback = mutating ? beginMutationRequestFeedback() : () => {};
  const operationRecordId = mutating ? beginOperationRecord(path, method) : null;
  if (mutationKey) app.mutationRequestsInFlight.add(mutationKey);
  const defaultTimeoutMs = path === "/api/state"
    ? 60000
    : path === "/api/training/run"
      ? 60000
    : path.startsWith("/api/inventory/")
      ? 30000
      : !mutating ? 30000 : 0;
  const timeoutMs = Math.max(0, Number(fetchOptions.timeoutMs ?? defaultTimeoutMs) || 0);
  const timeoutMessage = String(fetchOptions.timeoutMessage || (
    path === "/api/state"
      ? uiText("request.state_timeout")
      : !mutating
        ? uiText("request.read_timeout")
        : uiText("request.mutation_timeout")
  ));
  delete fetchOptions.timeoutMs;
  delete fetchOptions.timeoutMessage;
  let timeoutId = null;
  let timedOut = false;
  if (timeoutMs > 0) {
    const controller = new AbortController();
    fetchOptions.signal = controller.signal;
    timeoutId = setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, timeoutMs);
  }
  try {
    const response = await fetch(path, fetchOptions);
    const contentType = response.headers.get("content-type") || "";
    let payload;
    if (contentType.includes("application/json")) {
      payload = await response.json();
    } else {
      throw new Error(uiText("request.invalid_response", {status:response.status}));
    }
    if (!response.ok) {
      const useSpecificLegacyDetail = Boolean(payload.error_detail_safe && payload.error);
      const displayMessage = useSpecificLegacyDetail
        ? localizeServerError(payload.error)
        : (payload.message || localizeServerError(payload.error));
      const error = new Error(String(displayMessage));
      error.code = payload.error_code || null;
      error.phase = payload.error_phase || null;
      error.retryable = Boolean(payload.retryable);
      error.operation = payload.operation || null;
      error.payload = payload;
      error.rawMessage = payload.error || null;
      throw error;
    }
    finishAcceptedOperationRecord(operationRecordId, path, payload);
    return payload;
  } catch (error) {
    if (timedOut) {
      const error = new Error(timeoutMessage || uiText("request.read_timeout"));
      error.code = "REQUEST_TIMEOUT";
      finishOperationRecord(operationRecordId, "interrupted", error.message);
      throw error;
    }
    const recoveryMessage = error instanceof Error
      ? String(error.rawMessage || error.message || "")
      : String(error || "");
    if (
      error instanceof Error
      && error.message !== "Failed to fetch"
      && !skipAutoRefresh
      && !autoRefreshRetry
      && !app.autoRefreshRecovery
      && refreshRequiredMessage(recoveryMessage)
    ) {
      try {
        await refreshForRequestError(path, recoveryMessage);
        if (refreshIsSafeToRetry(recoveryMessage)) {
          const retried = await request(path, {...options, __autoRefreshRetry:true});
          finishOperationRecord(operationRecordId, "success", uiText("request.retry_success"));
          return retried;
        }
        error.message = uiText("request.refresh_required");
      } catch (refreshError) {
        error.message = uiText("request.refresh_failed", {error:refreshError.message || refreshError});
      }
    }
    if (error instanceof Error && error.message !== "Failed to fetch") {
      finishOperationRecord(operationRecordId, "failed", error.message);
      throw error;
    }
    // Browsers expose a network outage as the English "Failed to fetch".
    const connectionError = new Error(uiText("request.service_unavailable"));
    finishOperationRecord(operationRecordId, "failed", connectionError.message);
    throw connectionError;
  } finally {
    if (timeoutId !== null) clearTimeout(timeoutId);
    if (mutationKey) app.mutationRequestsInFlight.delete(mutationKey);
    finishFeedback();
  }
}

function localizeServerError(message) {
  const text = String(message || "").trim();
  if (!text) return uiText("request.failed");
  const translations = {
    "insufficient available balance":uiText("request.insufficient_balance"),
    "stake must be greater than zero":uiText("request.stake_zero"),
    "invalid half-time exact-score selection":uiText("request.invalid_half_time_score"),
    "invalid exact-score selection":uiText("request.invalid_exact_score"),
    "unknown endpoint":uiText("request.unknown_endpoint"),
  };
  if (translations[text]) return translations[text];
  const unsupportedMarket = text.match(/^unsupported market:\s*(.+)$/i);
  if (unsupportedMarket) return uiText("request.unsupported_market", {market:unsupportedMarket[1]});
  // Preserve the original backend detail. Player-movement failures often come
  // from Windows or a version-specific native validation and hiding the English
  // text makes failures on another machine impossible to classify.
  if (/^[\x00-\x7F]+$/.test(text) && /[A-Za-z]/.test(text)) {
    return uiText("request.operation_failed", {detail:text});
  }
  return text;
}

function statePatchMatchesCurrentState(response) {
  const sync = response?.state_sync;
  if (!app.state || !sync || !response?.state_patch) return false;
  return Number(sync.data_version) === Number(app.state.data_version)
    && String(sync.data_scope_id || "") === String(app.state.data_scope_id || "");
}

function accountPayloadMatchesCurrentState(payload) {
  const payloadScope = String(payload?.data_scope_id || "");
  const currentScope = String(app.state?.data_scope_id || "");
  return Boolean(payloadScope && currentScope && payloadScope === currentScope);
}

function dataResourceVersionKey(resource, state = app.state) {
  const data = state?.output || {};
  const values = [
    String(state?.data_scope_id || data.save_instance_id || ""),
    Number(state?.data_version || 0),
    String(state?.game_clock?.date || data.game_date || ""),
    String(data.game_layout || state?.connection?.game_layout || ""),
  ];
  if (resource === "club-legacy") {
    values.push(Number(state?.club_legacy_status?.revision || app.clubLegacyStatus?.revision || 0));
  }
  return values.join("|");
}

function dataPrewarmCycleKey(state = app.state) {
  const data = state?.output || {};
  const managed = Array.isArray(data.managed_teams) && data.managed_teams.length
    ? data.managed_teams : (data.managed_team ? [data.managed_team] : []);
  const teamIds = managed
    .map((team) => Number(team?.id || 0))
    .filter((teamId) => teamId > 0)
    .sort((left, right) => left - right);
  return [
    String(state?.data_scope_id || data.save_instance_id || ""),
    String(state?.game_clock?.date || data.game_date || ""),
    String(data.game_layout || state?.connection?.game_layout || ""),
    Number(data.selected_manager_id || data.manager?.id || 0),
    teamIds.join(","),
  ].join("|");
}

function pageDataVersionIsCurrent(resource) {
  return app.pageDataVersions.get(resource) === dataResourceVersionKey(resource);
}

function rememberPageDataVersion(resource) {
  app.pageDataVersions.set(resource, dataResourceVersionKey(resource));
}

function sharePageDataRequest(key, task) {
  const existing = app.pageDataRequests.get(key);
  if (existing) return existing;
  const pending = Promise.resolve().then(task);
  app.pageDataRequests.set(key, pending);
  pending.finally(() => {
    if (app.pageDataRequests.get(key) === pending) app.pageDataRequests.delete(key);
  }).catch(() => {});
  return pending;
}

function cancelDataPrewarm({clearVersions = false} = {}) {
  app.dataPrewarmGeneration += 1;
  clearTimeout(app.dataPrewarmTimer);
  clearTimeout(app.dataPrewarmIntentTimer);
  app.dataPrewarmTimer = null;
  app.dataPrewarmIntentTimer = null;
  app.dataPrewarmScheduledKey = "";
  app.dataPrewarmCompletedKey = "";
  app.dataPrewarmWorkKey = "";
  app.dataPrewarmPendingPages.clear();
  app.dataPrewarmRetryCounts.clear();
  app.dataPrewarmFailedPages.clear();
  app.pageDataRequests.clear();
  if (clearVersions) app.pageDataVersions.clear();
}

function dataPrewarmCanRun() {
  if (!isSaveConnected() || document.visibilityState === "hidden") return false;
  if (app.mutationRequestsInFlight?.size) return false;
  if (app.state?.save_change_pending) return false;
  return !app.state?.refreshing && (
    !app.state?.reconciling || Boolean(app.state?.background_reconcile_ready)
  );
}

function waitForDataPrewarmIdle() {
  return new Promise((resolve) => {
    if (typeof requestIdleCallback === "function") {
      requestIdleCallback(() => resolve(), {timeout:700});
    } else {
      setTimeout(resolve, 0);
    }
  });
}

async function preparePageData(page, {background = true, deep = true} = {}) {
  if (!isSaveConnected()) return false;
  if (["club", "activity", "hospital", "training", "canteen"].includes(page)) {
    if (managedRostersAreCurrent()) return true;
    const payload = await loadClub({silent:true, compact:true, background});
    const managed = output().managed_teams?.length || output().managed_team?.id;
    return !managed || Boolean(payload?.ready && !payload?.refreshing);
  }
  if (["world-clubs", "my-clubs"].includes(page)) {
    if (app.worldClubs?.ready && app.worldClubs?.native_scan?.ready
        && app.worldClubsScope === String(app.state?.data_scope_id || "")
        && pageDataVersionIsCurrent("world-clubs")) return true;
    const payload = await loadWorldClubs({page:app.worldClubPage || 1, background});
    return Boolean(payload?.ready && payload?.native_scan?.ready);
  }
  if (page === "world-nations") {
    if (app.worldNations?.ready && app.worldNations?.native_scan?.ready
        && app.worldNationsScope === String(app.state?.data_scope_id || "")
        && pageDataVersionIsCurrent("world-nations")) return true;
    const payload = await loadWorldNations({page:app.worldNationPage || 1, background});
    return Boolean(payload?.ready && payload?.native_scan?.ready);
  }
  if (page === "world-players") {
    if (app.worldPlayers?.ready && app.worldPlayersScope === String(app.state?.data_scope_id || "")
        && pageDataVersionIsCurrent("world-players")) return true;
    const payload = await loadWorldPlayers({
      page:app.worldPlayerPage || 1, background, hydrate:!background,
    });
    return Boolean(payload?.ready);
  }
  if (page === "hall-of-fame") {
    if (app.clubLegacyStatus?.refreshing) return false;
    if (!deep && app.clubLegacyLoadPromise) return true;
    const payload = await loadClubLegacyIndex({background, includeDetails:deep});
    return Boolean(payload);
  }
  if (page === "relations") {
    const scopes = await loadRelationScopes({background});
    if (!scopes) return false;
    if (!deep) return true;
    if (!managedRostersAreCurrent()) return false;
    if (relationState().scopeKind !== "managed") return true;
    const payload = await loadRelationNetwork({background});
    return Boolean(payload);
  }
  return true;
}

async function runDataPrewarm(generation, scopeKey) {
  app.dataPrewarmTimer = null;
  if (generation !== app.dataPrewarmGeneration || scopeKey !== dataPrewarmCycleKey()) return;
  if (!dataPrewarmCanRun()) {
    app.dataPrewarmScheduledKey = "";
    if (document.visibilityState === "hidden") return;
    scheduleDataPrewarm({delay:DATA_PREWARM_RETRY_MS, force:true});
    return;
  }
  for (const page of [...app.dataPrewarmPendingPages]) {
    await waitForDataPrewarmIdle();
    if (generation !== app.dataPrewarmGeneration || scopeKey !== dataPrewarmCycleKey()) return;
    if (!dataPrewarmCanRun()) {
      app.dataPrewarmScheduledKey = "";
      if (document.visibilityState !== "hidden") {
        scheduleDataPrewarm({delay:DATA_PREWARM_RETRY_MS, force:true});
      }
      return;
    }
    let ready = false;
    try {
      ready = await preparePageData(page, {background:true, deep:false});
    } catch (_error) { /* retain only this resource for a bounded retry */ }
    if (ready) {
      app.dataPrewarmPendingPages.delete(page);
      app.dataPrewarmRetryCounts.delete(page);
      app.dataPrewarmFailedPages.delete(page);
      continue;
    }
    const attempts = Number(app.dataPrewarmRetryCounts.get(page) || 0) + 1;
    app.dataPrewarmRetryCounts.set(page, attempts);
    if (attempts >= DATA_PREWARM_MAX_RETRIES) {
      app.dataPrewarmPendingPages.delete(page);
      app.dataPrewarmFailedPages.add(page);
    }
  }
  app.dataPrewarmScheduledKey = "";
  if (!app.dataPrewarmPendingPages.size) {
    app.dataPrewarmCompletedKey = scopeKey;
    return;
  }
  const nextAttempt = Math.min(...[...app.dataPrewarmPendingPages]
    .map((page) => Number(app.dataPrewarmRetryCounts.get(page) || 0) + 1));
  const retryDelay = Math.min(
    DATA_PREWARM_RETRY_MAX_MS,
    DATA_PREWARM_RETRY_MS * (2 ** Math.max(0, nextAttempt - 1)),
  );
  scheduleDataPrewarm({delay:retryDelay, force:true});
}

function scheduleDataPrewarm({delay = DATA_PREWARM_DELAY_MS, force = false} = {}) {
  if (!isSaveConnected()) return;
  const scopeKey = dataPrewarmCycleKey();
  if (!scopeKey) return;
  if (app.dataPrewarmWorkKey !== scopeKey) {
    app.dataPrewarmWorkKey = scopeKey;
    app.dataPrewarmPendingPages = new Set(DATA_PREWARM_PAGES);
    app.dataPrewarmRetryCounts.clear();
    app.dataPrewarmFailedPages.clear();
    app.dataPrewarmCompletedKey = "";
  }
  if (!force && (
    app.dataPrewarmCompletedKey === scopeKey
    || app.dataPrewarmScheduledKey === scopeKey
  )) return;
  clearTimeout(app.dataPrewarmTimer);
  app.dataPrewarmScheduledKey = scopeKey;
  const generation = app.dataPrewarmGeneration;
  app.dataPrewarmTimer = setTimeout(
    () => runDataPrewarm(generation, scopeKey), Math.max(0, Number(delay) || 0),
  );
}

function schedulePageIntentPrewarm(page, {strong = false} = {}) {
  if (!isSaveConnected()) return;
  clearTimeout(app.dataPrewarmIntentTimer);
  const generation = app.dataPrewarmGeneration;
  const delay = strong || !DATA_PREWARM_HEAVY_PAGES.has(page)
    ? DATA_PREWARM_INTENT_DELAY_MS : DATA_PREWARM_HEAVY_INTENT_DELAY_MS;
  app.dataPrewarmIntentTimer = setTimeout(() => {
    app.dataPrewarmIntentTimer = null;
    if (generation !== app.dataPrewarmGeneration || !dataPrewarmCanRun()) return;
    void preparePageData(page, {background:true, deep:true});
  }, delay);
}

function applyEconomySnapshot(economy, {merge = false, refreshBank = true} = {}) {
  if (!app.state || !economy) return false;
  app.state.economy = merge
    ? {...(app.state.economy || {}), ...economy}
    : economy;
  const walletBalance = Number(app.state.economy.casino_balance);
  if (Number.isFinite(walletBalance)) {
    app.state.balance = walletBalance;
    $("#balance").textContent = formatMoney(walletBalance);
    $("#wallet-dialog-balance").textContent = formatFullMoney(walletBalance);
  }
  if (refreshBank && app.page === "bank") renderBank();
  return true;
}

async function saveHiddenCompetitions() {
  if (!app.state?.data_scope_id) return false;
  const result = await request("/api/favorites/hidden-competitions", {
    method:"POST", headers:{"Content-Type":"application/json"},
    body:JSON.stringify({hidden_competitions:[...app.hiddenCompetitions.values()]}),
  });
  const hidden = (result.hidden_competitions || []).map((item) => ({
    id:Number(item.id), name:String(item.name || ""),
  })).filter((item) => Number.isFinite(item.id) && item.id > 0);
  app.hiddenCompetitions = new Map(hidden.map((item) => [item.id, item]));
  app.favoriteCompetitionIds = new Set(
    (result.favorite_competition_ids || []).map(Number).filter(Number.isFinite),
  );
  app.state.hidden_competitions = hidden;
  app.state.favorite_competition_ids = [...app.favoriteCompetitionIds];
  return true;
}

async function applyStatePatchOrReload(response) {
  if (!statePatchMatchesCurrentState(response)) {
    return loadState({fresh:true});
  }
  const patch = {...response.state_patch};
  if (patch.economy) {
    patch.economy = {...(app.state.economy || {}), ...patch.economy};
  }
  Object.assign(app.state, patch);
  if (patch.economy) applyEconomySnapshot(patch.economy, {refreshBank:false});
  renderCurrentPage();
  if (patch.mail && $("#mail-dialog")?.open) renderMail();
  renderIcons($(`#page-${app.page}`));
  return true;
}

function fmoddConfirm(message, confirmLabel = uiText("common.ok"), title = "FMODD") {
  const dialog = $("#fmodd-confirm-dialog");
  const messageNode = $("#fmodd-confirm-message");
  const defaultDetails = $("#credit-default-details");
  const waiverButton = $("#integrity-waive-fourth");
  const okButton = $("#fmodd-confirm-ok");
  const cancelButton = $("#fmodd-confirm-cancel");
  waiverButton.hidden = true;
  $("#fmodd-confirm-title").textContent = uiLegacy(title);
  cancelButton.hidden = false;
  messageNode.classList.remove("credit-default-message");
  messageNode.textContent = uiLegacy(message);
  defaultDetails.hidden = true;
  defaultDetails.open = false;
  okButton.textContent = uiLegacy(confirmLabel);
  cancelButton.textContent = uiText("common.cancel");
  okButton.type = "submit";
  okButton.value = "confirm";
  cancelButton.type = "submit";
  cancelButton.value = "cancel";
  dialog.returnValue = "";
  renderIcons();
  dialog.showModal();
  return new Promise((resolve) => {
    let finished = false;
    const form = okButton.form;
    const finish = (answer) => {
      if (finished) return;
      finished = true;
      form?.removeEventListener("submit", submitted);
      dialog.removeEventListener("close", closed);
      okButton.type = "button";
      cancelButton.type = "button";
      if (dialog.open) dialog.close();
      resolve(answer);
    };
    const submitted = (event) => {
      event.preventDefault();
      finish(event.submitter === okButton);
    };
    const closed = () => finish(false);
    form?.addEventListener("submit", submitted);
    dialog.addEventListener("close", closed);
  });
}

function fmoddPurchaseConfirm(item, payment) {
  const dialog = $("#fmodd-confirm-dialog");
  const messageNode = $("#fmodd-confirm-message");
  const cancelButton = $("#fmodd-confirm-cancel");
  const okButton = $("#fmodd-confirm-ok");
  const defaultDetails = $("#credit-default-details");
  const waiverButton = $("#integrity-waive-fourth");
  waiverButton.hidden = true;
  const price = Number(payment.price || 0);
  const rows = payment.free
    ? [[uiText("dialog.purchase.amount"), formatPounds(0)], [uiText("dialog.purchase.method"), uiText("dialog.purchase.free")], [uiText("dialog.purchase.total"), formatPounds(0)]]
    : [[uiText("dialog.purchase.amount"), formatPounds(price)], [uiText("funding.bank", {amount:formatPounds(payment.bank)})], [uiText("funding.wallet", {amount:formatPounds(payment.wallet)})], [uiText("dialog.purchase.total"), formatPounds(price)]];
  messageNode.classList.remove("credit-default-message");
  messageNode.classList.add("purchase-confirm-message");
  messageNode.innerHTML = `<span class="purchase-confirm-product">${escapeHtml(uiText("dialog.purchase.product", {name:item?.name || uiText("shop.product_fallback")}))}</span><span class="purchase-confirm-breakdown">${rows.map(([label, value], index) => `<span class="${index === rows.length - 1 ? "total" : ""}"><em>${escapeHtml(label)}</em><b>${escapeHtml(value)}</b></span>`).join("")}</span>`;
  defaultDetails.hidden = true;
  defaultDetails.open = false;
  cancelButton.hidden = false;
  okButton.textContent = uiText("dialog.purchase.confirm");
  cancelButton.textContent = uiText("common.cancel");
  renderIcons();
  dialog.showModal();
  return new Promise((resolve) => {
    let finished = false;
    const finish = (answer) => {
      if (finished) return;
      finished = true;
      okButton.removeEventListener("click", accept);
      cancelButton.removeEventListener("click", reject);
      dialog.removeEventListener("cancel", cancel);
      messageNode.classList.remove("purchase-confirm-message");
      if (dialog.open) dialog.close();
      resolve(answer);
    };
    const accept = () => finish(true);
    const reject = () => finish(false);
    const cancel = (event) => { event.preventDefault(); finish(false); };
    okButton.addEventListener("click", accept);
    cancelButton.addEventListener("click", reject);
    dialog.addEventListener("cancel", cancel);
  });
}

