const CREDIT_PENALTY_ATTRIBUTE_NAMES = {
  0x10:"credit.attribute.dribbling", 0x11:"credit.attribute.finishing", 0x15:"credit.attribute.off_ball", 0x16:"credit.attribute.passing", 0x19:"credit.attribute.vision",
  0x1A:"credit.attribute.handling", 0x1E:"credit.attribute.kicking", 0x21:"credit.attribute.decisions", 0x23:"credit.attribute.positioning", 0x24:"credit.attribute.reflexes",
  0x25:"credit.attribute.first_touch", 0x31:"credit.attribute.acceleration", 0x33:"credit.attribute.strength", 0x35:"credit.attribute.pace", 0x3A:"credit.attribute.bravery",
};

function localizedTrainingAttribute(attributeKey) {
  const source = String(attributeKey || "").split(":").pop();
  const messageKey = window.FMODDTrainingAttributeSourceKeys?.[source];
  if (!messageKey) return uiLegacy(source);
  const localized = uiText(messageKey);
  return localized === messageKey ? source : localized;
}

function localizedTrainingAttributeGroup(group) {
  const source = String(group || "");
  const messageKey = window.FMODDTrainingAttributeGroupSourceKeys?.[source];
  if (!messageKey) return uiLegacy(source);
  const localized = uiText(messageKey);
  return localized === messageKey ? source : localized;
}

function creditDefaultEffects(notice) {
  const attributes = new Map((notice.attribute_players || []).map((row) => [Number(row.id), row]));
  const injuries = new Map((notice.injury_players || []).map((row) => [Number(row.id), row]));
  return (notice.affected_players || []).map((player) => {
    const attribute = attributes.get(Number(player.id));
    const injury = injuries.get(Number(player.id));
    const changes = attribute ? Object.keys(attribute.before || {}).map((key) => {
      const nameKey = CREDIT_PENALTY_ATTRIBUTE_NAMES[Number(key)];
      const name = nameKey ? uiText(nameKey) : uiText("credit.attribute_fallback", {key});
      return `${name} ${Number(attribute.before[key])}→${Number(attribute.after?.[key])}`;
    }) : [];
    const parts = [];
    if (attribute) parts.push(`CA ${Number(attribute.ca_before)}→${Number(attribute.ca_after)}`, ...changes);
    if (injury) parts.push(uiText("credit.injury_penalty", {days:Number(injury.minimum_days || 30)}));
    return `<article><strong>${escapeHtml(player.name || uiText("credit.player_fallback", {id:player.id}))}</strong><span>${escapeHtml(parts.join(" · ") || uiText("credit.penalty_fallback"))}</span></article>`;
  }).join("");
}

