function fmoddIntegrityAlert(item) {
  const notice = item?.notice || item;
  const dialog = $("#fmodd-confirm-dialog");
  const cancelButton = $("#fmodd-confirm-cancel");
  const okButton = $("#fmodd-confirm-ok");
  const messageNode = $("#fmodd-confirm-message");
  const details = $("#credit-default-details");
  const waiverButton = $("#integrity-waive-fourth");
  $("#fmodd-confirm-title").textContent = uiText("integrity.committee");
  messageNode.classList.remove("credit-default-message", "purchase-confirm-message");
  messageNode.classList.add("integrity-notice-message");
  const body = localizedMailField(item || {}, "body") || uiText("integrity.fallback_body");
  messageNode.textContent = body;
  details.hidden = true;
  details.open = false;
  const waiver = notice?.penalty_waiver;
  waiverButton.hidden = !waiver?.available && !waiver?.paid;
  waiverButton.disabled = Boolean(waiver?.paid);
  waiverButton.textContent = waiver?.paid ? uiText("integrity.waiver_paid") : uiText("integrity.pay_waiver");
  okButton.textContent = uiText("common.confirm");
  cancelButton.hidden = true;
  renderIcons();
  dialog.showModal();
  return new Promise((resolve) => {
    const finish = () => {
      okButton.removeEventListener("click", finish);
      waiverButton.removeEventListener("click", payWaiver);
      dialog.removeEventListener("cancel", preventCancel);
      cancelButton.hidden = false;
      messageNode.classList.remove("integrity-notice-message");
      $("#fmodd-confirm-title").textContent = "FMODD";
      if (dialog.open) dialog.close();
      resolve();
    };
    const payWaiver = async () => {
      if (!waiver?.available || waiver?.paid) return;
      waiverButton.disabled = true;
      try {
        const response = await request("/api/mail/item-integrity/waive", {
          method:"POST", headers:{"Content-Type":"application/json"},
          body:JSON.stringify({mail_id:item?.id || notice?.id}),
        });
        applyEconomySnapshot(response.economy);
        waiver.available = false;
        waiver.paid = true;
        waiverButton.textContent = uiText("integrity.waiver_paid");
        toast(uiText("integrity.waiver_done"));
      } catch (error) {
        waiverButton.disabled = false;
        toast(error.message);
      }
    };
    const preventCancel = (event) => event.preventDefault();
    okButton.addEventListener("click", finish);
    waiverButton.addEventListener("click", payWaiver);
    dialog.addEventListener("cancel", preventCancel);
  });
}

