async function bootstrapState() {
  try {
    const status = await request("/api/refresh/status", {
      timeoutMs:5000,
      timeoutMessage:uiText("home.connecting_service"),
    });
    if (
      !status.cache_verified
      && (status.refreshing || status.reconciling || status.connection_pending)
    ) {
      const detail = liveRefreshProgressText(status);
      beginStartupLoading(detail);
      beginPolling(ACTIVE_REFRESH_POLL_MS, "status");
      return false;
    }
  } catch (_error) {
    // The full snapshot provides the existing connection error handling.
  }
  const loaded = await loadState();
  if (!loaded) beginPolling(1000, "status");
  return loaded;
}
function staffJobCategory(staff) {
  const jobType = Number(staff?.job_type || 0);
  return STAFF_JOB_CATEGORY_GROUPS.find((group)=>group.types.includes(jobType))?.label || "其他职员";
}
function staffJobCategoryIndex(label) {
  const index = STAFF_JOB_CATEGORY_GROUPS.findIndex((group)=>group.label===label);
  return index < 0 ? STAFF_JOB_CATEGORY_GROUPS.length : index;
}
function playerAbilitySort(a,b) {
  const caDifference=Number(b?.ca||0)-Number(a?.ca||0);
  if(caDifference)return caDifference;
  const paDifference=Number(b?.pa||0)-Number(a?.pa||0);
  if(paDifference)return paDifference;
  return String(a?.name||"").localeCompare(String(b?.name||""),activeUiLocale());
}
function staffSortInCategory(a,b) {
  const categoryA=staffJobCategory(a),categoryB=staffJobCategory(b);
  const categoryDifference=staffJobCategoryIndex(categoryA)-staffJobCategoryIndex(categoryB);
  if(categoryDifference)return categoryDifference;
  const group=STAFF_JOB_CATEGORY_GROUPS.find((row)=>row.label===categoryA);
  const priorityA=group?group.types.indexOf(Number(a?.job_type||0)):99;
  const priorityB=group?group.types.indexOf(Number(b?.job_type||0)):99;
  if(priorityA!==priorityB)return priorityA-priorityB;
  const caDifference=Number(b?.ca||0)-Number(a?.ca||0);
  if(caDifference)return caDifference;
  const paDifference=Number(b?.pa||0)-Number(a?.pa||0);
  if(paDifference)return paDifference;
  return String(a?.name||"").localeCompare(String(b?.name||""),activeUiLocale());
}
