const EMPTY_BETTING_ROWS = [];

function bettingDataIndex() {
  const data = output();
  const matchRows = data.matches || EMPTY_BETTING_ROWS;
  const competitionRows = data.competitions || EMPTY_BETTING_ROWS;
  const sources = app.bettingIndexSources;
  if (
    sources?.matches === matchRows
    && sources.competitions === competitionRows
    && app.bettingIndex
  ) return app.bettingIndex;
  const matchesByKey = new Map(matchRows.map((match) => [matchKey(match), match]));
  const competitionsById = new Map(
    competitionRows.map((competition) => [Number(competition.id), competition]),
  );
  const competitionDataSignature = JSON.stringify([
    matchRows.map((match) => [
      matchKey(match), String(match.competition_kind || ""),
      Number(match.home?.id || 0), Number(match.away?.id || 0),
      Number(match.kickoff_minutes ?? -1),
    ]),
    competitionRows.map((competition) => [
      Number(competition.id), String(competition.name || ""),
      String(competition.kind || ""), Number(competition.reputation || 0),
    ]),
  ]);
  const previousIndex = app.bettingIndex;
  const competitionVersion = previousIndex?.competitionDataSignature === competitionDataSignature
    ? previousIndex.competitionVersion
    : Number(app.bettingIndexVersion || 0) + 1;
  app.bettingIndexVersion = competitionVersion;
  app.bettingIndexSources = {matches:matchRows, competitions:competitionRows};
  app.bettingIndex = {
    matches:matchRows,
    competitions:competitionRows,
    matchesByKey,
    competitionsById,
    competitionDataSignature,
    competitionVersion,
  };
  return app.bettingIndex;
}

function invalidateBettingDataIndex() {
  app.bettingIndexSources = null;
  app.bettingIndex = null;
  app.competitionRenderSignature = null;
  app.fixtureRenderSignature = null;
  app.fixtureQuerySignature = null;
  app.inlineMarketSource = null;
  app.inlineMarketContainer = null;
  app.inlineMarketRenderSignature = null;
  app.slipRenderSignature = null;
}

function matchHasNotStarted(match) {
  const clock = app.gameClock || app.state?.game_clock;
  if (!clock?.date) return true;
  const fixtureDate = String(match.fixture_date || "");
  if (fixtureDate > String(clock.date)) return true;
  if (fixtureDate < String(clock.date)) return false;
  if (match.kickoff_minutes == null) return true;
  return Number(match.kickoff_minutes) >= Number(clock.minutes || 0);
}
function matches() { return bettingDataIndex().matches.filter(matchHasNotStarted); }
function scopedMatches() {
  const visible = matches().filter(
    (match) => !app.hiddenCompetitions.has(Number(match.competition_id)),
  );
  if (app.scope === "world") return visible;
  const teamIds = app.favoriteTeamIds;
  return teamIds.size ? visible.filter((match) => teamIds.has(Number(match.home.id)) || teamIds.has(Number(match.away.id))) : [];
}
function selectedMatch() {
  const match = bettingDataIndex().matchesByKey.get(String(app.selectedMatch || ""));
  if (!match) {
    return historicalMatches().find((item) => matchKey(item) === String(app.selectedMatch || "")) || null;
  }
  if (!matchHasNotStarted(match)) return null;
  if (app.hiddenCompetitions.has(Number(match.competition_id))) return null;
  if (app.scope === "world") return match;
  return app.favoriteTeamIds.has(Number(match.home.id))
    || app.favoriteTeamIds.has(Number(match.away.id)) ? match : null;
}
function matchMarketsLoaded(match) {
  return match?.market_catalog_state === "full"
    || Boolean(!match?.market_catalog_state && match?.half_time && match?.handicap_options);
}
async function loadMatchMarkets(match) {
  if (!match || match.historical_result || matchMarketsLoaded(match)) return;
  const key = matchKey(match);
  if (app.marketDetailsLoading.has(key)) return;
  app.marketDetailsLoading.add(key);
  match.market_catalog_state = "loading";
  renderInlineMarket();
  try {
    const response = await request("/api/match-markets", {
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({fixture_key:key}),
    });
    // A clock/status sync can replace app.state while the detailed catalog is
    // being calculated. Let that older request settle first, then apply the
    // catalog to the match object that is still owned by the current state.
    if (app.stateLoadPromise) await app.stateLoadPromise;
    if (Number(response.data_version) !== Number(app.state?.data_version)) {
      await loadState({fresh:true});
    }
    if (Number(response.data_version) !== Number(app.state?.data_version)) {
      throw new Error(uiText("betting.market_updated"));
    }
    const currentMatch = bettingDataIndex().matchesByKey.get(key);
    if (!currentMatch) return;
    Object.assign(currentMatch, response.match || {});
    currentMatch.market_catalog_state = "full";
    currentMatch.markets_loaded = true;
    applyLiveClockQuotes(app.gameClock || app.state?.game_clock);
    renderFixtures();
    renderInlineMarket();
  } catch (error) {
    const currentMatch = bettingDataIndex().matchesByKey.get(key) || match;
    if (currentMatch.market_catalog_state === "loading") currentMatch.market_catalog_state = "core";
    toast(error.message || uiText("betting.detail_failed"));
  } finally {
    app.marketDetailsLoading.delete(key);
    renderInlineMarket();
  }
}
function matchKey(match) { return [match.fixture_date, match.competition_id, match.home.id, match.away.id].join("|"); }
function applyLiveClockQuotes(clock) {
  const quotes = clock?.live_1x2 || {};
  let changed = false;
  const matchMap = bettingDataIndex().matchesByKey;
  for (const [key, match] of matchMap) {
    const quote = quotes[key];
    if (!quote?.odds) continue;
    const quoteSignature = JSON.stringify([
      quote.odds,
      quote.phase,
      quote.movement,
      quote.handicap_movement,
      quote.asian_handicap,
      quote.handicap_options,
      quote.knockout,
    ]);
    if (app.liveQuoteSignatures.get(key) !== quoteSignature) {
      app.liveQuoteSignatures.set(key, quoteSignature);
      changed = true;
    }
    match.casino_1x2 = quote.odds;
    match.market_phase = quote.phase;
    match.odds_movement = quote.movement || {};
    match.live_market = {focus:quote.focus, pressure:quote.pressure, strength:quote.strength};
    match.handicap_movement = quote.handicap_movement || match.handicap_movement;
    if (quote.asian_handicap) match.asian_handicap = quote.asian_handicap;
    if (quote.handicap_options?.length) match.handicap_options = quote.handicap_options;
    if (quote.knockout) match.knockout = quote.knockout;
  }
  for (const selection of app.selections) {
    if (!["1X2", "AH", "ADVANCE", "EXTRA_TIME", "PENALTIES", "ADVANCE_METHOD"].includes(selection.market) || selection.pricing_mode === "fair") continue;
    const quote = quotes[selectionMatchKey(selection)];
    if (!quote?.odds) continue;
    if (selection.market === "1X2") {
      selection.odds = Number(quote.odds[selection.selection_code]);
      selection.odds_movement = quote.movement?.[selection.selection_code] || "flat";
    } else {
      if (selection.market === "AH") {
        const option = quote.handicap_options?.find((item) => Number(item.home_line) === Number(selection.line));
        if (option) selection.odds = Number(option[`${selection.selection_code}_odds`]);
      } else if (quote.knockout) {
        const match = matchMap.get(selectionMatchKey(selection));
        if (match) selection.odds = selectionFor(match, selection.market, selection.selection_code, selection.line).odds;
      }
    }
    selection.market_phase = quote.phase;
  }
  return changed;
}
function syncSelectionOddsFromMatches() {
  const matchMap = new Map(matches().map((match) => [matchKey(match), match]));
  const championshipMap = new Map(
    (championshipData().competitions || [])
      .filter((competition) => competition.status === "open")
      .map((competition) => [Number(competition.competition_id), competition]),
  );
  app.selections = app.selections.filter(
    (selection) => {
      if (selection.type !== "championship") return matchMap.has(selectionMatchKey(selection));
      const competition = championshipMap.get(Number(selection.competition_id));
      const team = competition?.teams?.find((item) => Number(item.team_id) === Number(selection.team_id));
      if (!competition || !team || !(Number(team.odds) > 1)) return false;
      selection.market_version = String(competition.market_version || "");
      selection.odds = Number(team.odds);
      return true;
    },
  );
  app.selections = app.selections.filter((selection) => {
    if (selection.type === "championship") return true;
    const match = matchMap.get(selectionMatchKey(selection));
    if (!match) return false;
    if (!matchMarketsLoaded(match)) return true;
    if (selection.market === "AH") return (match.handicap_options || []).some((item) => Number(item.home_line) === Number(selection.line));
    if (selection.market === "HT_AH") return (match.half_time?.handicap_options || []).some((item) => Number(item.home_line) === Number(selection.line));
    if (selection.market === "SH_AH") return (match.half_time?.second_half?.handicap_options || []).some((item) => Number(item.home_line) === Number(selection.line));
    if (selection.market === "OU") return (match.total_options || []).some((item) => Number(item.line) === Number(selection.line));
    if (selection.market === "HT_OU") return (match.half_time?.total_options || []).some((item) => Number(item.line) === Number(selection.line));
    if (selection.market === "SH_OU") return (match.half_time?.second_half?.total_options || []).some((item) => Number(item.line) === Number(selection.line));
    if (selection.market === "TEAM_OU") { const side = String(selection.selection_code || "").split("_", 1)[0]; return (match.team_total_options?.[side] || []).some((item) => Number(item.line) === Number(selection.line)); }
    return true;
  });
  app.selections = app.selections.filter((selection) => {
    if (selection.type === "championship") return true;
    const match = matchMap.get(selectionMatchKey(selection));
    if (!match) return false;
    if (!matchMarketsLoaded(match)) return true;
    try {
      const refreshed = selectionFor(
        match, selection.market, selection.selection_code, selection.line,
      );
      if (!Number.isFinite(refreshed.odds) || refreshed.odds < 1.01) return false;
      Object.assign(selection, refreshed);
      return true;
    } catch (_error) {
      return false;
    }
  });
}
function isChosen(data) { return app.selections.some((item) => keyOf(item) === keyOf(data)); }

function filteredMatches() {
  const gameDate = String(app.gameClock?.date || app.state?.game_clock?.date || output().game_date || "");
  const tomorrow = gameDate ? isoDayAfter(gameDate) : "";
  const needle = app.search.trim().toLowerCase();
  if (app.selectedDate === "previous") {
    return historicalMatches().filter((match) => {
      if (!needle) return true;
      return [match.home.name, match.away.name, match.competition_name]
        .join(" ").toLowerCase().includes(needle);
    });
  }
  return scopedMatches().filter((match) => {
    if (app.selectedCompetition === "friendly" && !["friendly", "unconfirmed"].includes(match.competition_kind)) return false;
    if (app.selectedCompetition === "favorite_competitions_all" && !app.favoriteCompetitionIds.has(Number(match.competition_id))) return false;
    if (!["all", "friendly", "favorite_competitions_all"].includes(app.selectedCompetition) && String(match.competition_id) !== app.selectedCompetition) return false;
    if (app.selectedDate === "today" && match.fixture_date !== gameDate) return false;
    if (app.selectedDate === "tomorrow" && match.fixture_date !== tomorrow) return false;
    if (!needle) return true;
    return [match.home.name, match.away.name, match.competition_name].join(" ").toLowerCase().includes(needle);
  });
}
function isoDayAfter(value) { const date = new Date(`${value}T12:00:00`); date.setDate(date.getDate() + 1); return date.toISOString().slice(0, 10); }

function historicalMatches() {
  const candidates = historicalResultCandidates();
  const previousDate = activeHistoricalDate();
  return candidates
    .filter((result) => String(result.date || "") === previousDate)
    .map(historicalMatchFromResult);
}

function historicalResultCandidates({includeCompetition = true, includeHidden = false} = {}) {
  const gameDate = String(app.gameClock?.date || app.state?.game_clock?.date || output().game_date || "");
  if (!gameDate || !Array.isArray(app.seasonResults)) return [];
  return app.seasonResults
    .filter((result) => String(result.date || "") < gameDate)
    .filter((result) => result.odds_snapshot && typeof result.odds_snapshot === "object")
    .filter((result) => resultMatchesBettingScope(result, includeHidden))
    .filter((result) => !includeCompetition || resultMatchesCompetitionFilter(result));
}

function historicalAvailableDates() {
  return [...new Set(
    historicalResultCandidates({includeCompetition:false})
      .map((result) => String(result.date || ""))
      .filter(Boolean),
  )].sort((left, right) => right.localeCompare(left))
    .slice(0, HISTORICAL_MARKET_DATE_LIMIT);
}

function activeHistoricalDate() {
  const dates = historicalAvailableDates();
  if (app.selectedHistoricalDate === "") return "";
  const selected = String(app.selectedHistoricalDate || "");
  return dates.includes(selected) ? selected : (dates[0] || "");
}

function historicalNavigationMatches(includeHidden = false, requestedDate = activeHistoricalDate()) {
  const previousDate = String(requestedDate || "");
  if (!previousDate) return [];
  return historicalResultCandidates({includeCompetition:false, includeHidden})
    .filter((result) => String(result.date || "") === previousDate)
    .map(historicalMatchFromResult);
}

function historicalMatchFromResult(result) {
  const snapshot = result.odds_snapshot && typeof result.odds_snapshot === "object"
    ? result.odds_snapshot : {};
  return {
    ...snapshot,
    fixture_date: String(result.date || ""),
    kickoff_minutes: snapshot.kickoff_minutes ?? null,
    kickoff_time: snapshot.kickoff_time || "--:--",
    competition_id: Number(result.competition_id || 0),
    competition_name: String(result.competition_name || uiText("team_form.competition_unknown")),
    competition_kind: String(result.competition_kind || "league"),
    home: {...(snapshot.home || {}), ...(result.home || {})},
    away: {...(snapshot.away || {}), ...(result.away || {})},
    market_phase: "early",
    historical_result: result,
  };
}

function topSaveLabel(data) {
  const saveId = String(data.save_instance_id || "");
  const selectedManager = (data.manager_options || []).find((row) => Number(row.id) === Number(data.selected_manager_id));
  const managerName = selectedManager?.name || data.manager?.name || (data.selected_manager_id ? uiText("home.manager_id", {id:data.selected_manager_id}) : "");
  const teams = data.managed_teams?.length ? data.managed_teams : (data.managed_team ? [data.managed_team] : []);
  const teamRank = (team) => String(team?.team_type || "club") === "club" ? 0 : 1;
  const orderedTeams = [...teams].sort((left, right) => teamRank(left) - teamRank(right));
  const teamNames = [...new Set(orderedTeams.map((team) => String(team?.name || "")).filter(Boolean))];
  const teamName = teamNames.join("＋") || data.manager?.team_name || "";
  if (managerName && teamName) return `${managerName}-${teamName}`;
  if (managerName) return managerName;
  return data.save_name || (saveId ? uiText("home.save_id", {id:saveId}) : uiText("home.identifying_save"));
}

function isSaveConnected() {
  return Boolean(app.state?.connection?.connected);
}

function isWalletReady() {
  return Boolean(app.state?.connection?.wallet_ready || isSaveConnected());
}

function refreshBlocksPublishedState(state = app.state) {
  return Boolean(
    state?.refreshing
    || state?.connection_pending
    || (state?.reconciling && !state?.background_reconcile_ready)
  );
}

function liveRefreshProgressText(state = app.state) {
  const progress = state?.refresh_progress || {};
  const fallbackLabels = {
    settle_before_refresh:uiText("refresh.stage.settle_before_refresh"),
    generate_odds:uiText("refresh.stage.generate_odds"),
    validate_snapshot:uiText("refresh.stage.validate_snapshot"),
    settle_bets:uiText("refresh.stage.settle_bets"),
    championship_markets:uiText("refresh.stage.championship_markets"),
    club_context:uiText("refresh.stage.club_context"),
    effects_and_economy:uiText("refresh.stage.effects_and_economy"),
    persist_snapshot:uiText("refresh.stage.persist_snapshot"),
    publish_snapshot:uiText("refresh.stage.publish_snapshot"),
  };
  // Backend progress text is diagnostic and may use the server's source
  // language. Visible copy must be resolved from the stable refresh stage.
  const text = fallbackLabels[state?.refresh_stage]
    || (state?.reconciling ? uiText("refresh.reconciling") : uiText("refresh.refreshing"));
  const completed = Number(progress.completed);
  const total = Number(progress.total);
  const counter = Number.isFinite(completed) && Number.isFinite(total) && total > 0
    ? ` ${Math.min(total, Math.max(0, completed))}/${total}`
    : "";
  const heartbeatAge = Number(progress.heartbeat_age_ms || 0);
  const slowHint = heartbeatAge >= 15000 ? uiText("refresh.slow_hint") : "";
  return `${text}${counter}${slowHint}`;
}

function updateHomeConnectionProgress() {
  const fill = $("#home-connect-fill");
  if (!fill || !app.homeConnectionStartedAt) return;
  const elapsed = Date.now() - app.homeConnectionStartedAt;
  const value = Math.min(94, Math.max(2, elapsed / 120000 * 94));
  fill.style.width = `${value}%`;
  const progress = $("#home-connect-progress");
  progress?.setAttribute("aria-valuenow", String(Math.round(value)));
  progress?.setAttribute("aria-valuetext", uiText("home.connecting_progress", {percent:Math.round(value)}));
}

function syncHomeConnectionProgress(connecting) {
  const progress = $("#home-connect-progress");
  progress.hidden = !connecting;
  if (connecting) {
    if (!app.homeConnectionStartedAt) app.homeConnectionStartedAt = Date.now();
    updateHomeConnectionProgress();
    if (!app.homeConnectionTimer) {
      app.homeConnectionTimer = setInterval(updateHomeConnectionProgress, 350);
    }
    return;
  }
  if (app.homeConnectionTimer) clearInterval(app.homeConnectionTimer);
  app.homeConnectionTimer = null;
  app.homeConnectionStartedAt = null;
  $("#home-connect-fill").style.width = "0";
  progress.setAttribute("aria-valuenow", "0");
  progress.setAttribute("aria-valuetext", uiText("home.connecting_progress", {percent:0}));
}

function homeViewModel() {
  const connection = app.state?.connection || {status:"offline", connected:false, game_available:false};
  const data = output();
  const connected = Boolean(connection.connected);
  const oddsBusy = refreshBlocksPublishedState();
  const refreshControlBusy = Boolean(app.state?.refreshing || app.state?.reconciling);
  const connecting = !connected && (
    connection.status === "connecting" || Boolean(app.state?.connection_pending)
  );
  const detected = Boolean(connection.game_available);
  const title = connected
    ? topSaveLabel(data)
    : connecting
      ? uiText("home.reading_current_save")
      : detected
        ? uiText("home.detected_game")
        : uiText("home.not_connected");
  const managedTeam = data.managed_team?.name || data.managed_teams?.[0]?.name || "";
  const record = homeManagerRecord();
  const connectionMessageKey = `home.connection.${String(connection.message_code || "")}`;
  const localizedConnectionMessage = uiText(connectionMessageKey);
  const detail = connected
    ? (oddsBusy
      ? liveRefreshProgressText()
      : [data.game_date ? uiText("home.game_date", {date:data.game_date}) : "", managedTeam].filter(Boolean).join(" · "))
    : (localizedConnectionMessage !== connectionMessageKey
      ? localizedConnectionMessage
      : (detected ? uiText("home.enter_save") : uiText("home.launch_game")));
  const recordTotal = record?.total || null;
  const clubBusy = Boolean(app.clubStatus?.refreshing || app.state?.club_status?.refreshing);
  return {
    connection, data, connected, oddsBusy, refreshControlBusy, connecting, detected, title,
    managedTeam, record, recordTotal, clubBusy, detail,
  };
}

function homeRenderStateSignature(view) {
  const total = view.recordTotal;
  return JSON.stringify([
    String(app.state?.data_scope_id || ""), Number(app.state?.data_version || 0),
    view.connection.status || "offline", view.connected, view.connecting, view.detected,
    view.title, view.detail, view.oddsBusy, view.refreshControlBusy, view.clubBusy,
    total ? [
      Number(total.played || 0), Number(total.wins || 0), Number(total.draws || 0),
      Number(total.losses || 0), Number(total.win_rate || 0),
    ] : null,
    Boolean(app.homeManagerRecordLoadFailed), String(view.data.save_name || ""),
  ]);
}

function renderHome() {
  // Legacy source copy retained for static compatibility checks; displayed text uses i18n keys below.
  // 正在整理执教战绩
  renderHomeGlobalUsage();
  const view = homeViewModel();
  const {
    connection, data, connected, oddsBusy, refreshControlBusy, connecting, title,
    recordTotal, clubBusy, detail,
  } = view;
  const root = $("#home-connection");
  root.dataset.status = connection.status || "offline";
  root.setAttribute("aria-busy", String(connecting || oddsBusy));
  $("#page-home")?.setAttribute("aria-busy", String(connecting || oddsBusy));
  syncHomeConnectionProgress(connecting);
  const signature = homeRenderStateSignature(view);
  if (app.homeRenderSignature === signature) return;
  app.homeRenderSignature = signature;
  const progressTitle = $("#home-connect-progress strong");
  const progressDetail = $("#home-connect-progress small");
  if (progressTitle) progressTitle.textContent = uiText("home.connecting_save");
  if (progressDetail) progressDetail.textContent = uiText("home.reading_identity");
  $("#home-connection-title").textContent = title;
  $("#home-connection-detail").textContent = detail;
  const recordPanel = $("#home-manager-record");
  recordPanel.hidden = !connected;
  recordPanel.setAttribute("aria-busy", String(Boolean(connected && !recordTotal)));
  recordPanel.classList.toggle("loading", Boolean(connected && !recordTotal));
  if (connected && recordTotal) {
    $("#home-manager-record-title").textContent = uiText("home.current_team_record");
    $("#home-manager-record-played").textContent = uiPlural("home.matches_played", Number(recordTotal.played || 0));
    $("#home-manager-record-wins").textContent = String(Number(recordTotal.wins || 0));
    $("#home-manager-record-draws").textContent = String(Number(recordTotal.draws || 0));
    $("#home-manager-record-losses").textContent = String(Number(recordTotal.losses || 0));
    $("#home-manager-record-rate").textContent = `${Number(recordTotal.win_rate || 0).toFixed(1)}%`;
  } else if (connected) {
    $("#home-manager-record-title").textContent = app.homeManagerRecordLoadFailed
      ? uiText("home.record_unavailable")
      : clubBusy || oddsBusy ? uiText("home.record_loading") : uiText("home.record_preparing");
    $("#home-manager-record-played").textContent = app.homeManagerRecordLoadFailed
      ? uiText("home.retry_later")
      : clubBusy || oddsBusy ? uiText("home.loading") : uiText("home.waiting");
    $("#home-manager-record-wins").textContent = "—";
    $("#home-manager-record-draws").textContent = "—";
    $("#home-manager-record-losses").textContent = "—";
    $("#home-manager-record-rate").textContent = "—";
  }
  if (connected && !oddsBusy) ensureHomeManagerRecordLoaded();
  const connectButton = $("#connect-save-button");
  connectButton.disabled = connecting || refreshControlBusy;
  connectButton.setAttribute("aria-busy", String(connecting));
  connectButton.querySelector("span").textContent = connecting ? uiText("home.connecting") : connected ? (refreshControlBusy ? uiText("home.refreshing") : uiText("home.reconnect")) : uiText("home.connect");
  document.querySelectorAll("[data-home-app]").forEach((button) => {
    button.classList.toggle("locked", !connected);
    button.setAttribute("aria-disabled", String(!connected));
  });
  $("#home-last-save").textContent = connected
    ? uiText("home.connected", {name:title})
    : (data.save_name ? uiText("home.last_detected", {name:data.save_name}) : "");
}

function formatUsageTime(seconds) {
  const total = Math.max(0, Math.floor(Number(seconds || 0)));
  if (total < 60) return uiText("usage.less_than_minute");
  const days = Math.floor(total / 86400);
  const hours = Math.floor(total % 86400 / 3600);
  const minutes = Math.floor(total % 3600 / 60);
  if (days) return uiText("usage.days_hours", {days, hours});
  if (hours) return uiText("usage.hours_minutes", {hours, minutes});
  return uiText("usage.minutes", {minutes});
}

function renderHomeGlobalUsage() {
  const usage = $("#home-global-usage");
  if (!usage) return;
  usage.textContent = app.globalUsage
    ? formatUsageTime(app.globalUsage.usage_seconds)
    : uiText("usage.calculating");
}

function renderGlobalCareerStatistics(statistics) {
  const content = $("#global-career-content");
  if (!content) return;
  const signedMoney = (value) => (Number(value) > 0 ? "+" : "") + formatGlobalStatisticMoney(Number(value || 0));
  const streak = Number(statistics.current_streak || 0);
  const currentStreak = streak > 0 ? uiText("home.current_streak_win", {count:streak}) : streak < 0 ? uiText("home.current_streak_loss", {count:Math.abs(streak)}) : "—";
  const metric = (label, value, note = "", className = "") => (
    '<article class="' + className + '"><span>' + label + "</span><strong>" + value
    + "</strong>" + (note ? "<small>" + note + "</small>" : "") + "</article>"
  );
  content.innerHTML = '<section class="global-career-usage"><span><i data-lucide="clock-3"></i></span><div><small>' + uiText("home.global_usage") + '</small><strong>'
    + escapeHtml(formatUsageTime(statistics.usage_seconds))
    + "</strong></div><em>" + uiPlural("home.active_days", Number(statistics.active_days || 0)) + "</em></section>"
    + '<section class="global-career-metrics">'
    + metric(uiText("home.net_profit"), signedMoney(statistics.net_profit), uiText("home.roi", {value:Number(statistics.roi || 0).toFixed(2)}), Number(statistics.net_profit) > 0 ? "profit" : Number(statistics.net_profit) < 0 ? "loss" : "")
    + metric(uiText("home.max_profit"), signedMoney(statistics.maximum_profit), uiText("home.net_profit_note"), "profit")
    + metric(uiText("home.longest_win"), uiPlural("home.bets", Number(statistics.longest_win_streak || 0)), currentStreak, "profit")
    + metric(uiText("home.bet_count"), uiPlural("home.bets", Number(statistics.settled_bets || 0)), uiText("home.bet_record", {wins:Number(statistics.wins || 0), losses:Number(statistics.losses || 0), pushes:Number(statistics.pushes || 0)}))
    + metric(uiText("home.saves_used"), String(Number(statistics.save_count || 0)), uiText("home.betting_saves", {count:Number(statistics.betting_save_count || 0)}))
    + metric(uiText("home.longest_loss"), uiPlural("home.bets", Number(statistics.longest_loss_streak || 0)), uiText("home.max_loss", {amount:signedMoney(statistics.maximum_loss)}), Number(statistics.maximum_loss) < 0 ? "loss" : "")
    + "</section>";
  renderIcons();
}

function syncGlobalCareerScopeControls() {
  const scope = app.globalStatisticsScope === "current" ? "current" : "global";
  const currentAvailable = Boolean(app.state?.data_scope_id);
  document.querySelectorAll("[data-global-career-scope]").forEach((button) => {
    const selected = button.dataset.globalCareerScope === scope;
    button.classList.toggle("active", selected);
    button.setAttribute("aria-selected", String(selected));
    button.disabled = Boolean(app.globalStatisticsLoading)
      || (button.dataset.globalCareerScope === "current" && !currentAvailable);
  });
  const title = $("#global-career-title");
  if (title) title.textContent = uiText(scope === "current" ? "career.current_title" : "career.title");
}

function renderGlobalCareerState() {
  const dialog = $("#global-career-dialog");
  const content = $("#global-career-content");
  if (!dialog || !content) return;
  const busy = Boolean(app.globalStatisticsLoading);
  dialog.setAttribute("aria-busy", String(busy));
  content.setAttribute("aria-busy", String(busy));
  syncGlobalCareerScopeControls();
  if (busy) {
    const loadingKey = app.globalStatisticsScope === "current" ? "career.loading_current" : "home.loading_global";
    content.innerHTML = `<div class="global-career-loading" role="status"><span class="spinner"></span>${uiText(loadingKey)}</div>`;
    renderIcons(dialog);
    return;
  }
  if (app.globalStatisticsError) {
    content.innerHTML = `<div class="global-career-error" role="alert"><i data-lucide="circle-alert"></i><strong>${uiText("home.global_error")}</strong><span>${escapeHtml(app.globalStatisticsError)}</span><button type="button" data-global-career-retry>${uiText("home.retry")}</button></div>`;
    renderIcons(dialog);
    return;
  }
  if (app.globalStatistics) renderGlobalCareerStatistics(app.globalStatistics);
}

async function loadGlobalCareerStatistics() {
  const dialog = $("#global-career-dialog");
  if (!dialog) return;
  if (app.globalStatisticsLoading) return;
  app.globalStatisticsLoading = true;
  app.globalStatisticsError = "";
  renderGlobalCareerState();
  try {
    const statistics = await (
      app.globalStatisticsScope === "current"
        ? request("/api/global-statistics?scope=current")
        : request("/api/global-statistics")
    );
    app.globalStatistics = statistics;
    if (app.globalStatisticsScope === "global") {
      app.globalUsage = statistics;
      renderHomeGlobalUsage();
    }
  } catch (error) {
    app.globalStatisticsError = error.message || uiText("home.load_failed");
  } finally {
    app.globalStatisticsLoading = false;
    renderGlobalCareerState();
  }
}

async function setGlobalCareerStatisticsScope(scope) {
  const nextScope = scope === "current" ? "current" : "global";
  if (nextScope === "current" && !app.state?.data_scope_id) return;
  if (app.globalStatisticsLoading || app.globalStatisticsScope === nextScope) return;
  app.globalStatisticsScope = nextScope;
  app.globalStatistics = null;
  await loadGlobalCareerStatistics();
}

async function openGlobalCareerStatistics() {
  const dialog = $("#global-career-dialog");
  if (!dialog) return;
  app.globalStatisticsScope = "global";
  app.globalStatistics = null;
  if (!dialog.open) dialog.showModal();
  await loadGlobalCareerStatistics();
}

async function sendGlobalUsageHeartbeat(active = true) {
  if ((active && document.visibilityState === "hidden") || app.globalUsageHeartbeatBusy) return;
  app.globalUsageHeartbeatBusy = true;
  try {
    app.globalUsage = await request("/api/global-statistics/heartbeat", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({active}),
    });
    renderHomeGlobalUsage();
  } catch (_error) {
    // Usage statistics must not interrupt the main application.
  } finally {
    app.globalUsageHeartbeatBusy = false;
  }
}

function startGlobalUsageTracking() {
  sendGlobalUsageHeartbeat(true);
  app.globalUsageHeartbeatTimer = setInterval(() => sendGlobalUsageHeartbeat(true), 30000);
  document.addEventListener("visibilitychange", () => {
    sendGlobalUsageHeartbeat(document.visibilityState !== "hidden");
  });
  window.addEventListener("pagehide", () => {
    fetch("/api/global-statistics/heartbeat", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({active:false}), keepalive:true,
    }).catch(() => {});
  });
}

async function connectCurrentSave() {
  if (app.state?.refreshing || app.state?.reconciling) {
    if (isSaveConnected()) {
      toast(uiText("home.connected_refreshing"));
      beginPolling(ACTIVE_REFRESH_POLL_MS, "status");
      return;
    }
    app.state.connection = {
      ...app.state.connection,
      status:"connecting",
      connected:false,
      message:uiText("home.continue_reading"),
    };
    if (!app.homeConnectionStartedAt) app.homeConnectionStartedAt = Date.now();
    renderHome();
    beginPolling(ACTIVE_REFRESH_POLL_MS, "status");
    return;
  }
  if (app.state) {
    app.state.connection = {...app.state.connection,status:"connecting",connected:false,message:uiText("home.reading_current")};
  }
  app.homeConnectionStartedAt = Date.now();
  clearOwnedClubDetailCache();
  renderHome();
  try {
    const response = await request("/api/connect", {method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});
    if (!response.started) {
      await loadState({fresh:true});
      toast(uiText("home.connection_pending"));
      return;
    }
    if (app.state) {
      app.state.refreshing = true;
      app.state.refresh_mode = response.refresh_mode || "startup";
      app.state.connection = {...app.state.connection,status:"connecting",connected:false,wallet_ready:Boolean(response.wallet_ready),message:uiText("home.reading_current")};
      app.state.data_scope_id = response.data_scope_id || app.state.data_scope_id;
    }
    render();
    beginPolling(ACTIVE_REFRESH_POLL_MS, "status");
  } catch (error) {
    toast(error.message);
    await loadState({fresh:true});
  }
}

function renderRefreshControls() {
  if (!app.state) return;
  const oddsBusy = Boolean(app.state.refreshing || app.state.reconciling);
  const oddsRefreshActive = app.state.refreshing && app.state.refresh_mode !== "results";
  renderTopbarRefreshStatus();
  const signature = JSON.stringify([oddsBusy, oddsRefreshActive, String(app.state.refresh_mode || "")]);
  if (app.refreshControlsRenderSignature === signature) return;
  app.refreshControlsRenderSignature = signature;
  $("#refresh-button").disabled = oddsBusy;
  $("#refresh-button span").textContent = app.state.refresh_mode === "fast" ? uiText("refresh.fast_busy") : uiText("refresh.fast");
  const marketFullRefreshButton = $("#market-full-refresh-button");
  marketFullRefreshButton?.toggleAttribute("disabled", oddsBusy);
  const marketFullRefreshLabel = $("#market-full-refresh-button span");
  if (marketFullRefreshLabel) marketFullRefreshLabel.textContent = app.state.refresh_mode === "full" ? uiText("refresh.full_busy") : uiText("refresh.full");
  $("#settle-button").disabled = oddsBusy;
  $("#settle-button span").textContent = app.state.refresh_mode === "results" ? uiText("refresh.results_busy") : uiText("refresh.results");
  const fullRefreshButton = $("#full-refresh-button");
  fullRefreshButton?.toggleAttribute("disabled", oddsBusy);
  const fullRefreshLabel = $("#full-refresh-button span");
  if (fullRefreshLabel) fullRefreshLabel.textContent = app.state.refresh_mode === "full" ? uiText("refresh.full_busy") : uiText("refresh.change_save");
  $("#apply-odds-reading").disabled = oddsBusy;
  $("#apply-odds-reading span").textContent = oddsRefreshActive ? uiText("refresh.busy") : uiText("refresh.apply");
}

function syncBettingPageStatus() {
  const oddsBusy = refreshBlocksPublishedState();
  $("#page-betting")?.setAttribute("aria-busy", String(oddsBusy));
  $("#competition-list")?.setAttribute("aria-busy", String(oddsBusy));
  $("#page-betting .event-panel")?.setAttribute("aria-busy", String(oddsBusy));
  $("#fixtures")?.setAttribute("aria-busy", String(oddsBusy));
  ["#refresh-button", "#market-full-refresh-button", "#settle-button"].forEach((selector) => {
    $(selector)?.setAttribute("aria-busy", String(oddsBusy));
  });
}

function homeManagerRecord() {
  const stateScope = String(app.state?.data_scope_id || "");
  const clubScope = String(app.clubStatus?.data_scope_id || "");
  if (!stateScope || clubScope !== stateScope) return null;
  const team = managedTeams().find((row) => String(row.team_type || "club") === "club");
  if (!team) return null;
  return teamProfile(Number(team.id))?.manager_record || null;
}

async function ensureHomeManagerRecordLoaded() {
  const data = output();
  const team = managedTeams().find((row) => String(row.team_type || "club") === "club");
  const managerId = Number(data.selected_manager_id || data.manager?.id || 0);
  const scope = String(app.state?.data_scope_id || "");
  if (!scope || !team || managerId <= 0) return;
  const key = [scope, managerId, Number(team.id), Number(app.state?.data_version || 0)].join(":");
  if (app.homeManagerRecordLoadKey === key) return;
  app.homeManagerRecordLoadKey = key;
  app.homeManagerRecordLoadFailed = false;
  try {
    const payload = await loadClub({silent:true});
    if (!payload && app.homeManagerRecordLoadKey === key) {
      app.homeManagerRecordLoadFailed = true;
      renderHome();
    }
  } catch (_error) {
    if (app.homeManagerRecordLoadKey === key) {
      app.homeManagerRecordLoadFailed = true;
      renderHome();
    }
  }
}

function renderCurrentPage(page = app.page) {
  const renderers = {
    home: () => renderHome(),
    betting: () => {
      syncBettingPageStatus();
      renderCompetitions();
      renderFixtures();
      renderInlineMarket();
      renderSlip();
    },
    league: () => renderLeague(),
    shop: () => renderShop(),
    lottery: () => renderLottery(),
    inventory: () => renderInventory(),
    bank: () => renderBank(),
    activity: () => renderActivity(),
    hospital: () => renderHospital(),
    training: () => renderTraining(),
    canteen: () => renderCanteen(),
    club: () => renderClub(),
    relations: () => renderRelationsPage(),
    "hall-of-fame": () => renderHallOfFame(),
    "world-clubs": () => renderWorldClubs(),
    "world-players": () => renderWorldPlayers(),
    "world-nations": () => renderWorldNations(),
    "my-clubs": () => renderMyClubs(),
  };
  renderers[page]?.();
}

