    skyDrag: (() => { const v = String(lsGet("nebula.skyDrag", "off")); return ["off", "item", "all"].includes(v) ? v : "off"; })(), // 银河拖动模式：off 禁止 / item 个体 / all 整体
    skyOffX: Number(lsGet("nebula.skyOff.x", 0)) || 0,
