    skyItemOff: (() => { try { const o = JSON.parse(localStorage.getItem(`fmodd.rel3d.nebula.skyItems.${curTab}`) || "{}"); return o && typeof o === "object" ? o : {}; } catch (err) { return {}; } })(),
    skySel: new Set(), dragSkyKeys: null,
