    tacticsEditPts: null, // 拖拽磁贴后的工作副本（保存为自定义阵型前）
    customFormations: (() => { try { const o = JSON.parse(localStorage.getItem(`fmodd.rel3d.tactics.custom.${curTab}`) || "{}"); return o && typeof o === "object" ? o : {}; } catch (err) { return {}; } })(),
    trophyJersey: String(lsGet("trophy.jersey", "stripes")),
    trophyCup: String(lsGet("trophy.cup", "gold")),
