    trophyKits: (() => { try { const o = JSON.parse(localStorage.getItem(`fmodd.rel3d.trophy.kits.${curTab}`) || "{}"); return o && typeof o === "object" ? o : {}; } catch (err) { return {}; } })(),
    netOffX: Number(lsGet("offset.x", 0)) * baseR, // 关系网整体在背景中的位置（仅移动网络，不动背景）
    netOffY: Number(lsGet("offset.y", 0)) * baseR,
