  const assignments = Object.fromEntries(slots.flatMap((slot,index) => previousAssignments[index] ? [[slot.id,previousAssignments[index]]] : []));
  const entry = {id:positionTrainingCustomId(),name:uiText("facility.custom_formation_number", {number:state.customFormations.length + 1}),slots,assignments};
  state.customFormations.push(entry);
