  if (app.bankRenderSignature === signature) return;
  app.bankRenderSignature = signature;
  const active = credit.status === "active" && Number(credit.outstanding || 0) > 0;
  const salaryKnown = Number(salary.gross_weekly || 0) > 0 && Boolean(salary.next_payday);
  const combinedFunds = Math.max(0, Number(economy.bank_balance || 0)) + Number(economy.casino_balance || 0);
  const refreshClubButton = `<button class="primary-action" data-refresh-club-info><i data-lucide="refresh-cw"></i><span>${uiText("bank.refresh_club")}</span></button>`;
