  const dividendPaymentRows = (rows) => rows.map((row) => `<div><span><b>${escapeHtml(row.team_name || uiText("bank.acquired_club"))}</b><small>${uiText("bank.dividend.month", {month:escapeHtml(row.month || "")})}</small></span><b>+${formatFullMoney(row.amount)}</b></div>`).join("");
  const dividendHistory = dividendPayments.length
    ? `<div class="bank-dividend-history">${dividendPaymentRows(latestDividendPayments)}</div>${earlierDividendPayments.length ? `<details class="bank-dividend-archive"><summary>${uiText("bank.dividend.earlier", {count:earlierDividendPayments.length})}</summary><div class="bank-dividend-history">${dividendPaymentRows(earlierDividendPayments)}</div></details>` : ""}`
    : `<span class="bank-dividend-empty">${uiText("bank.dividend.empty")}</span>`;
  const developmentBankAction = String(app.state?.app_version || "").toLowerCase().endsWith("-dev")
