function intimacyRankingProjection(person) {
  const unsigned = Math.abs(Number(person.manager_intimacy || 0));
  const explicit = Number(person.manager_signed_intimacy);
  const signed = Number.isFinite(explicit)
    ? explicit
    : Number(person.manager_relation_type) === 1 || person.manager_relation_type == null
      ? unsigned : -unsigned;
  const permanent = Number(person.manager_relation_permanence) === 79;
  const tier = signed >= 0 ? (permanent ? 0 : 1) : (permanent ? 3 : 2);
  return {...person, signed_score:signed, permanent, tier};
}

async function loadIntimacyRankingPairs(kind) {
  const profile = app.clubProfiles.find((row) => String(row.team?.team_type || "club") === "club") || {};
  const teamId = Number(profile.team?.id || 0);
  const sourceVersion = Number(app.state?.data_version || 0);
  const cacheKey = `${kind}:${teamId}:${sourceVersion}`;
  if (!teamId || app.intimacyRankingPairCache?.key === cacheKey || app.intimacyRankingPairLoading === cacheKey) return;
  app.intimacyRankingPairLoading = cacheKey;
  try {
    const payload = {scope_kind:"managed",team_id:teamId,squad_team_id:0,person_kind:kind,page_size:60,search:"",data_version:sourceVersion};
    const first = await request("/api/relations/network", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({...payload,page:1}),
    });
    const people = [...(first.people || [])];
    for (let page = 2; page <= Number(first.pages || 1); page += 1) {
      const response = await request("/api/relations/network", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...payload,page})});
      people.push(...(response.people || []));
    }
    const personKeys = new Map(people.map((row) => [Number(row.id), String(row.person_key || "")]));
    const managerCounts = new Map();
    people.forEach((row) => Object.entries(row.person_relations_detail || {}).forEach(([key, detail]) => {
      if (Number(detail.reason) === 6) managerCounts.set(key, (managerCounts.get(key) || 0) + 1);
    }));
    const managerKey = [...managerCounts].sort((left,right) => right[1] - left[1])[0]?.[0] || "";
    app.intimacyRankingPairCache = {key:cacheKey, sourceVersion, managerKey, personKeys};
  } catch (error) {
    app.intimacyRankingPairCache = {key:cacheKey, sourceVersion, managerKey:"", personKeys:new Map(), error:error.message};
  } finally {
    app.intimacyRankingPairLoading = "";
    renderIntimacyRanking();
  }
}

async function openIntimacyRankingPair(personId, personName) {
  const detail = $("#intimacy-ranking-pair");
  const cache = app.intimacyRankingPairCache;
  const personKey = cache?.personKeys?.get(Number(personId));
  if (!detail || !cache?.managerKey || !personKey) { toast(uiText("relationship.ranking.pair_unresolved")); return; }
  detail.hidden = false;
  detail.innerHTML = `<span class="spinner"></span>${uiText("relationship.ranking.pair_loading")}`;
  try {
    const pair = await request("/api/relations/pair", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({person_a:cache.managerKey,person_b:personKey})});
    const line = (label, value) => `<div><strong>${escapeHtml(label)}</strong><b class="${Number(value?.signed_score || 0) < 0 ? "negative" : ""}">${Number(value?.signed_score || 0) > 0 ? "+" : ""}${Number(value?.signed_score || 0)}</b><small>${escapeHtml(relationshipReasonLabel(value?.reason))}${Number(value?.permanence) === 79 ? ` · ${uiText("relations.permanent")} ${relationshipPermanentIcon(value?.signed_score,true)}` : ""}</small></div>`;
    detail.innerHTML = `${line(uiText("relationship.ranking.manager_to_person", {person:personName}), pair.a_to_b)}${line(uiText("relationship.ranking.person_to_manager", {person:personName}), pair.b_to_a)}`;
  } catch (error) { detail.innerHTML = `<div class="intimacy-ranking-empty">${escapeHtml(error.message || uiText("relations.error.pair"))}</div>`; }
}

function renderIntimacyRanking() {
  const root = $("#intimacy-ranking-list");
  if (!root) return;
  if (!["players","staff"].includes(app.rankingTab)) app.rankingTab = "players";
  const kind = app.rankingTab === "staff" ? "staff" : "player";
  const profile = app.clubProfiles.find((row) => String(row.team?.team_type || "club") === "club") || {};
  const people = (kind === "staff" ? profile.staff || [] : allManagedPlayers() || [])
    .map(intimacyRankingProjection)
    .sort((left, right) => left.tier - right.tier || right.signed_score - left.signed_score || String(left.name).localeCompare(String(right.name), activeUiLocale()));
  const label = kind === "staff" ? uiText("relations.role.staff") : uiText("relations.role.player");
  const average = people.length
    ? Math.round(people.reduce((sum, person) => sum + Number(person.signed_score || 0), 0) / people.length)
    : 0;
  const maximum = people.length ? Math.max(...people.map((person) => Number(person.signed_score || 0))) : 0;
  const permanentCount = people.filter((person) => person.permanent).length;
  const avatarClass = (name) => `av${[...String(name || "?")].reduce((sum, char) => sum + char.charCodeAt(0), 0) % 5}`;
  const rows = people.map((person, index) => {
    const score = Number(person.signed_score || 0);
    const reason = Number(person.manager_relation_reason || 0);
    const reasonInfo = kind === "staff"
      ? staffRelationLabel(reason, person.job_type)
      : resolveIntimacyLabel(reason, true, true);
    const level = intimacyRelationLabelByScore(score);
    const scoreClass = intimacyScoreClass(score);
    const subtitle = kind === "staff"
      ? uiText("relationship.ranking.person_subtitle", {role:localizedStaffRole(person), ca:Number(person.ca || 0)})
      : uiText("relationship.ranking.person_subtitle", {role:primaryPlayerPosition(person), ca:Number(person.ca || 0)});
    const rank = index < 3
      ? `<span class="lb-rank-badge medal-${index + 1}">${index + 1}</span>`
      : `<span class="lb-rank-num">${String(index + 1).padStart(2,"0")}</span>`;
    const personName = person.name || uiText("relationship.ranking.person_fallback", {id:Number(person.id || 0)});
    return `<div class="lb-row"><span class="lb-col lb-rank">${rank}</span><span class="lb-col lb-name"><span class="lb-avatar ${avatarClass(person.name)}">${escapeHtml(String(person.name || "?").slice(0,2))}</span><span class="lb-identity"><b>${escapeHtml(personName)}${person.permanent ? `<em class="lb-perm" title="${uiText("relationship.ranking.permanent_bond")}">${relationshipPermanentIcon(score,true)}</em>` : ""}</b><small>${escapeHtml(subtitle)}</small></span></span><span class="lb-col lb-relation ${reasonInfo.cls}">${escapeHtml(reasonInfo.label)}</span><span class="lb-col lb-level ${level.cls}">${level.label}</span><span class="lb-col lb-score"><b class="${scoreClass}${score < 0 ? " negative" : ""}">${score > 0 ? "+" : ""}${score}</b><span class="lb-bar"><i class="lb-bar-fill ${scoreClass}${score < 0 ? " negative" : ""}" style="width:${Math.min(100,Math.abs(score))}%"></i></span></span></div>`;
  }).join("");
  const head = `<div class="lb-head"><span class="lb-col lb-rank">#</span><span class="lb-col lb-name">${uiText("relationship.ranking.name")}</span><span class="lb-col lb-relation">${uiText("relationship.ranking.relationship")}</span><span class="lb-col lb-level">${uiText("relationship.ranking.level")}</span><span class="lb-col lb-score">${uiText("relationship.ranking.intimacy")}</span></div>`;
  root.innerHTML = `<div class="lb-shell"><div class="lb-stats"><div><i data-lucide="${kind === "staff" ? "briefcase" : "users"}"></i><span>${uiText("relationship.ranking.person_count", {label})}</span><b>${people.length}</b></div><div><i data-lucide="heart-handshake"></i><span>${uiText("relationship.ranking.average")}</span><b>${average}</b></div><div><i data-lucide="crown"></i><span>${uiText("relationship.ranking.maximum")}</span><b>${maximum}</b></div><div><i data-lucide="star"></i><span>${uiText("relationship.ranking.permanent_bond")}</span><b>${permanentCount}</b></div></div>${people.length ? `<div class="lb-table">${head}${rows}</div>` : `<div class="lb-empty"><i data-lucide="${kind === "staff" ? "briefcase" : "users"}"></i><strong>${uiText("relationship.ranking.empty", {label})}</strong><span>${uiText("relationship.ranking.empty_note")}</span></div>`}</div>`;
  const subtitle = document.querySelector("#intimacy-ranking-dialog .dialog-head p");
  if (subtitle) subtitle.textContent = uiText("relationship.ranking.subtitle", {manager:selectedManagerName(), label});
  document.querySelectorAll(".intimacy-ranking-tab").forEach((button) => {
    const active = button.dataset.rankingTab === app.rankingTab;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", String(active));
  });
  renderIcons(root);
}

async function ensureWorldDataScan() {
  if (app.internationalNationsScanPromise) return app.internationalNationsScanPromise;
  const task = (async () => {
    const response = await request("/api/world-clubs/scan", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: "{}",
    });
    let scan = response.native_scan || {};
    for (let attempt = 0; attempt < 180; attempt += 1) {
      if (!scan.scanning && scan.ready && scan.addresses_current) return scan;
      if (!scan.scanning && scan.error) throw new Error(uiText("world.clubs.scan_failed"));
      await new Promise((resolve) => setTimeout(resolve, 1000));
      const latest = await request("/api/world-nations?page=1&page_size=15");
      app.worldNations = latest;
      app.worldNationsScope = String(app.state?.data_scope_id || output().save_instance_id || "");
      invalidateWorldNationDataIndex();
      if (app.page === "world-nations") renderWorldNations();
      scan = latest.native_scan || {};
    }
    throw new Error(uiText("world.scan_timeout"));
  })();
  app.internationalNationsScanPromise = task;
  try {
    return await task;
  } finally {
    if (app.internationalNationsScanPromise === task) app.internationalNationsScanPromise = null;
  }
}

// Kept as a semantic alias for the activity-centre caller.
function ensureInternationalNationScan() {
  return ensureWorldDataScan();
}

async function loadInternationalNations() {
  if (app.internationalNationsLoading) return;
  app.internationalNationsLoading = true;
  app.internationalNationError = "";
  let scanAttempted = false;
  try {
    while (true) {
      try {
        const response = await request("/api/activity/international/nations");
        app.internationalNations = response.nations || [];
        break;
      } catch (error) {
        const message = String(error?.message || "");
        const needsScan = !scanAttempted && /刷新世界数据|扫描世界数据|世界国家/.test(message);
        if (!needsScan) {
          // Keep this as null so a later activity render can retry.  An empty
          // array is a successful, cacheable result and would suppress reloads.
          app.internationalNations = null;
          app.internationalNationError = message;
          break;
        }
        scanAttempted = true;
        await ensureInternationalNationScan();
      }
    }
  } catch (error) {
    app.internationalNations = null;
    app.internationalNationError = error.message || uiText("world.scan_failed");
  } finally {
    app.internationalNationsLoading = false;
    if (app.page === "activity" && app.activityFloor === "international") renderActivity();
  }
}

