async function updateItemUsePlayers() {
  const itemId = $("#use-item-id").value;
  const item = economyItem(itemId);
  const teamId = Number($("#use-team").value || 0);
  if (item?.sku === "opponent_flu") {
    const fixtureKey = $("#use-fixture").value;
    const requestKey = `${teamId}:${fixtureKey}:${Date.now()}`;
    app.opponentPlayerRequestKey = requestKey;
    $("#use-player").disabled = true;
     $("#use-player").innerHTML = `<option value="">${uiText("inventory.reading_opponent_players")}</option>`;
    try {
      const response = await request("/api/fixture/opponent-players", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({team_id:teamId,fixture_key:fixtureKey})});
      if (app.opponentPlayerRequestKey !== requestKey) return;
      const players = response.players || [];
      $("#use-player").innerHTML = players.map((player) => {
        const injured = Number(player.availability?.injury_count || 0) > 0 || (player.availability?.injuries || []).length > 0;
         return `<option value="${Number(player.id)}" ${injured ? "disabled" : ""}>${escapeHtml(player.name)} · ${escapeHtml((player.positions || []).join("/"))}${injured ? ` · ${uiText("inventory.injured")}` : ""}</option>`;
       }).join("") || `<option value="">${uiText("inventory.opponent_no_players")}</option>`;
      const available = [...$("#use-player").options].some((option) => !option.disabled && Number(option.value));
      $("#use-player").disabled = !available;
       if (!available) toast(uiText("inventory.opponent_uninjured_required"));
    } catch (error) {
      if (app.opponentPlayerRequestKey !== requestKey) return;
       $("#use-player").innerHTML = `<option value="">${uiText("inventory.opponent_read_failed")}</option>`;
      $("#use-player").disabled = true;
      toast(error.message);
    }
    return;
  }
  const profile = teamProfile(teamId) || {};
  $("#use-player").innerHTML = (profile.players || []).map((player) => `<option value="${player.id}">${escapeHtml(player.name)} · ${escapeHtml((player.positions || []).join("/"))}</option>`).join("");
  $("#use-player").disabled = false;
}

async function updateItemUseOptions() {
  const teamId = Number($("#use-team").value || 0);
  const previousFixture = $("#use-fixture").value;
  $("#use-fixture").innerHTML = managedFixtures().filter((match) => [Number(match.home.id), Number(match.away.id)].includes(teamId)).map((match) => `<option value="${escapeHtml(matchKey(match))}">${escapeHtml(match.fixture_date)} · ${escapeHtml(match.home.name)} VS ${escapeHtml(match.away.name)}</option>`).join("");
  if ([...$("#use-fixture").options].some((option) => option.value === previousFixture)) $("#use-fixture").value = previousFixture;
  await updateItemUsePlayers();
}

async function loadReputationTargets(waitForPlayers = false) {
  const fetchTargets = () => request("/api/inventory/reputation-targets", {
    method:"POST", headers:{"Content-Type":"application/json"}, body:"{}",
  });
  let response = await fetchTargets();
  if (!waitForPlayers || response.players_ready) return response;
   toast(uiText("inventory.reading_club_players"));
  if (!response.players_refreshing) {
    await request("/api/club/refresh", {
      method:"POST", headers:{"Content-Type":"application/json"}, body:"{}",
    });
  }
  for (let attempt = 0; attempt < CLUB_REFRESH_POLL_ATTEMPTS; attempt += 1) {
    await new Promise((resolve) => setTimeout(resolve, CLUB_REFRESH_POLL_MS));
    response = await fetchTargets();
    if (response.players_ready) return response;
    if (!response.players_refreshing && response.players_error) {
      throw new Error(response.players_error);
    }
  }
   throw new Error(uiText("inventory.club_players_timeout"));
}

async function openReputationItem(itemId) {
  const item = economyItem(itemId);
  if (!item || !REPUTATION_SKUS.has(item.sku) || item.status !== "available") {
     toast(uiText("inventory.brochure_unavailable"));
    return;
  }
  const targetKind = item.sku === "club_brochure" ? "club" : item.sku === "league_brochure" ? "league" : "player";
  const clubBrochure = targetKind === "club";
  const leagueBrochure = targetKind === "league";
  let response;
  try {
    response = await loadReputationTargets(targetKind === "player");
  } catch (error) {
    toast(error.message);
    return;
  }
  const targets = clubBrochure
    ? (response.clubs || [])
    : leagueBrochure ? (response.leagues || []) : (response.players || []);
  if (clubBrochure && Number(response.unavailable_acquired_count || 0) > 0) {
     toast(uiText("inventory.acquired_club_rescan"));
  }
  if (!targets.length) {
     toast(clubBrochure ? uiText("inventory.no_clubs") : leagueBrochure ? uiText("inventory.no_leagues") : uiText("inventory.no_first_team_players"));
    return;
  }
  $("#reputation-item-id").value = itemId;
  $("#reputation-item-kind").value = targetKind;
   $("#reputation-title").textContent = uiText("inventory.reputation_use_title", {name:localizedItemName(item)});
   $("#reputation-subtitle").textContent = clubBrochure
     ? uiText("inventory.reputation_club_subtitle")
     : leagueBrochure ? uiText("inventory.reputation_league_subtitle") : uiText("inventory.reputation_player_subtitle");
   $("#reputation-target-label").textContent = clubBrochure ? uiText("inventory.select_club") : leagueBrochure ? uiText("inventory.select_league") : uiText("inventory.select_player");
  $("#reputation-target").innerHTML = targets.map((target) => {
     const source = clubBrochure ? (target.source === "acquired" ? uiText("inventory.acquired") : uiText("inventory.managed")) : leagueBrochure ? uiText("inventory.league") : uiText("inventory.first_team");
    const rawReputation = target.reputation ?? target.world_reputation ?? target.international_reputation;
    const reputation = Number(rawReputation);
     const suffix = rawReputation != null && Number.isFinite(reputation) ? uiText("inventory.current_value", {value:reputation}) : "";
    const teamId = targetKind === "player" ? Number(target.team_id || 0) : 0;
    return `<option value="${Number(target.id)}"${teamId ? ` data-team-id="${teamId}"` : ""}>${escapeHtml(source)} · ${escapeHtml(target.name)}${suffix}</option>`;
  }).join("");
  $("#reputation-dialog").showModal();
}

