function manualPlayer() {
  return allManagedPlayers().find((player) => Number(player.id) === Number(app.manualPlayerId)) || null;
}

function manualAttributeRows(player) {
  return Object.entries(player?.attributes || {}).flatMap(([group, values]) =>
    Object.entries(values || {}).map(([name, value]) => ({group, name, key:`${group}:${name}`, original:Number(value)}))
  ).filter((row) => Number.isFinite(row.original));
}

function manualAllocationTotals() {
  const deltas = Object.values(app.manualChanges || {}).map(Number);
  const removed = deltas.reduce((total, value) => total + Math.max(-value, 0), 0);
  const added = deltas.reduce((total, value) => total + Math.max(value, 0), 0);
  return {removed, added, available:removed - added};
}

function availableItemIds(sku, preferredId, quantity) {
  const rows = [...availableEconomyItems(sku)];
  rows.sort((left, right) => left.id === preferredId ? -1 : right.id === preferredId ? 1 : 0);
  return rows.slice(0, Math.max(1, Number(quantity) || 1)).map((item) => item.id);
}

function renderQuantityOptions(selector, maximum) {
  const node = $(selector);
  const previous = Math.min(Math.max(1, Number(node.value) || 1), maximum);
   node.innerHTML = Array.from({length:maximum}, (_value, index) => `<option value="${index + 1}">${uiText("inventory.quantity", {count:index + 1})}</option>`).join("");
  node.value = String(previous);
}

let manualFormulaPreviewTimer = null;

function resetManualFormulaPreview() {
  if (manualFormulaPreviewTimer) clearTimeout(manualFormulaPreviewTimer);
  manualFormulaPreviewTimer = null;
  app.manualFormulaPreview = null;
  app.manualPreviewRequestKey += 1;
}

function manualReallocationPayload() {
  const player = manualPlayer();
  const item = economyItem(app.manualItemId);
  const quantity = Math.max(1, Number($("#manual-quantity").value) || 1);
  if (!item || !player) return null;
  const changedRows = new Map(manualAttributeRows(player).filter((row) => app.manualChanges[row.key]).map((row) => [row.key, row]));
  return {
    item_ids:availableItemIds(item.sku, app.manualItemId, quantity),
    player_id:Number(player.id),
    team_id:managedPlayerTeamId(player.id),
    changes:{...app.manualChanges},
    expected:Object.fromEntries([...changedRows].map(([key, row]) => [key, row.original])),
  };
}

function setInventoryDialogBusy(selector, busy) {
  const dialog = $(selector);
  const content = dialog?.querySelector(".attribute-reallocation-content");
  content?.setAttribute("aria-busy", String(Boolean(busy)));
  const hint = dialog?.querySelector("[id$='confirm-hint']");
  hint?.setAttribute("role", "status");
  hint?.setAttribute("aria-live", "polite");
}

function manualReallocationSignature(payload) {
  return JSON.stringify(payload || null);
}

function queueManualFormulaPreview(payload, signature) {
  if (app.manualFormulaPreview?.signature === signature) return;
  if (manualFormulaPreviewTimer) clearTimeout(manualFormulaPreviewTimer);
  const requestKey = ++app.manualPreviewRequestKey;
  app.manualFormulaPreview = {signature, status:"pending", valid:false};
  manualFormulaPreviewTimer = setTimeout(async () => {
    manualFormulaPreviewTimer = null;
    try {
      const result = await request("/api/inventory/reallocate-attributes/preview", {
        method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload),
      });
      if (requestKey !== app.manualPreviewRequestKey || manualReallocationSignature(manualReallocationPayload()) !== signature) return;
      app.manualFormulaPreview = {signature, status:"ready", ...result};
    } catch (error) {
      if (requestKey !== app.manualPreviewRequestKey || manualReallocationSignature(manualReallocationPayload()) !== signature) return;
       app.manualFormulaPreview = {signature, status:"error", valid:false, message:error.message || uiText("inventory.formula_check_failed")};
    }
    renderManualReallocation();
  }, 120);
}

function renderQuantityValues(selector, values) {
  const node = $(selector);
  const previous = Number(node.value) || 1;
  const normalized = [...new Set((values || []).map(Number).filter((value) => Number.isInteger(value) && value > 0))].sort((left, right) => left - right);
   node.innerHTML = normalized.length
     ? normalized.map((value) => `<option value="${value}">${uiText("inventory.formula_quantity", {count:value})}</option>`).join("")
     : `<option value="">${uiText("inventory.no_valid_quantity")}</option>`;
  node.value = String(normalized.includes(previous) ? previous : normalized[0] || "");
}

function formulaMilestones(player, row, downgrade = false) {
  const costs = player?.training_ca?.costs?.[row?.key];
  const source = costs?.[downgrade ? "downgrade_milestones" : "milestones"];
  return Array.isArray(source) ? source : [];
}

function formulaMilestoneForBudget(player, row, budget, downgrade = false) {
  return formulaMilestones(player, row, downgrade).find((entry) => {
    const change = Number(entry.ca_change);
    return downgrade ? change === -Number(budget) : change === Number(budget);
  }) || null;
}

function firstFormulaCaChange(player, row) {
  return formulaMilestones(player, row).find((entry) => Number(entry.ca_change) > 0) || null;
}

function developmentFormulaOptions(item, player, selectedRow = null) {
  if (!["enlightenment", "random_enlightenment", "extremely_unstable_enlightenment"].includes(item?.sku)) return [];
  const owned = availableItemIds(item.sku, item.id, 99).length;
  const ca = Number(player?.ca); const pa = Number(player?.pa);
  const rows = selectedRow ? [selectedRow] : manualAttributeRows(player);
  const values = new Set();
  rows.forEach((row) => {
    formulaMilestones(player, row).forEach((entry) => {
      const change = Number(entry.ca_change);
      if (change > 0 && change <= owned && ca + change <= pa) values.add(change);
    });
    if (item.sku === "extremely_unstable_enlightenment") {
      formulaMilestones(player, row, true).forEach((entry) => {
        const change = Number(entry.ca_change);
        if (change < 0 && -change <= owned && ca + change >= 1) values.add(-change);
      });
    }
  });
  return [...values].sort((left, right) => left - right);
}

async function openManualReallocation(itemId) {
  const item = economyItem(itemId);
  const limit = REALLOCATION_LIMITS[item?.sku];
  if (!item || !limit || item.status !== "available") { toast(uiText("development.manual_unavailable")); return; }
  if (!managedRostersAreCurrent()) {
    toast(uiText("development.player_data_loading"));
    try { await ensureManagedRostersLoaded(true); } catch (error) { toast(error.message); return; }
  }
  const players = allManagedPlayers().filter((player) => manualAttributeRows(player).some((row) => row.original < limit));
  if (!players.length) { toast(uiText("development.no_players")); return; }
  app.manualItemId = itemId;
  app.manualPlayerId = Number(players[0].id);
  app.manualChanges = {};
  app.manualReallocationRenderSignature = null;
  resetManualFormulaPreview();
  $("#manual-title").textContent = localizedItemName(item);
  renderQuantityOptions("#manual-quantity", availableItemIds(item.sku, itemId, 99).length);
  $("#manual-player-select").innerHTML = players.map((player) => `<option value="${player.id}">${escapeHtml(player.name)} · ${escapeHtml(primaryPlayerPosition(player))} · ${escapeHtml(managedPlayerTeams(player.id).join(" / "))}</option>`).join("");
  renderManualReallocation();
  $("#attribute-reallocation-dialog").showModal();
  renderIcons();
}

function renderManualReallocation() {
  const player = manualPlayer();
  const item = economyItem(app.manualItemId);
  const limit = REALLOCATION_LIMITS[item?.sku] || 12;
  const quantity = Math.max(1, Number($("#manual-quantity").value) || 1);
  const maxPoints = quantity * 3;
  const rows = manualAttributeRows(player);
  const totals = manualAllocationTotals();
  const complete = totals.removed >= 1 && totals.removed <= maxPoints && totals.removed === totals.added;
  const payload = manualReallocationPayload();
  const payloadSignature = manualReallocationSignature(payload);
  if (complete) {
    queueManualFormulaPreview(payload, payloadSignature);
  } else if (app.manualFormulaPreview || manualFormulaPreviewTimer) {
    resetManualFormulaPreview();
  }
  const formulaPreview = app.manualFormulaPreview?.signature === payloadSignature ? app.manualFormulaPreview : null;
  const signature = JSON.stringify([
    String(app.state?.data_scope_id || ""), Number(app.state?.data_version || 0),
    item?.id || null, item?.status || "", player?.id || null, player?.ca, player?.pa,
    quantity, limit, rows.map((row) => [row.key, row.original]),
    app.manualChanges, complete,
    formulaPreview?.status || "", formulaPreview?.valid ?? null,
    formulaPreview?.formula_ca_change ?? null,
  ]);
  if (app.manualReallocationRenderSignature === signature) return;
  app.manualReallocationRenderSignature = signature;
   $("#manual-rule-text").textContent = uiText("inventory.manual_rule", {limit, quantity, maxPoints});
  const groups = new Map();
  rows.forEach((row) => { if (!groups.has(row.group)) groups.set(row.group, []); groups.get(row.group).push(row); });
  $("#manual-attribute-groups").innerHTML = [...groups.entries()].map(([group, groupRows]) => `<section class="manual-attribute-group"><h3>${escapeHtml(localizedTrainingAttributeGroup(group))}</h3><div>${groupRows.map((row) => {
    const delta = Number(app.manualChanges[row.key] || 0);
    const current = row.original + delta;
    const eligible = row.original < limit;
    const canDown = eligible && current > 1 && (delta > 0 || totals.removed < maxPoints);
    const canUp = eligible && current < limit && (delta < 0 || totals.available > 0);
    const changedClass = delta > 0 ? "increased" : delta < 0 ? "decreased" : "";
    const displayName = localizedTrainingAttribute(row.key || row.name);
     return `<div class="manual-attribute-row ${eligible ? "" : "locked"}"><span>${escapeHtml(displayName)}${eligible ? "" : `<small>${uiText("inventory.original_locked", {limit})}</small>`}</span><div class="manual-stepper"><button type="button" data-manual-key="${escapeHtml(row.key)}" data-manual-delta="1" aria-label="${uiText("inventory.increase", {name:displayName})}" ${canUp ? "" : "disabled"}>∧</button><strong class="${changedClass}">${current}</strong><button type="button" data-manual-key="${escapeHtml(row.key)}" data-manual-delta="-1" aria-label="${uiText("inventory.decrease", {name:displayName})}" ${canDown ? "" : "disabled"}>∨</button></div></div>`;
   }).join("")}</div></section>`).join("") || `<div class="empty-feature">${uiText("inventory.no_adjustable_attributes")}</div>`;
  const formulaValid = complete;
  $("#manual-reallocation-confirm").disabled = !formulaValid;
  $("#manual-confirm-hint").textContent = !complete
     ? totals.available > 0 ? uiText("inventory.points_pending", {count:totals.available}) : totals.removed ? uiText("inventory.points_mismatch") : uiText("inventory.remove_first")
     : formulaPreview?.status === "pending" ? uiText("inventory.formula_checking", {count:totals.removed})
     : formulaPreview?.status === "error" ? uiText("inventory.formula_preview_unavailable", {count:totals.removed})
     : formulaPreview?.valid ? uiText("inventory.formula_conserved", {count:totals.removed})
     : uiText("inventory.formula_delta", {sign:Number(formulaPreview.formula_ca_change) >= 0 ? "+" : "", change:Number(formulaPreview.formula_ca_change), count:totals.removed});
}

async function submitManualReallocation() {
  const player = manualPlayer();
  const totals = manualAllocationTotals();
  const item = economyItem(app.manualItemId);
  const quantity = Math.max(1, Number($("#manual-quantity").value) || 1);
  const payload = manualReallocationPayload();
  const signature = manualReallocationSignature(payload);
  if (!item || !player || !payload || totals.removed < 1 || totals.removed > quantity * 3 || totals.removed !== totals.added) return;
  const button = $("#manual-reallocation-confirm");
   button.disabled = true; button.textContent = uiText("inventory.confirming_attributes");
  setInventoryDialogBusy("#attribute-reallocation-dialog", true);
  try {
    const result = await request("/api/inventory/reallocate-attributes", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)});
    $("#attribute-reallocation-dialog").close();
    const updated = result.player;
    if (updated?.attributes) updateManagedPlayer(updated.player_id, {attributes:updated.attributes});
    app.manualItemId = null; app.manualPlayerId = null; app.manualChanges = {}; resetManualFormulaPreview();
    await applyStatePatchOrReload(result);
    renderClub();
     toast(uiText("inventory.reallocated", {name:player.name, count:totals.removed}));
  } catch (error) {
     toast(error.message || uiText("inventory.reallocation_failed"));
     button.disabled = false; button.textContent = uiText("inventory.confirm");
  } finally {
    setInventoryDialogBusy("#attribute-reallocation-dialog", false);
  }
}

function developmentItem() {
  return economyItem(app.developmentItemId);
}

function developmentPlayer() {
  return allManagedPlayers().find((player) => Number(player.id) === Number(app.developmentPlayerId)) || null;
}

function playerEligibleForDevelopment(player, sku) {
  const ca = Number(player?.ca);
  const pa = Number(player?.pa);
  if (!Number.isFinite(ca) || !Number.isFinite(pa) || ca < 1 || pa > 200 || ca > pa) return false;
  if (["enlightenment", "random_enlightenment", "extremely_unstable_enlightenment"].includes(sku)) return ca < pa;
  if (BREAKTHROUGH_PA_LIMITS[sku]) return pa < BREAKTHROUGH_PA_LIMITS[sku];
  if (LATENT_DRAGON_PA_LIMITS[sku]) return pa < LATENT_DRAGON_PA_LIMITS[sku];
  return false;
}

function developmentCapacity(item, player, row = null) {
  const owned = availableItemIds(item.sku, item.id, 99).length;
  const ca = Number(player.ca); const pa = Number(player.pa);
  if (LATENT_DRAGON_PA_LIMITS[item.sku]) return Math.max(0, Math.min(owned, LATENT_DRAGON_PA_LIMITS[item.sku] - pa));
  if (BREAKTHROUGH_PA_LIMITS[item.sku]) return Math.max(0, Math.min(owned, BREAKTHROUGH_PA_LIMITS[item.sku] - pa));
  const formulaOptions = developmentFormulaOptions(item, player, row);
  if (formulaOptions.length) return formulaOptions[formulaOptions.length - 1];
  return 0;
}

async function openPlayerDevelopment(itemId) {
  const item = economyItem(itemId);
  if (!item || !GROWTH_SKUS.has(item.sku) || item.status !== "available") { toast(uiText("development.player_unavailable")); return; }
  try {
    await ensurePlayerDevelopmentRosterLoaded();
  } catch (error) {
    toast(error.message || uiText("development.formula_load_failed"));
    return;
  }
  const latent = Boolean(LATENT_DRAGON_PA_LIMITS[item.sku]);
  const breakthrough = Boolean(BREAKTHROUGH_PA_LIMITS[item.sku]);
  const randomized = RANDOM_GROWTH_SKUS.has(item.sku);
  const players = allManagedPlayers().filter((player) => playerEligibleForDevelopment(player, item.sku));
  if (!players.length) {
    const paLimit = BREAKTHROUGH_PA_LIMITS[item.sku] || LATENT_DRAGON_PA_LIMITS[item.sku];
    if (breakthrough) { toast(uiText("development.no_pa_below", {limit:paLimit})); return; }
    toast(uiText("development.no_eligible"));
    return;
  }
  app.developmentItemId = itemId;
  app.developmentPlayerId = Number(players[0].id);
  app.developmentAttributeKey = null;
  app.playerDevelopmentRenderSignature = null;
  $("#development-title").textContent = localizedItemName(item);
  const paLimit = BREAKTHROUGH_PA_LIMITS[item.sku] || LATENT_DRAGON_PA_LIMITS[item.sku];
   $("#development-subtitle").textContent = latent ? uiText("development.subtitle_latent") : breakthrough ? uiText("development.subtitle_breakthrough") : randomized ? uiText("development.subtitle_random") : uiText("development.subtitle_attribute");
   $("#development-rule-note").textContent = latent ? uiText("development.rule_latent", {limit:paLimit}) : breakthrough ? uiText("development.rule_breakthrough", {limit:paLimit}) : item.sku === "extremely_unstable_enlightenment" ? uiText("development.rule_unstable") : item.sku === "random_enlightenment" ? uiText("development.rule_random") : uiText("development.rule_normal");
  $("#development-player-select").innerHTML = players.map((player) => `<option value="${player.id}">${escapeHtml(player.name)} · ${escapeHtml(managedPlayerTeams(player.id).join(" / "))}${app.cheatMode ? ` · CA ${player.ca} / PA ${player.pa}` : ""}</option>`).join("");
  renderQuantityOptions("#development-quantity", Math.max(1, availableItemIds(item.sku, itemId, 99).length));
  renderPlayerDevelopment();
  $("#player-development-dialog").showModal();
  renderIcons();
}

function renderPlayerDevelopment() {
  const item = developmentItem();
  const player = developmentPlayer();
  if (!item || !player) return;
  const breakthrough = Boolean(BREAKTHROUGH_PA_LIMITS[item.sku]);
  const latent = Boolean(LATENT_DRAGON_PA_LIMITS[item.sku]);
  const randomized = RANDOM_GROWTH_SKUS.has(item.sku);
  const formulaGrowth = ["enlightenment", "random_enlightenment", "extremely_unstable_enlightenment"].includes(item.sku);
  const selectedRow = randomized ? null : manualAttributeRows(player).find((entry) => entry.key === app.developmentAttributeKey) || null;
  const capacity = developmentCapacity(item, player, selectedRow);
  const formulaOptions = formulaGrowth ? developmentFormulaOptions(item, player, selectedRow) : [];
  if (formulaGrowth) renderQuantityValues("#development-quantity", formulaOptions);
  else renderQuantityOptions("#development-quantity", Math.max(1, capacity));
  const quantity = Math.max(1, Number($("#development-quantity").value) || 1);
  const quantityValid = formulaGrowth ? formulaOptions.includes(quantity) : capacity >= quantity;
  const selectedPlan = selectedRow ? formulaMilestoneForBudget(player, selectedRow, quantity) : null;
  const rows = manualAttributeRows(player);
  const signature = JSON.stringify([
    String(app.state?.data_scope_id || ""), Number(app.state?.data_version || 0),
    item?.id || null, item?.status || "", player?.id || null, player?.ca, player?.pa,
    app.developmentAttributeKey, quantity, capacity, formulaOptions,
    app.cheatMode, rows.map((entry) => [entry.key, entry.original]),
    selectedPlan?.attribute_after ?? null, selectedPlan?.attribute_points ?? null,
  ]);
  if (app.playerDevelopmentRenderSignature === signature) return;
  app.playerDevelopmentRenderSignature = signature;
  $("#development-quantity").disabled = !quantityValid;
  $("#development-player-summary").hidden = !app.cheatMode;
  const randomCa = item.sku === "extremely_unstable_enlightenment";
   const caAfterText = randomCa ? uiText("development.ca_valid_result", {quantity}) : uiText("development.after_value", {value:Number(player.ca) + (latent ? 0 : quantity)});
   const attributeEffect = selectedPlan
     ? uiText("development.attribute_points", {before:selectedPlan.attribute_before, after:selectedPlan.attribute_after, sign:Number(selectedPlan.attribute_points) > 0 ? "+" : "", points:selectedPlan.attribute_points})
     : randomized ? uiText("development.random_formula_settlement") : uiText("development.choose_attribute");
   $("#development-player-summary").innerHTML = `<div><small>${uiText("development.current_ability")}</small><strong>CA ${player.ca}</strong><span>${caAfterText}</span></div><div><small>${uiText("development.potential_ability")}</small><strong>PA ${player.pa}</strong><span>${uiText("development.after_value", {value:Number(player.pa) + (breakthrough || latent ? quantity : 0)})}</span></div><div><small>${latent || breakthrough ? uiText("development.effect") : randomized ? uiText("development.random_attribute") : uiText("development.specified_attribute")}</small><strong>${latent ? `PA +${quantity}` : breakthrough ? `CA/PA +${quantity}` : randomized ? uiText("development.formula_random_settlement") : app.developmentAttributeKey ? escapeHtml(localizedTrainingAttribute(app.developmentAttributeKey)) : uiText("development.not_selected")}</strong><span>${latent || breakthrough ? uiText("development.visible_unchanged") : randomCa ? uiText("development.random_direction", {quantity}) : attributeEffect}</span></div>`;
  const groups = new Map();
  rows.forEach((row) => { if (!groups.has(row.group)) groups.set(row.group, []); groups.get(row.group).push(row); });
  $("#development-attribute-groups").hidden = latent || breakthrough || randomized;
  $("#development-attribute-groups").innerHTML = latent || breakthrough || randomized ? "" : [...groups.entries()].map(([group, groupRows]) => `<section class="manual-attribute-group"><h3>${escapeHtml(localizedTrainingAttributeGroup(group))}</h3><div>${groupRows.map((row) => {
    const caOne = formulaMilestoneForBudget(player, row, 1);
    const firstChange = firstFormulaCaChange(player, row);
    const available = row.original < 20 && Boolean(firstChange);
    const selected = app.developmentAttributeKey === row.key;
    const selectedTarget = selected ? formulaMilestoneForBudget(player, row, quantity) : null;
    const formulaLabel = selectedTarget
      ? `${row.original} → ${selectedTarget.attribute_after} · CA+${quantity}`
      : caOne ? `${row.original} → ${caOne.attribute_after} · CA+1`
       : firstChange ? uiText("development.ca_first_change", {before:row.original, after:firstChange.attribute_after, change:firstChange.ca_change})
       : uiText("development.no_positive_ca", {value:row.original});
    return `<button type="button" class="development-attribute ${selected ? "selected" : ""}" data-development-key="${escapeHtml(row.key)}" ${available ? "" : "disabled"}><span>${escapeHtml(localizedTrainingAttribute(row.key || row.name))}</span><strong>${formulaLabel}</strong></button>`;
  }).join("")}</div></section>`).join("");
  $("#development-confirm").disabled = !quantityValid || (!latent && !breakthrough && !randomized && !selectedPlan);
   $("#development-confirm").textContent = latent || breakthrough || randomized ? uiText("development.confirm_use") : uiText("development.confirm_enhance_use");
  const selectedFirstChange = selectedRow ? firstFormulaCaChange(player, selectedRow) : null;
   $("#development-confirm-hint").textContent = latent ? uiText("development.hint_latent", {name:player.name, quantity}) : breakthrough ? uiText("development.hint_breakthrough", {name:player.name, quantity}) : randomized && quantityValid ? uiText("development.hint_random", {quantity}) : selectedPlan ? uiText("development.hint_selected", {name:localizedTrainingAttribute(selectedRow.key || selectedRow.name), before:selectedPlan.attribute_before, after:selectedPlan.attribute_after, quantity}) : selectedFirstChange ? uiText("development.hint_first_change", {name:localizedTrainingAttribute(selectedRow.key || selectedRow.name), change:selectedFirstChange.ca_change, required:selectedFirstChange.ca_change}) : app.developmentAttributeKey ? uiText("development.no_positive_landing") : quantityValid ? uiText("development.choose_attribute_hint") : uiText("development.no_formula_landing");
}

async function submitPlayerDevelopment() {
  const item = developmentItem();
  const player = developmentPlayer();
  const latent = Boolean(LATENT_DRAGON_PA_LIMITS[item?.sku]);
  const breakthrough = Boolean(BREAKTHROUGH_PA_LIMITS[item?.sku]);
  const randomized = RANDOM_GROWTH_SKUS.has(item?.sku);
  const row = latent || breakthrough || randomized ? null : manualAttributeRows(player).find((entry) => entry.key === app.developmentAttributeKey);
  const quantity = Math.max(1, Number($("#development-quantity").value) || 1);
  const formulaGrowth = ["enlightenment", "random_enlightenment", "extremely_unstable_enlightenment"].includes(item?.sku);
  const formulaOptions = formulaGrowth && item && player ? developmentFormulaOptions(item, player, row) : [];
  const quantityValid = formulaGrowth ? formulaOptions.includes(quantity) : developmentCapacity(item, player, row) >= quantity;
  if (!item || !player || !quantityValid || (!latent && !breakthrough && !randomized && (!row || !formulaMilestoneForBudget(player, row, quantity)))) { toast(uiText("development.submit_invalid")); return; }
  const button = $("#development-confirm");
   button.disabled = true; button.textContent = uiText("development.confirming_player");
  setInventoryDialogBusy("#player-development-dialog", true);
  try {
    const payload = {item_ids:availableItemIds(item.sku, item.id, quantity), player_id:Number(player.id), team_id:managedPlayerTeamId(player.id)};
    if (!latent && !breakthrough && !randomized) Object.assign(payload, {attribute_key:row.key, expected_attribute:row.original});
    const result = await request("/api/inventory/develop-player", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)});
    $("#player-development-dialog").close();
    const updated = result.player;
    updateManagedPlayer(updated?.player_id, {attributes:updated?.attributes, training_ca:updated?.training_ca, ca:updated?.ca, pa:updated?.pa});
    app.developmentItemId = null; app.developmentPlayerId = null; app.developmentAttributeKey = null;
    await applyStatePatchOrReload(result);
    renderClub();
     if (latent) toast(uiText("development.success_latent", {item:localizedItemName(item), name:player.name, quantity}));
     else if (breakthrough) toast(uiText("development.success_breakthrough", {item:localizedItemName(item), name:player.name, quantity}));
     else if (randomized) toast(uiText("development.success_random", {item:localizedItemName(item), name:player.name, before:updated.ca_before, after:updated.ca_after}));
     else toast(uiText("development.success_attribute", {item:localizedItemName(item), name:player.name, attribute:localizedTrainingAttribute(row.key || row.name), before:updated.attribute_before, after:updated.attribute_after, caBefore:updated.ca_before, caAfter:updated.ca_after}));
  } catch (error) {
    toast(error.message || uiText("development.use_failed"));
     button.disabled = false; button.textContent = latent || breakthrough || randomized ? uiText("development.confirm_use") : uiText("development.confirm_enhance_use");
  } finally {
    setInventoryDialogBusy("#player-development-dialog", false);
  }
}

function primaryPlayerPosition(player) {
  const primary = player.primary_positions || [];
  if (primary.length) return primary[0];
  const ratings = Object.entries(player.position_ratings || {});
  ratings.sort((left, right) => Number(right[1]) - Number(left[1]));
   return ratings[0]?.[0] || player.positions?.[0] || uiText("activity.unknown_position");
}

function playerCardPositions(player) {
  return Object.entries(player.position_ratings || {})
    .filter(([, value]) => Number(value) > 1)
    .sort((left, right) => Number(right[1]) - Number(left[1]))
    .map(([name]) => name);
}

function playerCardBadge(player) {
  app.playerCardPositionModes ||= new Map();
  const positions = playerCardPositions(player);
  const mode = Number(app.playerCardPositionModes.get(Number(player.id)) || 0);
  if (mode > 0 && positions.length) return positions[(mode - 1) % positions.length];
  const number = player.shirt_number ?? player.player_contract?.squad_number;
  return number != null ? String(number) : "-";
}

function cyclePlayerCardPosition(playerId) {
  const player = (app.club?.players || []).find((row) => Number(row.id) === Number(playerId));
  if (!player) return;
  app.playerCardPositionModes ||= new Map();
  const total = playerCardPositions(player).length + 1;
  const current = Number(app.playerCardPositionModes.get(Number(player.id)) || 0);
  app.playerCardPositionModes.set(Number(player.id), (current + 1) % Math.max(total, 1));
  renderClub();
}

function compactMoney(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount) || amount < 0) return "-";
  const compact = (number, suffix) => `${number.toFixed(1)}${suffix}`;
  const unit = moneyAbbreviationUnit(amount);
  if (unit) return `£${compact(amount / unit[0], unit[1])}`;
  return `£${Math.round(amount)}`;
}

function ownedClubMoney(value, unavailable = false) {
  if (unavailable) return uiText("world.not_read");
  if (value == null) return uiText("world.reading");
  const amount = Number(value);
  return Number.isFinite(amount) ? formatMoney(amount) : uiText("world.not_read");
}

function ownedClubCount(value, suffix = "") {
  const amount = Number(value);
  return Number.isFinite(amount) && amount >= 0
    ? `${Math.round(amount).toLocaleString(activeUiLocale())}${suffix}`
    : uiText("world.not_read");
}

function ownedClubSignedMoney(value, unavailable = false) {
  if (unavailable || value == null) return unavailable ? uiText("world.not_read") : uiText("world.reading");
  const amount = Number(value);
  if (!Number.isFinite(amount)) return uiText("world.not_read");
  if (amount === 0) return formatMoney(0);
  return `${amount > 0 ? "+" : "-"}${formatMoney(Math.abs(amount))}`;
}

function ownedClubDividendEstimate(metrics) {
  const forecast = metrics?.dividend_forecast;
  if (!forecast) return metrics?.unavailable ? uiText("world.not_read") : uiText("portfolio.card.last_month_profit_unread");
  const profit = Number(forecast.profit);
  if (Number.isFinite(profit) && profit < 0) {
    return uiText("portfolio.card.last_month_loss", {amount:ownedClubSignedMoney(profit)});
  }
  return ownedClubMoney(metrics.estimated_dividend, metrics.unavailable);
}

function ownedClubDebtMetric(metrics, teamId) {
  const label = ownedClubMoney(metrics?.debt, metrics?.unavailable);
  const debt = Number(metrics?.debt || 0);
  if (!(debt > 0) || metrics?.unavailable) return ownedClubMetric(uiText("portfolio.card.debt"), label);
  return `<div class="owned-debt-metric"><dt>${uiText("portfolio.card.debt")}</dt><dd><button type="button" data-world-debt="${Number(teamId)}" title="${uiText("portfolio.debt.pay_all")}"><span>${escapeHtml(label)}</span><i data-lucide="hand-coins"></i></button></dd></div>`;
}

function ownedClubValuationChangeParts(metrics) {
  if (metrics?.unavailable) return {amount:uiText("world.not_read"), percent:""};
  if (metrics?.valuation_change == null) return {amount:uiText("world.reading"), percent:""};
  const percent = Number(metrics.valuation_change_percent);
  return {
    amount: ownedClubSignedMoney(metrics.valuation_change),
    percent: Number.isFinite(percent)
      ? `${percent > 0 ? "+" : ""}${percent.toFixed(1)}%`
      : "",
  };
}

function ownedClubValuationChange(metrics) {
  const change = ownedClubValuationChangeParts(metrics);
  return [change.amount, change.percent].filter(Boolean).join(" · ");
}

function ownedClubAcquisitionMetric(metrics) {
  const netCost = metrics?.net_acquisition_cost ?? metrics?.acquisition_price;
  const cost = ownedClubMoney(netCost, metrics?.unavailable);
  const change = ownedClubValuationChangeParts(metrics);
  const amount = Number(metrics?.valuation_change);
  const tone = Number.isFinite(amount) && amount > 0
    ? "profit"
    : Number.isFinite(amount) && amount < 0 ? "loss" : "neutral";
  return `<div class="owned-acquisition-metric"><dt>${uiText("owned.detail.acquisition_cost")}</dt><dd><strong>${escapeHtml(cost)}</strong><small class="owned-acquisition-comparison"><span>${uiText("portfolio.card.relative_to_price")}</span><span class="owned-acquisition-change-stack"><b class="owned-acquisition-change ${tone}">${escapeHtml(change.amount)}</b>${change.percent ? `<b class="owned-acquisition-percent ${tone}">${escapeHtml(change.percent)}</b>` : ""}</span></small></dd></div>`;
}

function ownedClubHistoricalMetric(label, value, comparisonLabel, comparison) {
  const amount = Number(comparison?.change);
  const percent = Number(comparison?.change_percent);
  const available = comparison != null && Number.isFinite(amount);
  const tone = available && amount > 0
    ? "profit"
    : available && amount < 0 ? "loss" : "neutral";
  const change = available
    ? `${amount > 0 ? "+" : ""}${Math.round(amount).toLocaleString(activeUiLocale())}`
    : uiText("portfolio.card.no_record");
  const percentLabel = available && Number.isFinite(percent)
    ? `${percent > 0 ? "+" : ""}${percent.toFixed(1)}%`
    : "";
  return `<div class="owned-history-metric"><dt>${escapeHtml(label)}</dt><dd><strong>${escapeHtml(value)}</strong><small class="owned-acquisition-comparison"><span>${escapeHtml(comparisonLabel)}</span><span class="owned-acquisition-change-stack"><b class="owned-acquisition-change ${tone}">${escapeHtml(change)}</b>${percentLabel ? `<b class="owned-acquisition-percent ${tone}">${escapeHtml(percentLabel)}</b>` : ""}</span></small></dd></div>`;
}

function playerNationalityLabel(player) {
  const rows = [
    {id:player.nationality_id, name:player.nationality},
    player.second_nationality,
  ].filter((row) => row && (row.id || row.name));
  return rows.map(localizedNationName).filter(Boolean).join(" / ") || uiText("world.not_read");
}

function playerPositionGroup(player) {
  const position = primaryPlayerPosition(player);
  if (position === "GK") return "goalkeepers";
  if (["ST", "AML", "AMC", "AMR"].includes(position)) return "forwards";
  if (["DM", "ML", "MC", "MR"].includes(position)) return "midfielders";
  return "defenders";
}

function renderPlayerCard(player) {
  const ability = `<strong>CA ${player.ca ?? "-"} / PA ${player.pa ?? "-"}</strong>`;
  const wage = player.player_contract?.wage_per_week;
  const askingPrice = player.transfer?.asking_price ?? player.asking_price;
  const heightLabel = player.height_cm ? `${player.height_cm} cm` : uiText("world.not_read");
  const nationalityLabel = playerNationalityLabel(player);
  const wageLabel = compactMoney(wage);
  const askingPriceLabel = compactMoney(askingPrice);
  const injured = Number(player.availability?.injury_count || 0) > 0 || (player.availability?.injuries || []).length > 0;
  const loanedOut = Boolean(player.is_loaned_out || player.loan?.is_loaned_out);
  const injuryCross = injured ? `<span class="player-injury-cross" title="${uiText("world.club.player.injured")}" aria-label="${uiText("world.club.player.injured")}">+</span>` : "";
  const badge = playerCardBadge(player);
  const badgePrefix = badge === "-"
    ? ""
    : `<span class="player-card-identity-prefix">${escapeHtml(badge)}#</span>`;
  const portraitFallback = playerCardPositions(player)[0] || primaryPlayerPosition(player);
  const playerName = player.name || uiText("world.club.player.fallback");
  return `<article class="person-card player-card" data-player-detail="${player.id}" role="button" tabindex="0" aria-label="${uiText("world.view_details", {name:escapeHtml(playerName)})}"><span class="position-badge player-number-cycle player-card-portrait-frame" data-player-position-cycle="${player.id}" role="button" tabindex="0" aria-label="${uiText("world.club.player.cycle_aria", {player:escapeHtml(playerName)})}" title="${uiText("world.club.player.cycle_title")}">${legacyPortraitMarkup(player, "club-player-portrait", {defer:Boolean(app.clubStatus?.refreshing), fallbackText:portraitFallback})}</span><div class="person-card-main"><h3 class="${loanedOut ? "loaned-out" : ""}">${badgePrefix}<span class="player-card-name">${escapeHtml(player.name)}</span>${injuryCross}</h3>${ability}</div><div class="person-card-facts player-card-facts"><span><small>${uiText("world.club.player.height")}</small><b title="${escapeHtml(heightLabel)}">${escapeHtml(heightLabel)}</b></span><span><small>${uiText("world.column.nationality")}</small><b class="nationality-value" title="${escapeHtml(nationalityLabel)}">${escapeHtml(nationalityLabel)}</b></span><span><small>${uiText("owned.detail.weekly_wage")}</small><b title="${escapeHtml(wageLabel)}">${escapeHtml(wageLabel)}</b></span><span><small>${uiText("world.club.player.value")}</small><b title="${escapeHtml(askingPriceLabel)}">${escapeHtml(askingPriceLabel)}</b></span></div></article>`;
}

function renderClubTeamNav() {
  const teams = managedTeams();
  const node = $("#club-team-subnav");
  if (!node) return;
  const signature = JSON.stringify([
    Number(app.clubTeamId || 0),
    teams.map((team) => [Number(team.id), team.name || "", team.team_type || "club"]),
  ]);
  if (app.clubTeamNavSignature === signature) return;
  app.clubTeamNavSignature = signature;
  node.innerHTML = teams.map((team) => {
    const type = uiText(team.team_type === "national" ? "world.club.my_national_team" : "world.club.managed_club");
    const icon = team.team_type === "national" ? "flag" : "building-2";
    const active = Number(team.id) === Number(app.clubTeamId);
    return `<button type="button" class="${active ? "active" : ""}" data-club-team="${Number(team.id)}" aria-current="${active ? "page" : "false"}" aria-label="${escapeHtml(uiText("world.club.team_nav_aria", {type, team:team.name || team.id}))}"><i data-lucide="${icon}"></i><span>${type}</span></button>`;
  }).join("");
  node.querySelectorAll("[data-club-team]").forEach((button) => button.addEventListener("click", () => {
    app.clubTeamId = Number(button.dataset.clubTeam);
    app.club = teamProfile(app.clubTeamId);
    app.clubTab = "players";
    app.clubSquadTeamId = null;
    showPage("club");
    renderClub();
  }));
  renderIcons(node);
}

async function loadWorldClubs({page = app.worldClubPage, background = false} = {}) {
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const requestedVersion = Number(app.state?.data_version || 0);
  const requestedResourceVersion = dataResourceVersionKey("world-clubs");
  const query = new URLSearchParams({page:String(page || 1), page_size:"15"});
  if (app.worldClubSearch) query.set("search", app.worldClubSearch);
  if (app.worldClubContinent) query.set("continent", app.worldClubContinent);
  if (app.worldClubNation) query.set("nation", app.worldClubNation);
  const requestSignature = `world-clubs:${requestedResourceVersion}:${query}`;
  const task = sharePageDataRequest(requestSignature, async () => {
    app.worldClubsLoading = true;
    app.worldClubsError = null;
    if (!background || ["world-clubs", "my-clubs"].includes(app.page)) {
      renderWorldClubs();
      renderMyClubs();
    }
    const requestKey = ++app.worldClubsRequestKey;
    try {
    const response = await request(`/api/world-clubs?${query}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (
      requestKey !== app.worldClubsRequestKey
      || requestedScope !== currentScope
      || requestedVersion !== Number(app.state?.data_version || 0)
      || requestedResourceVersion !== dataResourceVersionKey("world-clubs")
      || String(response.data_scope_id || "") !== requestedScope
      || !isSaveConnected()
    ) return app.worldClubs;
    app.worldClubs = response;
    app.worldClubsScope = requestedScope;
    app.worldClubsError = null;
    app.worldClubPage = Number(app.worldClubs?.pagination?.page || 1);
    rememberPageDataVersion("world-clubs");
    app.worldClubsLoading = false;
    if (!background || ["world-clubs", "my-clubs"].includes(app.page)) {
      renderWorldClubs();
      renderMyClubs();
    }
    if ((!background || app.page === "my-clubs") && activeOwnedClubs().length) {
      void loadPortfolioYouthOverview().catch(() => {});
    }
    if (!background || ["world-clubs", "my-clubs"].includes(app.page)) {
      syncWorldClubScanPolling(app.worldClubs);
    }
    return app.worldClubs;
    } catch (error) {
    if (requestKey === app.worldClubsRequestKey) {
      app.worldClubsLoading = false;
      app.worldClubsError = error.message || uiText("world.clubs.read_failed");
      if (!background || ["world-clubs", "my-clubs"].includes(app.page)) {
        renderWorldClubs();
        renderMyClubs();
      }
      if (!background) toast(app.worldClubsError);
    }
    return null;
    } finally {
    if (requestKey === app.worldClubsRequestKey) app.worldClubsLoading = false;
    }
  });
  app.worldClubsLoadPromise = task;
  try {
    return await task;
  } finally {
    if (app.worldClubsLoadPromise === task) app.worldClubsLoadPromise = null;
  }
}

function worldPlayerSummaryScope(response = null) {
  const scope = String(
    response?.data_scope_id || app.state?.data_scope_id
    || output().save_instance_id || "",
  );
  const gameDate = String(
    response?.game_date || app.gameClock?.date
    || app.state?.game_clock?.date || output().game_date || "",
  );
  const sessionGeneration = Number(
    response?.index?.session_generation
    ?? app.worldPlayers?.index?.session_generation ?? 0,
  );
  return `${scope}:${sessionGeneration}:${gameDate}`;
}

function prepareWorldPlayerSummaryCache(response) {
  const summaryScope = worldPlayerSummaryScope(response);
  if (app.worldPlayerSummaryScope !== summaryScope) {
    app.worldPlayerSummaryScope = summaryScope;
    app.worldPlayerSummaryCache.clear();
  }
  const players = (response?.players || []).map((player) => {
    const cached = app.worldPlayerSummaryCache.get(Number(player.id));
    return cached ? {...cached, ...player} : player;
  });
  return {...response, players};
}

function rememberWorldPlayerSummaries(response) {
  const prepared = prepareWorldPlayerSummaryCache(response);
  for (const player of prepared.players || []) {
    if (player.summary_live === true) {
      app.worldPlayerSummaryCache.set(Number(player.id), {...player});
    }
  }
  return prepared;
}

function rememberWorldPlayerSummary(player) {
  if (!player?.id) return;
  const summaryScope = worldPlayerSummaryScope();
  if (app.worldPlayerSummaryScope !== summaryScope) {
    app.worldPlayerSummaryScope = summaryScope;
    app.worldPlayerSummaryCache.clear();
  }
  app.worldPlayerSummaryCache.set(Number(player.id), {
    ...(app.worldPlayerSummaryCache.get(Number(player.id)) || {}),
    ...player,
    summary_live:true,
  });
}

function worldPlayerQuery({page = app.worldPlayerPage, force = false, live = false} = {}) {
  const query = new URLSearchParams({
    page:String(page || 1), page_size:"30", search:app.worldPlayerSearch || "",
    sort_by:app.worldPlayerSort || "pa", sort_order:app.worldPlayerSortOrder || "desc",
    gender:app.worldPlayerGender || "men", live:live ? "1" : "0",
  });
  [
    ["nationality_id", app.worldPlayerNationalityId],
    ["min_age", app.worldPlayerMinAge], ["max_age", app.worldPlayerMaxAge],
    ["min_ca", app.worldPlayerMinCa], ["max_ca", app.worldPlayerMaxCa],
    ["min_pa", app.worldPlayerMinPa], ["max_pa", app.worldPlayerMaxPa],
  ].forEach(([key, value]) => {
    if (value != null && Number(value) > 0) query.set(key, String(Number(value)));
  });
  if (force) query.set("refresh", "1");
  return query;
}

async function hydrateWorldPlayerPage(query, requestKey, hydrationKey, requestedScope) {
  const visible = app.worldPlayers?.players || [];
  if (!visible.length || visible.every((player) => player.summary_live === true)) return;
  app.worldPlayersHydrating = true;
  syncWorldPlayerPageStatus();
  const liveQuery = new URLSearchParams(query);
  liveQuery.set("live", "1");
  liveQuery.delete("refresh");
  try {
    const response = await request(`/api/world-players?${liveQuery}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (
      requestKey !== app.worldPlayersRequestKey
      || hydrationKey !== app.worldPlayerHydrationRequestKey
      || requestedScope !== currentScope
      || String(response.data_scope_id || "") !== requestedScope
      || !isSaveConnected()
    ) return;
    app.worldPlayers = rememberWorldPlayerSummaries(response);
    app.worldPlayersScope = requestedScope;
    app.worldPlayerPage = Number(response.pagination?.page || 1);
    app.worldPlayersError = null;
    renderWorldPlayers();
  } catch (error) {
    if (
      requestKey === app.worldPlayersRequestKey
      && hydrationKey === app.worldPlayerHydrationRequestKey
    ) toast(error.message || uiText("world.players.page_update_failed"));
  } finally {
    if (hydrationKey === app.worldPlayerHydrationRequestKey) {
      app.worldPlayersHydrating = false;
      syncWorldPlayerPageStatus();
    }
  }
}

async function loadWorldPlayers({
  page = app.worldPlayerPage, force = false, background = false,
  hydrate = !background,
} = {}) {
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const requestedVersion = Number(app.state?.data_version || 0);
  const requestedResourceVersion = dataResourceVersionKey("world-players");
  const query = worldPlayerQuery({page, force, live:false});
  const requestSignature = `world-players:${requestedResourceVersion}:${query}`;
  const task = sharePageDataRequest(requestSignature, async () => {
    app.worldPlayersLoading = true;
    app.worldPlayersRebuilding = Boolean(force);
    app.worldPlayersHydrating = false;
    app.worldPlayersError = null;
    const hydrationKey = ++app.worldPlayerHydrationRequestKey;
    if (force) {
      app.worldPlayerSummaryScope = "";
      app.worldPlayerSummaryCache.clear();
    }
    if (!background || app.page === "world-players") renderWorldPlayers();
    const requestKey = ++app.worldPlayersRequestKey;
    try {
    const requestQuery = new URLSearchParams(query);
    if (background) requestQuery.set("background", "1");
    const response = await request(`/api/world-players?${requestQuery}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (requestKey !== app.worldPlayersRequestKey || requestedScope !== currentScope
        || requestedVersion !== Number(app.state?.data_version || 0)
        || requestedResourceVersion !== dataResourceVersionKey("world-players")
        || String(response.data_scope_id || "") !== requestedScope || !isSaveConnected()) return app.worldPlayers;
    app.worldPlayers = prepareWorldPlayerSummaryCache(response);
    app.worldPlayersScope = requestedScope;
    app.worldPlayerPage = Number(response.pagination?.page || 1);
    app.worldPlayersError = null;
    rememberPageDataVersion("world-players");
    if (!background || app.page === "world-players") renderWorldPlayers();
    if (hydrate || app.page === "world-players") {
      void hydrateWorldPlayerPage(query, requestKey, hydrationKey, requestedScope);
    }
    return app.worldPlayers;
    } catch (error) {
    if (requestKey === app.worldPlayersRequestKey) {
      app.worldPlayersError = error.message || uiText("world.players.read_failed");
      if (!background) toast(app.worldPlayersError);
    }
    return null;
    } finally {
    if (requestKey === app.worldPlayersRequestKey) {
      app.worldPlayersLoading = false;
      app.worldPlayersRebuilding = false;
      if (!background || app.page === "world-players") renderWorldPlayers();
    }
    }
  });
  app.worldPlayersLoadPromise = task;
  try {
    return await task;
  } finally {
    if (app.worldPlayersLoadPromise === task) app.worldPlayersLoadPromise = null;
  }
}

function hydrateCurrentWorldPlayerPage() {
  if (!app.worldPlayers?.players?.length || app.worldPlayersHydrating) return;
  if (app.worldPlayers.players.every((player) => player.summary_live === true)) return;
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const hydrationKey = ++app.worldPlayerHydrationRequestKey;
  const query = worldPlayerQuery({page:app.worldPlayerPage, live:false});
  void hydrateWorldPlayerPage(
    query, app.worldPlayersRequestKey, hydrationKey, requestedScope,
  );
}

function worldPlayerRow(player) {
  const value = (entry) => entry == null || entry === "" ? "-" : escapeHtml(entry);
  const positions = (player.positions || []).join("/") || "-";
  return `<div class="world-player-row" role="row" tabindex="0" aria-label="${uiText("world.view_details", {name:escapeHtml(player.name || String(player.id))})}" data-world-player-detail="${Number(player.id || 0)}"><span class="world-player-name" role="cell" title="UID ${Number(player.id || 0)}"><strong>${escapeHtml(player.name || String(player.id))}</strong></span><span role="cell">${value(player.age)}</span><span role="cell">${value(player.ca)}</span><span role="cell">${value(player.pa)}</span><span role="cell">${escapeHtml(localizedNationName({id:player.nationality_id,name:player.nationality}) || uiText("world.not_read"))}</span><span role="cell">${escapeHtml(player.team_name || "-")}</span><span role="cell">${compactMoney(player.asking_price)}</span><span role="cell">${escapeHtml(positions)}</span></div>`;
}

function worldPlayerSortHeader(field, label, filters = {}) {
  const selected = String(filters.sort_by || app.worldPlayerSort || "pa");
  const selectedOrder = String(filters.sort_order || app.worldPlayerSortOrder || "desc");
  const active = selected === field;
  const order = active ? selectedOrder : "none";
  const arrow = active ? (order === "asc" ? "↑" : "↓") : "↕";
  const ariaSort = active ? (order === "asc" ? "ascending" : "descending") : "none";
  return `<span role="columnheader" aria-sort="${ariaSort}"><button type="button" class="world-player-sort-button${active ? " active" : ""}" data-world-player-sort="${field}" aria-label="${uiText("world.sort_by", {label})}">${label}<span aria-hidden="true">${arrow}</span></button></span>`;
}

async function openWorldPlayerDetail(playerId) {
  const dialog = $("#club-detail-dialog");
  const content = $("#club-detail-content");
  if (!dialog || !content) return;
  const scope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const requestKey = ++app.worldPlayerDetailRequestKey;
  const cached = worldPlayerDataIndex().playersById.get(Number(playerId));
  $("#club-detail-title").textContent = cached?.name || uiText("world.player_detail.player_profile");
  $("#club-detail-subtitle").textContent = uiText("world.players.detail_loading");
  content.classList.remove("player-detail-content");
  content.setAttribute("aria-busy", "true");
  content.innerHTML = `<div class="detail-loading-state"><i data-lucide="loader-circle"></i><strong>${uiText("world.reading")}</strong></div>`;
  if (!dialog.open) dialog.showModal();
  renderIcons(dialog);
  try {
    const response = await request(`/api/world-players/detail?player_id=${Number(playerId)}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (
      app.worldPlayerDetailRequestKey !== requestKey || !dialog.open
      || !response?.player || scope !== currentScope
      || String(response.data_scope_id || "") !== scope
    ) return;
    rememberWorldPlayerSummary(response.player);
    content.removeAttribute("aria-busy");
    openClubDetail("player", Number(playerId), {players:[response.player]}, {
      worldPlayer:true,
      onPlayerRename:(player) => {
        const cached = worldPlayerDataIndex().playersById.get(Number(player.id));
        if (cached) cached.name = player.name;
        rememberWorldPlayerSummary(cached || player);
        invalidateWorldPlayerDataIndex();
        renderWorldPlayers();
      },
    });
  } catch (error) {
    if (app.worldPlayerDetailRequestKey !== requestKey || !dialog.open) return;
    content.removeAttribute("aria-busy");
    content.innerHTML = `<div class="detail-error-state"><i data-lucide="circle-alert"></i><strong>${uiText("world.player_detail.read_failed")}</strong><span>${escapeHtml(error.message || uiText("world.ranking.read_failed"))}</span><button type="button" data-world-player-detail-retry>${uiText("world.retry")}</button></div>`;
    content.querySelector("[data-world-player-detail-retry]")?.addEventListener("click", () => openWorldPlayerDetail(playerId));
    renderIcons(dialog);
  }
}

function invalidateWorldPlayerDataIndex() {
  app.worldPlayerIndexSource = null;
  app.worldPlayerIndex = null;
  app.worldPlayerRenderSignature = null;
}

function worldPlayerDataIndex() {
  const data = app.worldPlayers;
  if (app.worldPlayerIndexSource === data && app.worldPlayerIndex) {
    return app.worldPlayerIndex;
  }
  const players = data?.players || [];
  const pagination = data?.pagination || {
    page:1, page_size:30, page_count:1, total:0, from:0, to:0,
  };
  const filters = data?.filters || {};
  app.worldPlayerIndexVersion += 1;
  app.worldPlayerIndexSource = data;
  app.worldPlayerIndex = {
    data, players, pagination, filters, version:app.worldPlayerIndexVersion,
    playersById:new Map(players.map((player) => [Number(player.id), player])),
    dataSignature:JSON.stringify([
      Boolean(data?.ready), data?.data_scope_id || "", filters,
      data?.gender_supported ?? null, pagination, players,
    ]),
  };
  return app.worldPlayerIndex;
}

function worldPlayerRenderStateSignature(index) {
  return JSON.stringify([
    index.version, moneyRenderSignature(),
    index.data ? "" : String(app.worldPlayersError || ""),
    index.data ? false : Boolean(app.worldPlayersLoading),
  ]);
}

// Large world/portfolio templates are composed from game facts and fixed copy.
// Translate only an exact catalog value: arbitrary names, IDs, paths, and server
// diagnostics pass through unchanged.
function localizeWorldPortfolioNode(root) {
  if (!root || !window.FMODDI18n) return;
  const localize = (value) => {
    const source = String(value ?? "");
    const match = source.match(/^(\s*)([\s\S]*?)(\s*)$/);
    const translated = uiLegacy(match?.[2] || source);
    return translated === (match?.[2] || source) ? source : `${match?.[1] || ""}${translated}${match?.[3] || ""}`;
  };
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => { node.nodeValue = localize(node.nodeValue); });
  root.querySelectorAll("[aria-label],[title],[placeholder]").forEach((element) => {
    ["aria-label", "title", "placeholder"].forEach((attribute) => {
      if (element.hasAttribute(attribute)) element.setAttribute(attribute, localize(element.getAttribute(attribute)));
    });
  });
}

function installWorldPortfolioLocalizer() {
  const roots = ["world-player-content", "world-club-content", "world-nation-content", "world-nation-detail-content", "world-club-detail-content", "my-club-content", "portfolio-tool-content"]
    .map((id) => document.getElementById(id)).filter(Boolean);
  if (!roots.length) return;
  const observer = new MutationObserver((records) => {
    records.forEach((record) => record.addedNodes.forEach((node) => {
      if (node.nodeType === Node.ELEMENT_NODE) localizeWorldPortfolioNode(node);
      else if (node.nodeType === Node.TEXT_NODE) node.nodeValue = uiLegacy(node.nodeValue);
    }));
  });
  roots.forEach((root) => { localizeWorldPortfolioNode(root); observer.observe(root, {childList:true, subtree:true}); });
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", installWorldPortfolioLocalizer, {once:true});
else installWorldPortfolioLocalizer();

function syncWorldPlayerPageStatus() {
  const page = $("#page-world-players");
  const root = $("#world-player-content");
  const status = $("#world-player-sync-status");
  const refreshButton = $("#world-player-index-refresh");
  const busy = Boolean(app.worldPlayersLoading);
  const hydrating = Boolean(app.worldPlayersHydrating);
  page?.setAttribute("aria-busy", String(busy));
  root?.setAttribute("aria-busy", String(busy));
  if (refreshButton) {
    refreshButton.disabled = busy;
    refreshButton.classList.toggle("is-refreshing", busy);
    const label = refreshButton.querySelector("span");
    if (label) label.textContent = busy
      ? (app.worldPlayersRebuilding ? uiText("world.rebuilding") : uiText("world.reading")) : uiText("world.refresh");
  }
  root?.querySelectorAll(
    "[data-world-player-sort],[data-world-player-page],[data-world-player-page-input]",
  ).forEach((control) => {
    if (busy) {
      if (control.dataset.worldPlayerBusyDisabled == null) {
        control.dataset.worldPlayerBusyDisabled = String(control.disabled);
      }
      control.disabled = true;
    } else if (control.dataset.worldPlayerBusyDisabled != null) {
      control.disabled = control.dataset.worldPlayerBusyDisabled === "true";
      delete control.dataset.worldPlayerBusyDisabled;
    }
  });
  document.querySelectorAll("#world-player-filters select,#world-player-filters input,#world-player-filters button").forEach((control) => {
    control.disabled = busy;
  });
  if (!status) return;
  status.hidden = !busy && !hydrating;
  const label = status.querySelector("span");
  if (label) label.textContent = app.worldPlayersRebuilding
    ? uiText("world.players.rebuilding")
    : busy ? uiText("world.players.loading") : uiText("world.players.updating");
}

function syncWorldPlayerGenderControl(data = app.worldPlayers) {
  const control = $(".world-player-gender-setting");
  const select = $("#world-player-gender");
  if (!control || !select) return;
  control.hidden = !(data?.ready && data.gender_supported === true);
  select.value = app.worldPlayerGender || "men";
}

function syncWorldPlayerFilterControls(data = app.worldPlayers) {
  const nationality = $("#world-player-nationality");
  const nations = data?.filter_options?.nationalities || [];
  if (nationality) {
    const signature = JSON.stringify(nations);
    if (nationality.dataset.optionsSignature !== signature) {
      nationality.dataset.optionsSignature = signature;
      nationality.innerHTML = `<option value="">${uiText("world.players.nationality_all")}</option>${nations.map((nation) => `<option value="${Number(nation.id)}">${escapeHtml(localizedNationName(nation))}</option>`).join("")}`;
    }
    nationality.value = app.worldPlayerNationalityId ? String(app.worldPlayerNationalityId) : "";
  }
  [
    ["#world-player-min-age", app.worldPlayerMinAge],
    ["#world-player-max-age", app.worldPlayerMaxAge],
    ["#world-player-min-ca", app.worldPlayerMinCa],
    ["#world-player-max-ca", app.worldPlayerMaxCa],
    ["#world-player-min-pa", app.worldPlayerMinPa],
    ["#world-player-max-pa", app.worldPlayerMaxPa],
  ].forEach(([selector, value]) => {
    const input = $(selector);
    if (input && document.activeElement !== input) input.value = value == null ? "" : String(value);
  });
}

function worldPlayerRangeValues(minSelector, maxSelector, label) {
  const read = (selector) => {
    const value = String($(selector)?.value || "").trim();
    return value ? Number(value) : null;
  };
  const minimum = read(minSelector);
  const maximum = read(maxSelector);
  if (minimum != null && maximum != null && minimum > maximum) {
    throw new Error(uiText("world.players.range_invalid", {label}));
  }
  return [minimum, maximum];
}

function renderWorldPlayers() {
  const root = $("#world-player-content");
  if (!root) return;
  const index = worldPlayerDataIndex();
  const data = index.data;
  syncWorldPlayerPageStatus();
  syncWorldPlayerGenderControl(data);
  syncWorldPlayerFilterControls(data);
  const signature = worldPlayerRenderStateSignature(index);
  if (app.worldPlayerRenderSignature === signature) return;
  app.worldPlayerRenderSignature = signature;
  if (!data && app.worldPlayersLoading) {
    root.innerHTML = `<div class="world-club-empty world-player-loading"><i data-lucide="loader-circle"></i><strong>${uiText("world.reading")}</strong></div>`;
    renderIcons(); return;
  }
  if (!data) {
    root.innerHTML = `<div class="world-club-empty"><i data-lucide="circle-alert"></i><strong>${uiText("world.players.read_failed")}</strong><span>${escapeHtml(app.worldPlayersError || uiText("world.players.no_data"))}</span><button type="button" class="refresh-button" data-world-players-retry><i data-lucide="refresh-cw"></i><span>${uiText("world.retry")}</span></button></div>`;
    root.querySelector("[data-world-players-retry]")?.addEventListener("click", () => loadWorldPlayers({page:1, force:true}));
    renderIcons(); return;
  }
  if (!data.ready) {
    root.innerHTML = `<div class="world-club-empty"><i data-lucide="plug-zap"></i><strong>${uiText("world.players.connect")}</strong><span>${uiText("world.players.connect_note")}</span></div>`;
    renderIcons(); return;
  }
  const players = index.players;
  const pagination = index.pagination;
  const filters = index.filters;
  const shownSearch = String(filters.search || "");
  const table = players.length ? `<div class="world-result-heading"><strong>${shownSearch ? uiText("world.search_results", {query:escapeHtml(shownSearch)}) : uiText("world.players.all")}</strong><span>${pagination.from}-${pagination.to} / ${pagination.total}</span></div><section class="world-player-table" role="table" aria-label="${uiText("world.players.list_aria")}"><div class="world-player-table-head" role="row"><span role="columnheader">${uiText("world.column.name")}</span><span role="columnheader">${uiText("world.column.age")}</span>${worldPlayerSortHeader("ca", "CA", filters)}${worldPlayerSortHeader("pa", "PA", filters)}<span role="columnheader">${uiText("world.column.nationality")}</span><span role="columnheader">${uiText("world.column.club")}</span>${worldPlayerSortHeader("asking_price", uiText("world.column.asking_price"), filters)}<span role="columnheader">${uiText("world.column.position")}</span></div><div class="world-player-list" role="rowgroup">${players.map(worldPlayerRow).join("")}</div></section>` : `<div class="world-club-empty compact"><i data-lucide="search-x"></i><strong>${uiText("world.players.no_match")}</strong><span>${uiText("world.players.no_match_note")}</span></div>`;
  root.innerHTML = `${table}<nav class="world-pagination" aria-label="${uiText("world.page_aria")}"><button type="button" data-world-player-page="${pagination.page - 1}" aria-label="${uiText("world.previous_page")}" ${pagination.page <= 1 ? "disabled" : ""}><i data-lucide="chevron-left"></i></button><label>${uiText("world.page", {page:`<input type="number" min="1" max="${pagination.page_count}" value="${pagination.page}" data-world-player-page-input aria-label="${uiText("world.page")}">`, total:pagination.page_count})}</label><button type="button" data-world-player-page="${pagination.page + 1}" aria-label="${uiText("world.next_page")}" ${pagination.page >= pagination.page_count ? "disabled" : ""}><i data-lucide="chevron-right"></i></button></nav>`;
  root.querySelectorAll("[data-world-player-page]").forEach((button) => button.addEventListener("click", () => { if (!button.disabled) loadWorldPlayers({page:Number(button.dataset.worldPlayerPage)}); }));
  root.querySelectorAll("[data-world-player-sort]").forEach((button) => button.addEventListener("click", () => {
    const field = String(button.dataset.worldPlayerSort || "");
    if (!field || app.worldPlayersLoading) return;
    if (app.worldPlayerSort === field) app.worldPlayerSortOrder = app.worldPlayerSortOrder === "desc" ? "asc" : "desc";
    else { app.worldPlayerSort = field; app.worldPlayerSortOrder = "desc"; }
    app.worldPlayerPage = 1;
    loadWorldPlayers({page:1});
  }));
  root.querySelectorAll("[data-world-player-page-input]").forEach((input) => {
    const jump = () => {
      const page = Math.max(1, Math.min(Number(input.max || 1), Number(input.value || 1)));
      input.value = String(page);
      if (page !== app.worldPlayerPage) loadWorldPlayers({page});
    };
    input.addEventListener("change", jump);
    input.addEventListener("keydown", (event) => { if (event.key === "Enter") { event.preventDefault(); jump(); } });
  });
  root.querySelectorAll("[data-world-player-detail]").forEach((row) => {
    const open = () => openWorldPlayerDetail(Number(row.dataset.worldPlayerDetail));
    row.addEventListener("click", open);
    row.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        open();
      }
    });
  });
  syncWorldPlayerPageStatus();
  renderIcons();
}

function clubReputationTier(reputation) {
  const value = Number(reputation);
  if (!Number.isFinite(value) || value <= 0) return uiText("world.pending");
  if (value >= 8500) return uiText("world.reputation.elite");
  if (value >= 7000) return uiText("world.reputation.high");
  if (value >= 5500) return uiText("world.reputation.upper_medium");
  if (value >= 4000) return uiText("world.reputation.medium");
  if (value >= 2500) return uiText("world.reputation.lower_medium");
  if (value >= 1000) return uiText("world.reputation.standard");
  return uiText("world.reputation.obscure");
}

function worldClubAssignment(value) {
  const label = String(value || "").trim();
  return !label || ["未分类", "未知", "世界"].includes(label) ? uiText("world.not_read") : label;
}

function ownedClubLeagueLabel(nation, competition) {
  const country = worldClubAssignment(nation);
  const league = worldClubAssignment(competition);
  if ([uiText("world.not_read"), uiText("world.pending"), "待读取"].includes(country)
      || [uiText("world.not_read"), uiText("world.pending"), "待读取"].includes(league)) return league;
  const escapedCountry = country.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return league.replace(new RegExp(`^${escapedCountry}\\s*[·•|/／-]\\s*`), "").trim() || league;
}

function ownedClubReputationRanks(club) {
  const parts = [];
  const leagueRank = Number(club.competition_reputation_rank);
  const leagueTotal = Number(club.competition_reputation_total);
  const nationRank = Number(club.nation_reputation_rank);
  const nationTotal = Number(club.nation_reputation_total);
  if (Number.isInteger(leagueRank) && leagueRank > 0 && Number.isInteger(leagueTotal) && leagueTotal > 0) {
    parts.push({label:uiText("portfolio.rank.league"), rank:leagueRank, total:leagueTotal});
  }
  if (Number.isInteger(nationRank) && nationRank > 0 && Number.isInteger(nationTotal) && nationTotal > 0) {
    parts.push({label:uiText("portfolio.rank.nation"), rank:nationRank, total:nationTotal});
  }
  return parts;
}

function ownedClubReputationMetric(club) {
  const ranks = ownedClubReputationRanks(club);
  const value = ranks.length
    ? ranks.map((row) => `${row.label} ${row.rank}/${row.total}`).join("\n")
    : uiText("world.not_read");
  return `<div class="owned-reputation-rank-metric"><dt>${uiText("portfolio.rank.reputation")}</dt><dd>${escapeHtml(value)}</dd></div>`;
}

function ownedClubSalePrice(metrics, ownership = {}) {
  const serverPrice = Number(metrics?.sale_price || 0);
  if (Number.isFinite(serverPrice) && serverPrice > 0) return serverPrice;
  const storedValuation = ownership?.acquisition_valuation || {};
  const valuation = Number(
    metrics?.current_valuation
    || ownership?.current_valuation
    || storedValuation.price
    || ownership?.acquisition_price
    || 0
  );
  if (!(valuation > 0)) return 0;
  const competitionPremium = Math.max(
    0,
    Math.min(
      valuation,
      Number(
        metrics?.competition_premium
        || ownership?.competition_premium
        || storedValuation.competition_premium
        || 0
      ),
    ),
  );
  return Math.floor((valuation - competitionPremium) * 0.98) + competitionPremium;
}

function ownedClubOrderStorageKey() {
  return `fmodd-owned-club-order:${String(app.state?.data_scope_id || "default")}`;
}

function storedOwnedClubOrder() {
  try {
    const values = JSON.parse(localStorage.getItem(ownedClubOrderStorageKey()) || "[]");
    if (!Array.isArray(values)) return [];
    return [...new Set(values.map(Number).filter((value) => Number.isInteger(value) && value > 0))];
  } catch (_error) {
    return [];
  }
}

function orderedOwnedClubs(clubs) {
  const positions = new Map(storedOwnedClubOrder().map((teamId, index) => [teamId, index]));
  return clubs.map((club, index) => ({club, index})).sort((left, right) => {
    const leftPosition = positions.get(Number(left.club.id));
    const rightPosition = positions.get(Number(right.club.id));
    if (leftPosition != null || rightPosition != null) {
      if (leftPosition == null) return 1;
      if (rightPosition == null) return -1;
      if (leftPosition !== rightPosition) return leftPosition - rightPosition;
    }
    return left.index - right.index;
  }).map((entry) => entry.club);
}

function ownedClubDataIndex() {
  const data = app.worldClubs;
  const acquired = data?.acquired || [];
  const scope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const orderRaw = localStorage.getItem(ownedClubOrderStorageKey()) || "[]";
  const sources = app.ownedClubIndexSources;
  if (
    sources?.data === data && sources.acquired === acquired
    && sources.scope === scope && sources.orderRaw === orderRaw
    && app.ownedClubIndex
  ) return app.ownedClubIndex;
  let storedOrder = [];
  try {
    const parsed = JSON.parse(orderRaw);
    if (Array.isArray(parsed)) {
      storedOrder = [...new Set(parsed.map(Number).filter((value) => Number.isInteger(value) && value > 0))];
    }
  } catch (_error) {
    storedOrder = [];
  }
  const positions = new Map(storedOrder.map((teamId, index) => [teamId, index]));
  const ordered = acquired.map((club, index) => ({club, index})).sort((left, right) => {
    const leftPosition = positions.get(Number(left.club.id));
    const rightPosition = positions.get(Number(right.club.id));
    if (leftPosition != null || rightPosition != null) {
      if (leftPosition == null) return 1;
      if (rightPosition == null) return -1;
      if (leftPosition !== rightPosition) return leftPosition - rightPosition;
    }
    return left.index - right.index;
  }).map((entry) => entry.club);
  const byId = new Map(acquired.map((club) => [Number(club.id), club]));
  app.ownedClubIndexVersion += 1;
  app.ownedClubIndexSources = {data, acquired, scope, orderRaw};
  app.ownedClubIndex = {
    data, acquired, ordered, byId, orderRaw, version:app.ownedClubIndexVersion,
    active:acquired.filter((club) => club.ownership_active !== false),
    dataSignature:JSON.stringify(acquired),
  };
  return app.ownedClubIndex;
}

function saveOwnedClubOrder(grid) {
  const teamIds = [...grid.querySelectorAll("[data-owned-club-card]")]
    .map((card) => Number(card.dataset.ownedClubCard))
    .filter((teamId) => Number.isInteger(teamId) && teamId > 0);
  localStorage.setItem(ownedClubOrderStorageKey(), JSON.stringify(teamIds));
}

function worldClubCard(club, {
  portfolio = false,
  orderIndex = null,
  orderTotal = 0,
  reordering = false,
} = {}) {
  const displayName = club.display_name
    || (portfolio ? (club.renamed_short_name || club.short_name) : "")
    || club.name || club.short_name || uiText("world.unnamed_club");
  const ranking = club.league_position != null && club.league_team_count != null
    ? uiText("portfolio.league_position", {position:Number(club.league_position), total:Number(club.league_team_count)})
    : uiText("world.pending");
  const reputation = portfolio
    ? (club.reputation == null ? uiText("world.pending") : Number(club.reputation).toLocaleString(activeUiLocale()))
    : clubReputationTier(club.reputation);
  if (portfolio) {
    const teamId = Number(club.id);
    const expanded = app.ownedClubExpandedIds.has(teamId);
    const orderControls = reordering && orderTotal > 1 ? `<div class="owned-club-order-controls" aria-label="${uiText("portfolio.order.aria", {club:escapeHtml(displayName)})}"><span><i data-lucide="grip-vertical"></i><b data-owned-club-order-position>${uiText("portfolio.order.position", {position:Number(orderIndex) + 1})}</b></span><div><button type="button" data-owned-club-order="up" aria-label="${uiText("portfolio.order.up")} ${escapeHtml(displayName)}" title="${uiText("portfolio.order.up")}"><i data-lucide="arrow-up"></i></button><button type="button" data-owned-club-order="down" aria-label="${uiText("portfolio.order.down")} ${escapeHtml(displayName)}" title="${uiText("portfolio.order.down")}"><i data-lucide="arrow-down"></i></button></div></div>` : "";
    if (club.ownership_active === false) {
      const restoreDate = club.ownership_suspended_until || club.acquired_game_date || uiText("world.pending");
      return `<article class="owned-club-row-card owned-club-row-suspended" data-owned-club-card="${teamId}">
        <div class="owned-club-row-identity">${orderControls}<div class="owned-club-row-kicker"><i data-lucide="history"></i><span>${uiText("portfolio.suspended.kicker")}</span></div><h2>${escapeHtml(displayName)}</h2><span>${uiText("portfolio.suspended.record_safe")}</span><small>${uiText("portfolio.suspended.restore_date", {date:escapeHtml(restoreDate)})}</small></div>
        <dl class="owned-club-row-metrics">${ownedClubMetric(uiText("portfolio.suspended.current_status"), uiText("portfolio.suspended.not_effective"))}${ownedClubMetric(uiText("portfolio.suspended.resume_date"), restoreDate)}</dl>
        <div class="owned-club-row-form"><small>${uiText("portfolio.suspended.restrictions")}</small><div><span class="owned-form-none">${uiText("portfolio.suspended.cannot_manage")}</span></div></div>
        <div class="owned-club-row-actions"><button type="button" class="primary-action owned-club-row-view" data-world-view="${teamId}"><span>${uiText("portfolio.suspended.view_status")}</span></button><button type="button" class="owned-club-row-sell" disabled title="${uiText("portfolio.suspended.sell_title")}"><span>${uiText("portfolio.suspended.badge")}</span></button></div>
      </article>`;
    }
    const metrics = app.ownedClubMetrics.get(Number(club.id)) || club.portfolio_metrics || {};
    const fanCountLabel = metrics.fan_count_source === "social_media_followers"
      ? uiText("portfolio.metric.social_following") : uiText("portfolio.metric.season_tickets");
    const liveReputation = metrics.reputation ?? club.reputation;
    const reputationMetric = ownedClubHistoricalMetric(
      uiText("portfolio.metric.reputation"), ownedClubCount(liveReputation), uiText("portfolio.metric.vs_last_month"),
      metrics.reputation_comparison,
    );
    const fanCountMetric = metrics.fan_count_source === "social_media_followers"
      ? ownedClubHistoricalMetric(
        fanCountLabel, ownedClubCount(metrics.fan_count), uiText("portfolio.metric.vs_last_season"),
        metrics.social_media_followers_comparison,
      )
      : ownedClubMetric(fanCountLabel, ownedClubCount(metrics.fan_count));
    const salePrice = ownedClubSalePrice(metrics, club);
    const form = (club.recent_results || []).slice(0, 5);
    const formHtml = form.length ? form.map((row) => {
      const tone = row.result === "胜" ? "win" : row.result === "平" ? "draw" : "loss";
      return `<span class="world-form-${tone}" title="${escapeHtml(`${row.opponent || uiText("portfolio.form.opponent")} ${row.score || ""}`)}">${escapeHtml(row.result || "-")}</span>`;
    }).join("") : `<span class="owned-form-none">${uiText("portfolio.form.none")}</span>`;
    return `<article class="owned-club-row-card${expanded ? " is-expanded" : ""}" data-owned-club-card="${teamId}">
      <div class="owned-club-row-identity" data-owned-club-disclosure role="button" tabindex="0" aria-expanded="${expanded}" aria-controls="owned-club-metrics-${teamId}">${orderControls}<h2>${escapeHtml(displayName)}</h2><span>${uiText("portfolio.metric.country")}: ${escapeHtml(localizedClubNation(club, metrics.nation))}</span><small>${uiText("portfolio.metric.competition")}: ${escapeHtml(ownedClubLeagueLabel(club.nation, club.competition))}</small></div>
      <dl class="owned-club-row-metrics" id="owned-club-metrics-${teamId}" data-owned-club-disclosure>${ownedClubMetric(uiText("portfolio.metric.league_rank"), ranking)}${ownedClubMetric(uiText("portfolio.metric.transfer_budget"), ownedClubMoney(metrics.transfer_budget, metrics.unavailable))}${ownedClubMetric(uiText("portfolio.metric.balance"), ownedClubMoney(metrics.balance, metrics.unavailable))}${ownedClubMetric(uiText("portfolio.metric.dividend"), ownedClubDividendEstimate(metrics))}${ownedClubMetric(uiText("portfolio.metric.valuation"), ownedClubMoney(metrics.current_valuation, metrics.unavailable))}${ownedClubAcquisitionMetric(metrics)}${ownedClubMetric(uiText("portfolio.metric.holding_days"), metrics.holding_days == null ? uiText("world.not_read") : uiText("portfolio.metric.days", {count:ownedClubCount(metrics.holding_days)}))}${ownedClubDebtMetric(metrics, club.id)}${ownedClubReputationMetric(club)}${reputationMetric}${fanCountMetric}${ownedClubMetric(uiText("portfolio.metric.season_revenue"), ownedClubMoney(metrics.season_revenue, metrics.unavailable))}</dl>
      <div class="owned-club-row-form"><small>${uiText("portfolio.form.recent")}</small><div>${formHtml}</div></div>
      <div class="owned-club-row-actions"><button type="button" class="primary-action owned-club-row-view" data-world-view="${Number(club.id)}"><span>${uiText("portfolio.view")}</span></button><button type="button" class="owned-club-row-sell" data-world-sell="${Number(club.id)}"><span>${uiText("portfolio.sell")}</span></button><button type="button" class="owned-club-row-toggle" data-owned-club-toggle="${teamId}" aria-expanded="${expanded}" aria-controls="owned-club-metrics-${teamId}" aria-label="${expanded ? uiText("portfolio.collapse") : uiText("portfolio.expand")} ${escapeHtml(displayName)}"><span>${expanded ? uiText("portfolio.collapse_data") : uiText("portfolio.more_data")}</span><i data-lucide="chevron-${expanded ? "up" : "down"}"></i></button></div>
    </article>`;
  }
  return `<article class="world-club-card">
    <div class="world-club-card-head"><h2>${escapeHtml(displayName)}</h2></div>
    <dl class="world-club-facts">
      <div><dt>${uiText("portfolio.metric.country")}</dt><dd>${escapeHtml(localizedClubNation(club))}</dd></div>
      <div><dt>${uiText("portfolio.metric.competition")}</dt><dd>${escapeHtml(worldClubAssignment(club.competition))}</dd></div>
      <div><dt>${uiText("portfolio.metric.reputation")}</dt><dd>${reputation}</dd></div>
      <div><dt>${uiText("portfolio.metric.league_rank")}</dt><dd>${ranking}</dd></div>
    </dl>
    <button type="button" class="primary-action world-club-view" data-world-view="${Number(club.id)}"><span>${uiText("portfolio.view")}</span></button>
  </article>`;
}

function activeOwnedClubs() {
  return ownedClubDataIndex().active;
}

function initializeOwnedClubCardInteractions(root) {
  const setExpanded = (card, button, expanded) => {
    const teamId = Number(card?.dataset.ownedClubCard);
    if (!card || !button || !Number.isInteger(teamId)) return;
    card.classList.toggle("is-expanded", expanded);
    if (expanded) app.ownedClubExpandedIds.add(teamId);
    else app.ownedClubExpandedIds.delete(teamId);
    button.setAttribute("aria-expanded", String(expanded));
    card.querySelectorAll('[data-owned-club-disclosure][role="button"]').forEach((node) => node.setAttribute("aria-expanded", String(expanded)));
    button.setAttribute("aria-label", `${expanded ? uiText("portfolio.collapse") : uiText("portfolio.expand")} ${card.querySelector("h2")?.textContent || uiText("portfolio.club_fallback")}`);
    button.innerHTML = `<span>${expanded ? uiText("portfolio.collapse_data") : uiText("portfolio.more_data")}</span><i data-lucide="chevron-${expanded ? "up" : "down"}"></i>`;
    renderIcons();
  };
  root.querySelectorAll("[data-owned-club-toggle]").forEach((button) => button.addEventListener("click", () => {
    const teamId = Number(button.dataset.ownedClubToggle);
    const card = button.closest("[data-owned-club-card]");
    if (!card || !Number.isInteger(teamId)) return;
    setExpanded(card, button, !card.classList.contains("is-expanded"));
  }));

  root.querySelectorAll("[data-owned-club-card]").forEach((card) => card.addEventListener("click", (event) => {
    if (app.ownedClubReorderMode || !event.target.closest("[data-owned-club-disclosure]")) return;
    if (event.target.closest("button, a, input, select, textarea, label")) return;
    const selection = window.getSelection?.();
    if (selection && !selection.isCollapsed) return;
    const button = card.querySelector("[data-owned-club-toggle]");
    setExpanded(card, button, !card.classList.contains("is-expanded"));
  }));
  root.querySelectorAll('[data-owned-club-disclosure][role="button"]').forEach((disclosure) => disclosure.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    const card = disclosure.closest("[data-owned-club-card]");
    const button = card?.querySelector("[data-owned-club-toggle]");
    if (!card || !button || app.ownedClubReorderMode) return;
    setExpanded(card, button, !card.classList.contains("is-expanded"));
  }));

  const grid = root.querySelector(".my-club-grid");
  if (!grid) return;
  const syncOrderButtons = () => {
    const cards = [...grid.querySelectorAll("[data-owned-club-card]")];
    cards.forEach((card, index) => {
      const up = card.querySelector('[data-owned-club-order="up"]');
      const down = card.querySelector('[data-owned-club-order="down"]');
      const position = card.querySelector("[data-owned-club-order-position]");
      if (up) up.disabled = index === 0;
      if (down) down.disabled = index === cards.length - 1;
      if (position) position.textContent = uiText("portfolio.order.position", {position:index + 1});
    });
  };
  grid.querySelectorAll("[data-owned-club-order]").forEach((button) => button.addEventListener("click", () => {
    const card = button.closest("[data-owned-club-card]");
    if (!card || button.disabled) return;
    if (button.dataset.ownedClubOrder === "up") {
      const previous = card.previousElementSibling;
      if (previous) grid.insertBefore(card, previous);
    } else {
      const next = card.nextElementSibling;
      if (next) grid.insertBefore(next, card);
    }
    saveOwnedClubOrder(grid);
    syncOrderButtons();
    const position = [...grid.querySelectorAll("[data-owned-club-card]")].indexOf(card) + 1;
    const status = root.querySelector("[data-owned-club-order-status]");
    if (status) status.textContent = uiText("portfolio.order.saved", {club:card.querySelector("h2")?.textContent || uiText("portfolio.club_fallback"), position});
  }));
  syncOrderButtons();
}

async function performOwnedClubMetricsLoad({force = false, snapshot = null} = {}) {
  const clubs = activeOwnedClubs();
  if (!clubs.length) return true;
  const scope = String(app.state?.data_scope_id || "");
  if (app.ownedClubMetricsScope !== scope) {
    app.ownedClubMetrics.clear();
    app.ownedClubMetricsVersion += 1;
    app.ownedClubPortfolioSummary = null;
    app.ownedClubMetricsScope = scope;
  }
  const targets = force ? clubs : clubs.filter((club) => !app.ownedClubMetrics.has(Number(club.id)));
  if (!targets.length) return true;
  const requestKey = ++app.ownedClubMetricsRequestKey;
  app.ownedClubMetricsLoading = true;
  renderMyClubs();
  try {
    const metricsUrl = force ? "/api/world-clubs/metrics"
      : `/api/world-clubs/metrics?team_ids=${targets.map((club) => Number(club.id)).join(",")}`;
    const response = snapshot || await request(metricsUrl, {
      timeoutMs:180000,
      timeoutMessage:uiText("portfolio.refresh.timeout"),
    });
    if (
      requestKey !== app.ownedClubMetricsRequestKey
      || scope !== String(app.state?.data_scope_id || "")
      || String(response.data_scope_id || "") !== scope
    ) return;
    const metrics = response.metrics || {};
    if (response.economy && app.state) {
      applyEconomySnapshot(response.economy);
      renderBank();
    }
    app.ownedClubPortfolioSummary = response.summary || null;
    for (const club of clubs.filter((club) => Object.hasOwn(metrics, String(Number(club.id))))) {
      app.ownedClubMetrics.set(
        Number(club.id), metrics[String(Number(club.id))] || {unavailable:true},
      );
    }
    app.ownedClubMetricsVersion += 1;
    if (response.metrics_complete === false) rebuildOwnedClubPortfolioSummaryFromCache();
    if (Number(response.dividends?.paid_count || 0) > 0) {
      toast(uiText("portfolio.dividend_received", {amount:formatFullMoney(response.dividends.paid_amount)}));
    }
    renderMyClubs();
    return true;
  } catch (_error) {
    if (requestKey !== app.ownedClubMetricsRequestKey || scope !== String(app.state?.data_scope_id || "")) return false;
    renderMyClubs();
    return false;
  } finally {
    if (requestKey === app.ownedClubMetricsRequestKey) {
      app.ownedClubMetricsLoading = false;
      renderMyClubs();
    }
  }
}

async function loadOwnedClubMetrics({force = false} = {}) {
  if (app.ownedClubMetricsPromise) {
    if (force) app.ownedClubMetricsForceQueued = true;
    return app.ownedClubMetricsPromise;
  }
  const task = (async () => {
    let nextForce = force;
    let succeeded = true;
    do {
      app.ownedClubMetricsForceQueued = false;
      succeeded = await performOwnedClubMetricsLoad({force:nextForce});
      nextForce = app.ownedClubMetricsForceQueued;
    } while (nextForce);
    return succeeded;
  })();
  app.ownedClubMetricsPromise = task;
  try {
    return await task;
  } finally {
    if (app.ownedClubMetricsPromise === task) {
      app.ownedClubMetricsPromise = null;
      app.ownedClubMetricsForceQueued = false;
    }
  }
}

function rebuildOwnedClubPortfolioSummaryFromCache() {
  const clubs = activeOwnedClubs();
  if (!clubs.length) {
    app.ownedClubPortfolioSummary = {
      club_count:0, valued_club_count:0, comparable_club_count:0,
      partial:false, acquisition_cost:null, gross_acquisition_cost:null,
      acquisition_refunds:null, current_valuation:null, valuation_change:null,
      balance:null, season_revenue:null, estimated_dividend:null, debt:null,
    };
    return true;
  }
  if (clubs.some((club) => !app.ownedClubMetrics.has(Number(club.id)))) {
    app.ownedClubPortfolioSummary = null;
    void loadOwnedClubMetrics();
    return false;
  }
  const rows = clubs.map((club) => app.ownedClubMetrics.get(Number(club.id)) || {});
  const readable = (row) => !row.unavailable;
  const valued = rows.filter((row) => readable(row) && row.current_valuation != null);
  const comparable = valued.filter((row) => row.net_acquisition_cost != null);
  const total = (field, source = rows) => {
    const values = source
      .map((row) => row[field])
      .filter((value) => value != null && Number.isFinite(Number(value)))
      .map(Number);
    return values.length ? values.reduce((sum, value) => sum + value, 0) : null;
  };
  app.ownedClubPortfolioSummary = {
    club_count:clubs.length,
    valued_club_count:valued.length,
    comparable_club_count:comparable.length,
    partial:valued.length !== clubs.length,
    acquisition_cost:total("net_acquisition_cost"),
    gross_acquisition_cost:total("gross_acquisition_price"),
    acquisition_refunds:total("acquisition_refund"),
    current_valuation:total("current_valuation", valued),
    valuation_change:total("valuation_change", comparable),
    balance:total("balance"),
    season_revenue:total("season_revenue"),
    estimated_dividend:total("estimated_dividend"),
    debt:total("debt"),
  };
  return true;
}

function updateOwnedClubCachedMetrics(teamId, metricsPatch, financesPatch = null) {
  const cached = cachedOwnedClubDetail(teamId);
  if (!cached?.detail) return false;
  const detail = cached.detail;
  detail.portfolio_metrics = {
    ...(detail.portfolio_metrics || {}),
    ...(metricsPatch || {}),
  };
  if (financesPatch) {
    const information = detail.club_information ||= {};
    Object.assign(information.finances ||= {}, financesPatch);
  }
  rememberOwnedClubDetailMutation(teamId, detail, ["overview"]);
  return true;
}

function syncOwnedClubDividendForecasts(economy) {
  const forecasts = economy?.dividends?.forecasts;
  if (!Array.isArray(forecasts) || !app.ownedClubMetrics.size) return false;
  let changed = false;
  forecasts.forEach((forecast) => {
    const teamId = Number(forecast?.team_id || 0);
    const previous = app.ownedClubMetrics.get(teamId);
    if (!previous) return;
    const estimatedDividend = Number(forecast.estimated_amount || 0);
    if (
      Number(previous.estimated_dividend || 0) === estimatedDividend
      && JSON.stringify(previous.dividend_forecast || null) === JSON.stringify(forecast)
    ) return;
    const updated = {
      ...previous,
      dividend_forecast:forecast,
      estimated_dividend:estimatedDividend,
    };
    app.ownedClubMetrics.set(teamId, updated);
    updateOwnedClubCachedMetrics(teamId, {
      dividend_forecast:forecast,
      estimated_dividend:estimatedDividend,
    });
    changed = true;
  });
  if (changed) {
    app.ownedClubMetricsVersion += 1;
    rebuildOwnedClubPortfolioSummaryFromCache();
  }
  return changed;
}

async function refreshOwnedClubCards() {
  if (app.ownedClubMetricsPromise) await app.ownedClubMetricsPromise;
  const addressResult = await request("/api/world-clubs/owned-refresh", {
    method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({include_metrics:true}),
    timeoutMs:180000,
    timeoutMessage:uiText("portfolio.refresh.address_timeout"),
  });
  clearOwnedClubDetailCache();
  await loadWorldClubs({page:app.worldClubPage});
  const metricsLoaded = addressResult.metrics_snapshot
    ? await performOwnedClubMetricsLoad({force:true, snapshot:addressResult.metrics_snapshot})
    : await loadOwnedClubMetrics({force:true});
  if (!metricsLoaded) throw new Error(uiText("portfolio.refresh.metrics_failed"));
  return addressResult;
}

function syncWorldClubScanPolling(data = app.worldClubs) {
  const scanning = Boolean(data?.native_scan?.scanning);
  if (!scanning) {
    clearInterval(app.worldClubScanPoll);
    app.worldClubScanPoll = null;
    return;
  }
  if (app.worldClubScanPoll) return;
  app.worldClubScanPoll = setInterval(async () => {
    const latest = await loadWorldClubs({page:app.worldClubPage});
    if (!latest?.native_scan?.scanning) {
      clearInterval(app.worldClubScanPoll);
      app.worldClubScanPoll = null;
    }
  }, 1200);
}

function worldClubDataIndex() {
  const data = app.worldClubs;
  if (app.worldClubIndexSource === data && app.worldClubIndex) return app.worldClubIndex;
  const facets = data?.facets || [];
  const clubs = data?.clubs || [];
  const scan = data?.native_scan || {};
  const pagination = data?.pagination || {page:1,page_count:1,total:0,from:0,to:0};
  const scanContent = scan.ready
    ? [true, Boolean(scan.addresses_current)]
    : [false, Boolean(scan.scanning), Number(scan.progress || 0), scan.progress_text || "", scan.error || ""];
  app.worldClubIndexSource = data;
  app.worldClubIndex = {
    data, facets, clubs, scan, pagination,
    facetsByName:new Map(facets.map((row) => [String(row.name || ""), row])),
    clubsById:new Map(clubs.map((club) => [Number(club.id), club])),
    facetTotal:facets.reduce((sum, row) => sum + Number(row.count || 0), 0),
    dataSignature:JSON.stringify([
      Boolean(data?.ready), data?.data_scope_id || "", data?.filters || {},
      pagination, scanContent, facets, clubs,
    ]),
  };
  return app.worldClubIndex;
}

function worldClubContentSignature(index) {
  return JSON.stringify([
    index.dataSignature,
    app.worldClubSearch, app.worldClubContinent, app.worldClubNation,
    Number(app.worldClubPage || 1),
    index.data ? "" : String(app.worldClubsError || ""),
    index.data ? false : Boolean(app.worldClubsLoading),
  ]);
}

function syncWorldClubPageStatus(refreshing, scan) {
  const page = $("#page-world-clubs");
  const root = $("#world-club-content");
  const status = $("#world-club-sync-status");
  page?.setAttribute("aria-busy", String(refreshing));
  root?.setAttribute("aria-busy", String(refreshing));
  if (!status) return;
  status.hidden = !refreshing;
  const label = status.querySelector("span");
  if (label) label.textContent = scan.scanning
    ? uiText("world.clubs.scan_progress", {progress:Number(scan.progress || 0)}) : uiText("world.clubs.syncing");
}

function renderWorldClubs() {
  const root = $("#world-club-content");
  if (!root) return;
  const index = worldClubDataIndex();
  const data = index.data;
  const scan = index.scan;
  const refreshing = Boolean(app.worldClubsLoading || scan.scanning);
  syncWorldClubPageStatus(refreshing, scan);
  const scanButton = $("#world-club-scan");
  if (scanButton) {
    scanButton.disabled = Boolean(refreshing || !data?.ready);
    scanButton.classList.toggle("is-refreshing", refreshing);
    const label = scanButton.querySelector("span");
    if (label) label.textContent = scan.scanning
      ? uiText("world.clubs.refresh_progress", {progress:scan.progress || 0})
      : app.worldClubsLoading ? uiText("world.refreshing") : scan.ready ? uiText("world.clubs.rescan") : uiText("world.clubs.scan");
  }
  const signature = worldClubContentSignature(index);
  if (app.worldClubRenderSignature === signature) return;
  app.worldClubRenderSignature = signature;
  if (!data && app.worldClubsLoading) {
    root.innerHTML = `<div class="world-club-empty world-club-refreshing"><i data-lucide="loader-circle"></i><strong>${uiText("world.refreshing")}</strong><span>${uiText("world.clubs.loading")}</span></div>`;
    renderIcons(); return;
  }
  if (!data) {
    root.innerHTML = `<div class="world-club-empty"><i data-lucide="circle-alert"></i><strong>${uiText("world.clubs.read_failed")}</strong><span>${escapeHtml(app.worldClubsError || uiText("world.clubs.no_data"))}</span><button type="button" class="refresh-button" data-world-clubs-retry><i data-lucide="refresh-cw"></i><span>${uiText("world.retry")}</span></button></div>`;
    root.querySelector("[data-world-clubs-retry]")?.addEventListener("click", () => loadWorldClubs({page:1}));
    renderIcons(); return;
  }
  if (!data.ready) {
    root.innerHTML = `<div class="world-club-empty"><i data-lucide="plug-zap"></i><strong>${uiText("world.players.connect")}</strong><span>${uiText("world.clubs.connect_note")}</span></div>`;
    renderIcons(); return;
  }
  if (!scan.ready) {
    root.innerHTML = scan.scanning
      ? `<div class="world-scan-state"><div><strong>${uiText("world.clubs.scan_progress", {progress:Number(scan.progress || 0)})}</strong></div><progress max="100" value="${Number(scan.progress || 0)}"></progress></div>`
      : `<div class="world-club-empty"><i data-lucide="scan-search"></i><strong>${scan.error ? uiText("world.clubs.scan_failed") : uiText("world.clubs.not_scanned")}</strong><span>${uiText("world.clubs.scan_note")}</span></div>`;
    renderIcons(); return;
  }
  const facets = index.facets;
  const activeContinent = index.facetsByName.get(app.worldClubContinent);
  const continentButtons = `<button type="button" class="${app.worldClubContinent ? "" : "active"}" data-world-continent="" aria-pressed="${!app.worldClubContinent}">${uiText("world.all")} <span>${index.facetTotal}</span></button>${facets.map((row) => `<button type="button" class="${row.name === app.worldClubContinent ? "active" : ""}" data-world-continent="${escapeHtml(row.name)}" aria-pressed="${row.name === app.worldClubContinent}">${escapeHtml(localizedContinentName(row.name))} <span>${Number(row.count || 0)}</span></button>`).join("")}`;
  const nationButtons = activeContinent ? `<div class="world-filter-row nations" role="group" aria-label="${uiText("world.clubs.filter_nation")}"><button type="button" class="${app.worldClubNation ? "" : "active"}" data-world-nation="" aria-pressed="${!app.worldClubNation}">${uiText("world.clubs.all_nations")}</button>${(activeContinent.nations || []).map((row) => `<button type="button" class="${row.name === app.worldClubNation ? "active" : ""}" data-world-nation="${escapeHtml(row.name)}" aria-pressed="${row.name === app.worldClubNation}">${escapeHtml(localizedNationName(row))} <span>${Number(row.count || 0)}</span></button>`).join("")}</div>` : "";
  const clubs = index.clubs;
  const pagination = index.pagination;
  const addressNotice = !scan.addresses_current ? `<div class="world-address-notice"><i data-lucide="circle-alert"></i><span>${uiText("world.clubs.cache_notice")}</span></div>` : "";
  root.innerHTML = `${addressNotice}<div class="world-directory-tools"><div class="world-filter-row continents" role="group" aria-label="${uiText("world.clubs.filter_continent")}">${continentButtons}</div>${nationButtons}</div>
    ${clubs.length ? `<div class="world-result-heading"><strong>${app.worldClubNation || app.worldClubContinent || uiText("world.clubs.all_clubs")}</strong><span>${pagination.from}-${pagination.to} / ${pagination.total}</span></div><div class="world-club-grid">${clubs.map((club) => worldClubCard(club)).join("")}</div>` : `<div class="world-club-empty compact"><i data-lucide="search-x"></i><strong>${uiText("world.clubs.no_match")}</strong><span>${uiText("world.clubs.no_match_note")}</span></div>`}
    <nav class="world-pagination" aria-label="${uiText("world.page_aria")}"><button type="button" data-world-page="${pagination.page - 1}" aria-label="${uiText("world.previous_page")}" ${pagination.page <= 1 ? "disabled" : ""}><i data-lucide="chevron-left"></i></button><label>${uiText("world.page", {page:`<input type="number" min="1" max="${pagination.page_count}" value="${pagination.page}" data-world-page-input aria-label="${uiText("world.page")}">`, total:pagination.page_count})}</label><button type="button" data-world-page="${pagination.page + 1}" aria-label="${uiText("world.next_page")}" ${pagination.page >= pagination.page_count ? "disabled" : ""}><i data-lucide="chevron-right"></i></button></nav>`;
  root.querySelectorAll("[data-world-continent]").forEach((button) => button.addEventListener("click", () => { app.worldClubContinent = button.dataset.worldContinent || ""; app.worldClubNation = ""; app.worldClubPage = 1; loadWorldClubs({page:1}); }));
  root.querySelectorAll("[data-world-nation]").forEach((button) => button.addEventListener("click", () => { app.worldClubNation = button.dataset.worldNation || ""; app.worldClubPage = 1; loadWorldClubs({page:1}); }));
  root.querySelectorAll("[data-world-page]").forEach((button) => button.addEventListener("click", () => { if (!button.disabled) loadWorldClubs({page:Number(button.dataset.worldPage)}); }));
  root.querySelectorAll("[data-world-page-input]").forEach((input) => {
    const jump = () => {
      const page = Math.max(1, Math.min(Number(input.max || 1), Number(input.value || 1)));
      input.value = String(page);
      if (page !== app.worldClubPage) loadWorldClubs({page});
    };
    input.addEventListener("change", jump);
    input.addEventListener("keydown", (event) => { if (event.key === "Enter") { event.preventDefault(); jump(); } });
  });
  root.querySelectorAll("[data-world-view]").forEach((button) => button.addEventListener("click", () => openWorldClubDetail(Number(button.dataset.worldView))));
  renderIcons();
}

async function sellOwnedClub(teamId, button) {
  const club = (app.worldClubs?.acquired || []).find(
    (row) => Number(row.id) === Number(teamId),
  );
  const metrics = app.ownedClubMetrics.get(Number(teamId)) || club?.portfolio_metrics || {};
  const salePrice = ownedClubSalePrice(metrics, club);
  const confirmed = await fmoddConfirm(
    uiText("portfolio.sell.confirm", {
      club:club?.name || uiText("portfolio.club_fallback"),
      amount:salePrice > 0 ? formatFullMoney(salePrice) : uiText("portfolio.sell.estimate_pending"),
    }),
    uiText("portfolio.sell.title"),
  );
  if (!confirmed) return;
  try {
    const result = await runOwnedClubOperation(button, uiText("portfolio.sell.busy"), () => request(
      "/api/world-clubs/sell",
      {
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({team_id:Number(teamId)}),
      },
    ));
    if (!result) return;
    if (app.worldClubs) app.worldClubs.acquired = result.acquired || [];
    app.ownedClubMetrics.delete(Number(teamId));
    app.ownedClubMetricsVersion += 1;
    clearOwnedClubDetailCache(teamId);
    rebuildOwnedClubPortfolioSummaryFromCache();
    if (result.economy && app.state) {
      applyEconomySnapshot(result.economy);
      renderBank();
    }
    renderMyClubs();
    toast(uiText("portfolio.sell.done", {amount:formatFullMoney(result.sale_price || 0)}));
  } catch (error) {
    toast(error.message || uiText("portfolio.sell.failed"));
  }
}

async function repayOwnedClubDebt(teamId, button) {
  const club = (app.worldClubs?.acquired || []).find(
    (row) => Number(row.id) === Number(teamId),
  );
  const metrics = app.ownedClubMetrics.get(Number(teamId)) || club?.portfolio_metrics || {};
  const debt = Number(metrics.debt || 0);
  if (!(debt > 0)) return toast(uiText("portfolio.debt.none"));
  const confirmed = await fmoddConfirm(
    uiText("portfolio.debt.confirm", {amount:formatFullMoney(debt), club:club?.name || uiText("portfolio.club_fallback")}),
    uiText("portfolio.debt.title"),
  );
  if (!confirmed) return;
  try {
    const result = await runOwnedClubOperation(button, uiText("portfolio.debt.busy"), () => request(
      "/api/world-clubs/debt-repay",
      {
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({team_id:Number(teamId), expected_debt:debt}),
      },
    ));
    if (!result) return;
    const updated = {...metrics, debt:0};
    app.ownedClubMetrics.set(Number(teamId), updated);
    updateOwnedClubCachedMetrics(teamId, {debt:0}, {debts:[]});
    app.ownedClubMetricsVersion += 1;
    rebuildOwnedClubPortfolioSummaryFromCache();
    if (result.economy && app.state) {
      applyEconomySnapshot(result.economy);
      renderBank();
    }
    renderMyClubs();
    toast(uiText("portfolio.debt.done", {amount:formatFullMoney(result.repaid_amount || debt)}));
  } catch (error) {
    toast(error.message || uiText("portfolio.debt.failed"));
  }
}

async function loadWorldNations({page = app.worldNationPage, background = false} = {}) {
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const requestedVersion = Number(app.state?.data_version || 0);
  const requestedResourceVersion = dataResourceVersionKey("world-nations");
  const query = new URLSearchParams({page:String(page), page_size:"15"});
  if (app.worldNationSearch) query.set("search", app.worldNationSearch);
  if (app.worldNationContinent) query.set("continent", app.worldNationContinent);
  const requestSignature = `world-nations:${requestedResourceVersion}:${query}`;
  const task = sharePageDataRequest(requestSignature, async () => {
  const requestKey = Number(app.worldNationRequestKey || 0) + 1;
  app.worldNationRequestKey = requestKey;
  app.worldNationsLoading = true;
  app.worldNationsError = null;
  if (!background || app.page === "world-nations") renderWorldNations();
  try {
    const response = await request(`/api/world-nations?${query}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (requestKey !== app.worldNationRequestKey || requestedScope !== currentScope
        || requestedVersion !== Number(app.state?.data_version || 0)
        || requestedResourceVersion !== dataResourceVersionKey("world-nations")
        || String(response.data_scope_id || "") !== requestedScope
        || !isSaveConnected()) return app.worldNations;
    app.worldNations = response;
    app.worldNationsScope = requestedScope;
    app.worldNationsError = null;
    app.worldNationPage = Number(app.worldNations?.pagination?.page || 1);
    rememberPageDataVersion("world-nations");
    if (!background || app.page === "world-nations") renderWorldNations();
    if (!background || app.page === "world-nations") syncWorldNationScanPolling(app.worldNations);
    return app.worldNations;
  } catch (error) {
    if (requestKey !== app.worldNationRequestKey) return app.worldNations;
    app.worldNationsError = error.message || uiText("world.nations.read_failed");
    if (!background || app.page === "world-nations") renderWorldNations();
    if (!background) toast(app.worldNationsError);
    return null;
  } finally {
    if (requestKey === app.worldNationRequestKey) {
      app.worldNationsLoading = false;
      if (!background || app.page === "world-nations") renderWorldNations();
    }
  }
  });
  app.worldNationsLoadPromise = task;
  try {
    return await task;
  } finally {
    if (app.worldNationsLoadPromise === task) app.worldNationsLoadPromise = null;
  }
}

function syncWorldNationScanPolling(data = app.worldNations) {
  const scanning = Boolean(data?.native_scan?.scanning);
  if (!scanning) {
    clearInterval(app.worldNationScanPoll);
    app.worldNationScanPoll = null;
    return;
  }
  if (app.worldNationScanPoll) return;
  app.worldNationScanPoll = setInterval(async () => {
    const latest = await loadWorldNations({page:app.worldNationPage});
    if (!latest?.native_scan?.scanning) {
      clearInterval(app.worldNationScanPoll);
      app.worldNationScanPoll = null;
      if (latest?.native_scan?.ready && latest.native_scan.addresses_current) {
        // A completed manual scan also satisfies the activity centre's
        // nationality catalogue.  Drop the failed/old result so the next
        // activity render performs a fresh read.
        app.internationalNations = null;
        app.internationalNationError = "";
        if (app.page === "activity" && app.activityFloor === "international") {
          void loadInternationalNations();
        }
      }
    }
  }, 1200);
}

function invalidateWorldNationDataIndex() {
  app.worldNationIndexSource = null;
  app.worldNationIndex = null;
  app.worldNationRenderSignature = null;
}

function worldNationDataIndex() {
  const data = app.worldNations;
  if (app.worldNationIndexSource === data && app.worldNationIndex) return app.worldNationIndex;
  const facets = data?.facets || [];
  const nations = data?.nations || [];
  const scan = data?.native_scan || {};
  const pagination = data?.pagination || {page:1,page_count:1,total:0,from:0,to:0};
  const scanContent = scan.ready
    ? [true, Boolean(scan.addresses_current)]
    : [false, Boolean(scan.scanning), Number(scan.progress || 0), scan.progress_text || "", scan.error || ""];
  const dataSignature = JSON.stringify([
    Boolean(data?.ready), data?.error || "", data?.filters || {}, pagination,
    scanContent, facets, nations,
  ]);
  if (!app.worldNationIndex || app.worldNationIndex.dataSignature !== dataSignature) {
    app.worldNationIndexVersion = Number(app.worldNationIndexVersion || 0) + 1;
  }
  app.worldNationIndexSource = data;
  app.worldNationIndex = {
    data, facets, nations, scan, pagination, dataSignature,
    version:Number(app.worldNationIndexVersion || 0),
    nationsById:new Map(nations.map((nation) => [Number(nation.id), nation])),
    facetTotal:facets.reduce((sum, row) => sum + Number(row.count || 0), 0),
  };
  return app.worldNationIndex;
}

function worldNationContentSignature(index) {
  return JSON.stringify([
    String(app.state?.data_scope_id || output().save_instance_id || ""),
    String(app.worldNationsScope || ""), index.version,
    app.worldNationSearch, app.worldNationContinent, Number(app.worldNationPage || 1),
    index.data ? "" : String(app.worldNationsError || ""),
    index.data ? false : Boolean(app.worldNationsLoading),
  ]);
}

function syncWorldNationPageStatus(index = worldNationDataIndex()) {
  const scan = index.scan;
  const refreshing = Boolean(app.worldNationsLoading || app.worldNationsRebuilding || scan.scanning);
  const page = $("#page-world-nations");
  const root = $("#world-nation-content");
  const status = $("#world-nation-sync-status");
  page?.setAttribute("aria-busy", String(refreshing));
  root?.setAttribute("aria-busy", String(refreshing));
  if (status) {
    status.hidden = !refreshing;
    const label = status.querySelector("span");
    if (label) label.textContent = scan.scanning
      ? uiText("world.clubs.scan_progress", {progress:Number(scan.progress || 0)})
      : app.worldNationsRebuilding ? uiText("world.nations.starting_scan") : uiText("world.nations.syncing");
  }
  const scanButton = $("#world-nation-scan");
  if (scanButton) {
    scanButton.disabled = Boolean(refreshing || !index.data?.ready);
    scanButton.classList.toggle("is-refreshing", refreshing);
    const label = scanButton.querySelector("span");
    if (label) label.textContent = scan.scanning
      ? `${Number(scan.progress || 0)}%`
      : app.worldNationsRebuilding ? uiText("world.reading") : app.worldNationsLoading
        ? uiText("world.refreshing") : scan.ready ? uiText("world.clubs.rescan") : uiText("world.nations.scan");
  }
  root?.querySelectorAll("[data-world-nation-continent], [data-world-nation-page], [data-world-nation-view]").forEach((control) => {
    const saved = Object.prototype.hasOwnProperty.call(control.dataset, "worldNationIdleDisabled");
    if (refreshing && !saved) {
      control.dataset.worldNationIdleDisabled = String(control.disabled);
      control.disabled = true;
    } else if (!refreshing && saved) {
      control.disabled = control.dataset.worldNationIdleDisabled === "true";
      delete control.dataset.worldNationIdleDisabled;
    }
  });
}

function worldNationCard(nation) {
  const youth = nation.youth_rating == null ? uiText("world.pending") : `${Number(nation.youth_rating).toLocaleString(activeUiLocale())} / 200`;
  const reputation = nation.reputation == null ? uiText("world.not_read") : Number(nation.reputation).toLocaleString(activeUiLocale());
  const nationId = Number(nation.id);
  const nationName = localizedNationName(nation) || uiText("world.unnamed_nation");
  return `<article class="world-club-card world-nation-card" aria-labelledby="world-nation-name-${nationId}">
    <div class="world-club-card-head"><h2 id="world-nation-name-${nationId}">${escapeHtml(nationName)}</h2></div>
    <dl class="world-club-facts">
      <div><dt>${uiText("world.nation.continent")}</dt><dd>${escapeHtml(localizedContinentName(nation.continent))}</dd></div>
      <div><dt>${uiText("world.nation.reputation")}</dt><dd>${reputation}</dd></div>
      <div><dt>${uiText("world.nation.youth_rating")}</dt><dd>${youth}</dd></div>
      <div><dt>${uiText("world.nation.manager")}</dt><dd>${escapeHtml(nation.manager || uiText("world.not_read"))}</dd></div>
    </dl>
    <button type="button" class="primary-action world-club-view" data-world-nation-view="${nationId}" aria-label="${uiText("world.view_details", {name:escapeHtml(nationName)})}">${uiText("world.view")}</button>
  </article>`;
}

function renderWorldNations() {
  const root = $("#world-nation-content");
  if (!root) return;
  const index = worldNationDataIndex();
  const data = index.data;
  syncWorldNationPageStatus(index);
  const signature = worldNationContentSignature(index);
  if (app.worldNationRenderSignature === signature) return;
  app.worldNationRenderSignature = signature;
  if (!data && app.worldNationsLoading) {
    root.innerHTML = `<div class="world-club-empty world-club-refreshing"><i data-lucide="loader-circle"></i><strong>${uiText("world.nations.loading")}</strong><span>${uiText("world.nations.loading")}</span></div>`;
    renderIcons(); return;
  }
  if (!data) {
    root.innerHTML = `<div class="world-club-empty"><i data-lucide="circle-alert"></i><strong>${uiText("world.nations.read_failed")}</strong><span>${escapeHtml(app.worldNationsError || uiText("world.nations.no_data"))}</span><button type="button" class="refresh-button" data-world-nations-retry><i data-lucide="refresh-cw"></i><span>${uiText("world.retry")}</span></button></div>`;
    root.querySelector("[data-world-nations-retry]")?.addEventListener("click", () => loadWorldNations({page:1}));
    renderIcons(); return;
  }
  const scan = index.scan;
  if (!data.ready) {
    root.innerHTML = `<div class="world-club-empty"><i data-lucide="plug-zap"></i><strong>${uiText("world.players.connect")}</strong><span>${uiText("world.nations.connect_note")}</span></div>`;
    renderIcons(); return;
  }
  if (!scan.ready || !(data.nations || []).length && !app.worldNationSearch && !app.worldNationContinent) {
    root.innerHTML = scan.scanning
      ? `<div class="world-scan-state"><div><strong>${uiText("world.clubs.scan_progress", {progress:Number(scan.progress || 0)})}</strong></div><progress max="100" value="${Number(scan.progress || 0)}"></progress></div>`
      : `<div class="world-club-empty"><i data-lucide="scan-search"></i><strong>${scan.error ? uiText("world.clubs.scan_failed") : uiText("world.nations.need_scan")}</strong><span>${uiText("world.nations.scan_note")}</span></div>`;
    renderIcons(); return;
  }
  const facets = index.facets;
  const filters = `<button type="button" class="${app.worldNationContinent ? "" : "active"}" data-world-nation-continent="" aria-pressed="${!app.worldNationContinent}">${uiText("world.all")} <span>${index.facetTotal}</span></button>${facets.map((row) => `<button type="button" class="${row.name === app.worldNationContinent ? "active" : ""}" data-world-nation-continent="${escapeHtml(row.name)}" aria-pressed="${row.name === app.worldNationContinent}">${escapeHtml(localizedContinentName(row.name))} <span>${Number(row.count || 0)}</span></button>`).join("")}`;
  const nations = index.nations;
  const pagination = index.pagination;
  const addressNotice = !scan.addresses_current ? `<div class="world-address-notice"><i data-lucide="circle-alert"></i><span>${uiText("world.nations.cache_notice")}</span></div>` : "";
  root.innerHTML = `${addressNotice}<div class="world-directory-tools"><div class="world-filter-row continents" role="group" aria-label="${uiText("world.clubs.filter_continent")}">${filters}</div></div>
    ${nations.length ? `<div class="world-result-heading"><strong>${app.worldNationContinent ? localizedContinentName(app.worldNationContinent) : uiText("world.nations.all_nations")}</strong><span>${pagination.from}-${pagination.to} / ${pagination.total}</span></div><div class="world-club-grid world-nation-grid">${nations.map(worldNationCard).join("")}</div>` : `<div class="world-club-empty compact"><i data-lucide="search-x"></i><strong>${uiText("world.nations.no_match")}</strong><span>${uiText("world.clubs.no_match_note")}</span></div>`}
    <nav class="world-pagination" aria-label="${uiText("world.page_aria")}"><button type="button" data-world-nation-page="${pagination.page - 1}" aria-label="${uiText("world.previous_page")}" ${pagination.page <= 1 ? "disabled" : ""}><i data-lucide="chevron-left"></i></button><span>${uiText("world.page", {page:pagination.page, total:pagination.page_count})}</span><button type="button" data-world-nation-page="${pagination.page + 1}" aria-label="${uiText("world.next_page")}" ${pagination.page >= pagination.page_count ? "disabled" : ""}><i data-lucide="chevron-right"></i></button></nav>`;
  root.querySelectorAll("[data-world-nation-continent]").forEach((button) => button.addEventListener("click", () => { app.worldNationContinent = button.dataset.worldNationContinent || ""; app.worldNationPage = 1; loadWorldNations({page:1}); }));
  root.querySelectorAll("[data-world-nation-page]").forEach((button) => button.addEventListener("click", () => { if (!button.disabled) loadWorldNations({page:Number(button.dataset.worldNationPage)}); }));
  root.querySelectorAll("[data-world-nation-view]").forEach((button) => button.addEventListener("click", () => openWorldNationDetail(Number(button.dataset.worldNationView))));
  syncWorldNationPageStatus(index);
  renderIcons();
}

function worldNationRankingMetric(player, ranking) {
  const value = player?.[ranking];
  if (value == null || value === "") return "-";
  if (ranking === "asking_price") return Number(value) > 0 ? compactMoney(value) : uiText("world.unlisted");
  return Number(value).toLocaleString(activeUiLocale());
}

function worldNationRankingProgress(player, ranking) {
  const value = Number(player?.[ranking]);
  if (!Number.isFinite(value) || value < 0) return null;
  const maximum = ranking === "pa" || ranking === "ca"
    ? 200 : ranking === "world_reputation" ? 10000 : 0;
  return maximum ? Math.max(0, Math.min(100, value / maximum * 100)) : null;
}

function renderWorldNationPlayerRanking(detail) {
  const state = detail.playerRanking || {ranking:"pa", page:1};
  const ranking = String(state.ranking || "pa");
  const tabs = [
    ["pa", "PA"], ["ca", "CA"], ["asking_price", uiText("world.column.asking_price")],
    ["world_reputation", uiText("world.ranking.world_reputation")],
  ];
  const tabIcons = {
    pa:"sparkles", ca:"gauge", asking_price:"badge-pound-sterling",
    world_reputation:"star",
  };
  const data = state.data;
  const players = data?.players || [];
  const pagination = data?.pagination || {page:Number(state.page || 1), page_count:1, page_size:30, total:0};
  const label = tabs.find(([key]) => key === ranking)?.[1] || "PA";
  let body = "";
  if (state.loading) {
    body = `<div class="world-nation-ranking-state"><i data-lucide="loader-circle"></i><strong>${uiText("world.ranking.loading", {label:escapeHtml(label)})}</strong></div>`;
  } else if (state.error) {
    body = `<div class="world-nation-ranking-state error"><i data-lucide="circle-alert"></i><strong>${uiText("world.ranking.read_failed")}</strong><span>${escapeHtml(state.error)}</span><button type="button" data-world-nation-ranking-retry>${uiText("world.retry")}</button></div>`;
  } else if (!players.length) {
    body = `<div class="world-nation-ranking-state"><i data-lucide="users"></i><strong>${uiText("world.ranking.empty")}</strong></div>`;
  } else {
    const startRank = (Number(pagination.page || 1) - 1) * Number(pagination.page_size || 30);
    body = `<div class="world-nation-ranking-table" role="table" aria-label="${uiText("world.nation.ranking_aria", {label:escapeHtml(label)})}">
      <div class="world-nation-ranking-head" role="row"><span role="columnheader">${uiText("league.rank")}</span><span role="columnheader">${uiText("common.player")}</span><span role="columnheader">${uiText("world.column.age")}</span><span role="columnheader">${uiText("world.column.club")}</span><span role="columnheader">${escapeHtml(label)}</span></div>
      <div class="world-nation-ranking-list" role="rowgroup">${players.map((player, index) => {
        const rank = startRank + index + 1;
        const rankTone = rank <= 3 ? ` podium podium-${rank}` : "";
        const progress = worldNationRankingProgress(player, ranking);
        const playerName = player.name || String(player.id);
        return `<div class="world-nation-ranking-row" role="row" tabindex="0" data-world-nation-player="${Number(player.id || 0)}" aria-label="${uiText("world.nation.ranking_view_player", {player:escapeHtml(playerName)})}"><span class="world-nation-ranking-rank${rankTone}" role="cell"><b>${rank}</b></span><span class="world-nation-ranking-player" role="cell" title="UID ${Number(player.id || 0)}"><span><strong>${escapeHtml(playerName)}</strong><small>${escapeHtml((player.positions || []).join("/") || uiText("world.nation.ranking_position_missing"))}</small></span></span><span class="world-nation-ranking-age" role="cell">${player.age == null ? "-" : Number(player.age)}</span><span class="world-nation-ranking-club" role="cell">${escapeHtml(player.team_name || uiText("world.nation.ranking_free_agent"))}</span><span class="world-nation-ranking-metric metric-${ranking}" role="cell"><strong>${escapeHtml(worldNationRankingMetric(player, ranking))}</strong>${progress == null ? "" : `<i aria-hidden="true"><b style="width:${progress.toFixed(1)}%"></b></i>`}</span></div>`;
      }).join("")}</div>
    </div>`;
  }
  const paginationControls = !state.loading && !state.error && data ? `<nav class="world-pagination world-nation-ranking-pagination" aria-label="${uiText("world.nation.ranking_pagination")}"><button type="button" data-world-nation-ranking-page="${Number(pagination.page || 1) - 1}" aria-label="${uiText("world.previous_page")}" ${Number(pagination.page || 1) <= 1 ? "disabled" : ""}><i data-lucide="chevron-left"></i></button><span>${uiText("world.nation.ranking_page", {page:Number(pagination.page || 1), total:Number(pagination.page_count || 1), count:Number(pagination.total || 0)})}</span><button type="button" data-world-nation-ranking-page="${Number(pagination.page || 1) + 1}" aria-label="${uiText("world.next_page")}" ${Number(pagination.page || 1) >= Number(pagination.page_count || 1) ? "disabled" : ""}><i data-lucide="chevron-right"></i></button></nav>` : "";
  return `<section class="world-nation-ranking" aria-labelledby="world-nation-ranking-title" aria-busy="${Boolean(state.loading)}">
    <header><div class="world-nation-ranking-heading"><span class="world-nation-ranking-emblem"><i data-lucide="trophy" aria-hidden="true"></i></span><div><h3 id="world-nation-ranking-title">${uiText("world.nation.ranking_title")}</h3>${data ? `<span>${uiText("world.nation.ranking_count", {count:Number(pagination.total || 0)})}</span>` : ""}</div></div><div class="world-nation-ranking-tabs" role="tablist" aria-label="${uiText("world.nation.ranking_type")}">${tabs.map(([key, tabLabel]) => `<button type="button" role="tab" data-world-nation-ranking="${key}" aria-selected="${ranking === key}" class="${ranking === key ? "active" : ""}" ${state.loading ? "disabled" : ""}><i data-lucide="${tabIcons[key]}" aria-hidden="true"></i><span>${tabLabel}</span></button>`).join("")}</div></header>
    ${body}${data?.price_note ? `<p class="world-nation-ranking-note">${escapeHtml(data.price_note)}</p>` : ""}${paginationControls}
  </section>`;
}

function renderWorldNationDetail(detail) {
  const nation = detail.nation || {};
  const team = detail.national_team || {};
  const manager = detail.manager || {};
  const investment = detail.investment || {};
  const youth = Number(nation.youth_rating || 0);
  const available = Boolean(investment.available && investment.price != null);
  const investmentOptions = (investment.options || []).filter(Boolean);
  const optionButton = (requestedIncrease) => {
    const quote = investmentOptions.find((row) => Number(row.requested_increase) === requestedIncrease)
      || (requestedIncrease === 1 && available ? {increase:1,price:investment.price} : null);
    const enabled = Boolean(quote && Number(quote.increase) !== 0 && quote.price != null);
    const increase = Number(quote?.increase || requestedIncrease);
    const increaseLabel = increase > 0 ? `+${increase}` : String(increase);
    const priceLabel = enabled ? compactMoney(quote.price) : uiText("world.nation.not_adjustable");
    return `<button type="button" class="primary-action" data-world-nation-invest="${Number(nation.id)}" data-youth-rating="${youth}" data-youth-increase="${requestedIncrease}" aria-label="${uiText("world.nation.adjust_aria", {increase:increaseLabel, price:priceLabel})}" ${enabled ? "" : "disabled"}><span>${increaseLabel}</span><small>${priceLabel}</small></button>`;
  };
  return `<div class="world-nation-profile">
    <dl class="world-detail-summary">
      <div><small>${uiText("world.nation.manager_mens")}</small><strong>${escapeHtml(manager.name || uiText("world.nation.vacant"))}</strong></div>
      <div><small>${uiText("world.nation.reputation")}</small><strong>${team.reputation == null ? uiText("world.not_read") : Number(team.reputation).toLocaleString(activeUiLocale())}</strong></div>
      <div><small>${uiText("world.nation.youth_rating")}</small><strong>${youth} / 200</strong></div>
      <div><small>${uiText("world.nation.continent")}</small><strong>${escapeHtml(localizedContinentName(nation.continent))}</strong></div>
    </dl>
    <section class="world-nation-investment">
      <div class="world-nation-investment-copy"><small>${uiText("world.nation.invest_youth")}</small><strong>${youth}</strong>${available ? "" : `<span>${uiText("world.nation.max_rating")}</span>`}</div>
      <div class="world-nation-investment-actions">${optionButton(-5)}${optionButton(-1)}${optionButton(1)}${optionButton(5)}</div>
    </section>
    ${renderWorldNationPlayerRanking(detail)}
  </div>`;
}

function isCurrentWorldNationDetail(content, requestKey, nationId) {
  const dialog = $("#world-nation-detail-dialog");
  return Boolean(
    dialog?.open
    && Number(app.worldNationDetailRequestKey || 0) === Number(requestKey)
    && Number(content?.dataset.worldNationDetailRequestKey || 0) === Number(requestKey)
    && Number(content?.dataset.worldNationDetailNationId || 0) === Number(nationId)
  );
}

function syncWorldNationDetailBusy() {
  const dialog = $("#world-nation-detail-dialog");
  const content = $("#world-nation-detail-content");
  const status = $("#world-nation-detail-status");
  const busy = Boolean(app.worldNationDetailBusy);
  dialog?.setAttribute("aria-busy", String(busy));
  content?.setAttribute("aria-busy", String(busy));
  if (status) {
    status.hidden = !busy;
    const label = status.querySelector("span");
    if (label) label.textContent = busy
      ? app.worldNationDetailBusyLabel || uiText("world.nation.detail_syncing")
      : "";
  }
  dialog?.querySelectorAll("button,input,select,textarea").forEach((control) => {
    if (busy && app.worldNationDetailBlocking) {
      if (!Object.hasOwn(control.dataset, "worldNationDetailWasDisabled")) {
        control.dataset.worldNationDetailWasDisabled = String(control.disabled);
      }
      control.disabled = true;
      return;
    }
    if (!Object.hasOwn(control.dataset, "worldNationDetailWasDisabled")) return;
    control.disabled = control.dataset.worldNationDetailWasDisabled === "true";
    delete control.dataset.worldNationDetailWasDisabled;
  });
}

function beginWorldNationDetailBusy(
  label,
  {requestKey = app.worldNationDetailRequestKey, blocking = false} = {},
) {
  const dialog = $("#world-nation-detail-dialog");
  const content = $("#world-nation-detail-content");
  if (!dialog?.open || Number(requestKey) !== Number(app.worldNationDetailRequestKey)
      || Number(content?.dataset.worldNationDetailRequestKey || 0) !== Number(requestKey)) return null;
  if (app.worldNationDetailBusy) return null;
  app.worldNationDetailBusyRequestKey = Number(requestKey);
  app.worldNationDetailBusy = true;
  app.worldNationDetailBlocking = Boolean(blocking);
  app.worldNationDetailBusyLabel = label;
  syncWorldNationDetailBusy();
  return () => {
    if (Number(app.worldNationDetailBusyRequestKey) !== Number(requestKey)) return;
    app.worldNationDetailBusy = false;
    app.worldNationDetailBlocking = false;
    app.worldNationDetailBusyLabel = "";
    syncWorldNationDetailBusy();
  };
}

async function runWorldNationDetailOperation(button, label, task, operationKey = "") {
  const requestKey = Number(app.worldNationDetailRequestKey || 0);
  const finish = beginWorldNationDetailBusy(label, {requestKey, blocking:true});
  if (!finish) throw new Error(uiText("world.nation.detail_busy"));
  try {
    return await task();
  } finally {
    finish();
  }
}

function refreshWorldNationDetailContent(content, detail, nationId, requestKey) {
  if (!isCurrentWorldNationDetail(content, requestKey, nationId)) return;
  content.innerHTML = renderWorldNationDetail(detail);
  bindWorldNationDetailActions(content, detail, nationId, requestKey);
  syncWorldNationDetailBusy();
  renderIcons(content);
}

async function loadWorldNationPlayers(content, detail, nationId, requestKey, ranking = "pa", page = 1) {
  if (!isCurrentWorldNationDetail(content, requestKey, nationId)) return;
  const state = detail.playerRanking || {requestKey:0};
  detail.playerRanking = state;
  const rankingRequestKey = Number(state.requestKey || 0) + 1;
  Object.assign(state, {
    requestKey:rankingRequestKey, ranking:String(ranking || "pa"),
    page:Math.max(1, Number(page || 1)), loading:true, error:"", data:null,
  });
  refreshWorldNationDetailContent(content, detail, nationId, requestKey);
  try {
    const query = new URLSearchParams({
      nation_id:String(Number(nationId)), ranking:state.ranking,
      page:String(state.page), page_size:"30",
    });
    const response = await request(`/api/world-nations/players?${query}`);
    if (
      !isCurrentWorldNationDetail(content, requestKey, nationId)
      || Number(state.requestKey) !== rankingRequestKey
    ) return;
    state.data = response;
    state.page = Number(response.pagination?.page || 1);
    state.error = "";
  } catch (error) {
    if (
      !isCurrentWorldNationDetail(content, requestKey, nationId)
      || Number(state.requestKey) !== rankingRequestKey
    ) return;
    state.error = error.message || uiText("world.nation.ranking_read_failed");
  } finally {
    if (
      isCurrentWorldNationDetail(content, requestKey, nationId)
      && Number(state.requestKey) === rankingRequestKey
    ) {
      state.loading = false;
      refreshWorldNationDetailContent(content, detail, nationId, requestKey);
    }
  }
}

function bindWorldNationDetailActions(content, detail, nationId, requestKey) {
  content.querySelectorAll("[data-world-nation-invest]").forEach((button) => button.addEventListener("click", async (event) => {
    const activeButton = event.currentTarget;
    if (activeButton.disabled || !isCurrentWorldNationDetail(content, requestKey, nationId)) return;
    const current = Number(activeButton.dataset.youthRating || 0);
    const requestedIncrease = Number(activeButton.dataset.youthIncrease || 1);
    try {
      await runWorldNationDetailOperation(activeButton, uiText("world.nation.adjusting_youth"), async () => {
        const result = await request("/api/world-nations/invest", {
          method:"POST", headers:{"Content-Type":"application/json"},
          body:JSON.stringify({nation_id:Number(activeButton.dataset.worldNationInvest), expected_youth_rating:current, increase:requestedIncrease}),
        });
        if (Number(app.worldNationDetailRequestKey || 0) !== Number(requestKey)) return;
        const after = Number(result.native?.after ?? current + requestedIncrease);
        const row = worldNationDataIndex().nationsById.get(Number(nationId));
        if (row) {
          row.youth_rating = after;
          invalidateWorldNationDataIndex();
        }
        applyEconomySnapshot(result.economy);
        toast(result.warning || uiText("world.nation.youth_adjusted", {rating:after}));
        renderWorldNations();
        if (isCurrentWorldNationDetail(content, requestKey, nationId)) {
          detail.nation = {...(detail.nation || {}), youth_rating:after};
          detail.investment = result.investment || detail.investment;
          content.innerHTML = renderWorldNationDetail(detail);
          bindWorldNationDetailActions(content, detail, nationId, requestKey);
          syncWorldNationDetailBusy();
          renderIcons();
        }
      }, `world-nation-invest:${requestKey}:${nationId}:${requestedIncrease}`);
    } catch (error) {
      toast(error.message || uiText("world.nation.youth_invest_failed"));
    }
  }));
  content.querySelectorAll("[data-world-nation-ranking]").forEach((button) => button.addEventListener("click", () => {
    if (button.disabled) return;
    loadWorldNationPlayers(content, detail, nationId, requestKey, button.dataset.worldNationRanking, 1);
  }));
  content.querySelectorAll("[data-world-nation-ranking-page]").forEach((button) => button.addEventListener("click", () => {
    if (button.disabled) return;
    loadWorldNationPlayers(content, detail, nationId, requestKey, detail.playerRanking?.ranking || "pa", Number(button.dataset.worldNationRankingPage));
  }));
  content.querySelector("[data-world-nation-ranking-retry]")?.addEventListener("click", () => {
    loadWorldNationPlayers(content, detail, nationId, requestKey, detail.playerRanking?.ranking || "pa", detail.playerRanking?.page || 1);
  });
  content.querySelectorAll("[data-world-nation-player]").forEach((row) => {
    const open = () => openWorldPlayerDetail(Number(row.dataset.worldNationPlayer));
    row.addEventListener("click", open);
    row.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        open();
      }
    });
  });
}

async function openWorldNationDetail(nationId) {
  const dialog = $("#world-nation-detail-dialog");
  const content = $("#world-nation-detail-content");
  const nation = worldNationDataIndex().nationsById.get(Number(nationId));
  const requestKey = Number(app.worldNationDetailRequestKey || 0) + 1;
  app.worldNationDetailRequestKey = requestKey;
  content.dataset.worldNationDetailRequestKey = String(requestKey);
  content.dataset.worldNationDetailNationId = String(Number(nationId));
  app.worldNationDetailBusyRequestKey = requestKey;
  app.worldNationDetailBusy = false;
  app.worldNationDetailBlocking = false;
  app.worldNationDetailBusyLabel = "";
  $("#world-nation-detail-title").textContent = localizedNationName(nation) || uiText("world.nation.detail_title");
  $("#world-nation-detail-subtitle").textContent = uiText("world.nation.detail_loading");
  content.innerHTML = `<div class="empty-feature">${uiText("world.nation.detail_loading_short")}</div>`;
  if (!dialog.open) dialog.showModal();
  const finishBusy = beginWorldNationDetailBusy(
    uiText("world.nation.detail_loading"),
    {requestKey, blocking:false},
  );
  try {
    const detail = await request(`/api/world-nations/detail?nation_id=${Number(nationId)}`);
    if (app.worldNationDetailRequestKey !== requestKey || !dialog.open) return;
    $("#world-nation-detail-title").textContent = localizedNationName(detail.nation || nation) || uiText("world.nation.detail_title");
    $("#world-nation-detail-subtitle").textContent = `${localizedContinentName(detail.nation?.continent || nation?.continent)} · ${uiText("world.nation.mens_team")}`;
    if (nation) {
      nation.reputation = detail.national_team?.reputation ?? null;
      nation.manager = detail.manager?.name || uiText("world.nation.vacant");
      nation.youth_rating = detail.nation?.youth_rating ?? nation.youth_rating;
      invalidateWorldNationDataIndex();
      renderWorldNations();
    }
    detail.playerRanking = {
      requestKey:0, ranking:"pa", page:1, loading:false, error:"", data:null,
    };
    content.innerHTML = renderWorldNationDetail(detail);
    bindWorldNationDetailActions(content, detail, nationId, requestKey);
    syncWorldNationDetailBusy();
    renderIcons(content);
    void loadWorldNationPlayers(content, detail, nationId, requestKey, "pa", 1);
  } catch (error) {
    if (app.worldNationDetailRequestKey !== requestKey) return;
    content.innerHTML = `<div class="world-club-empty compact"><i data-lucide="circle-alert"></i><strong>${uiText("world.nation.detail_read_failed")}</strong><span>${escapeHtml(error.message || uiText("world.ranking.read_failed"))}</span></div>`;
    renderIcons();
  } finally {
    finishBusy?.();
  }
}

async function scanWorldNations() {
  app.worldNationsRebuilding = true;
  renderWorldNations();
  try {
    const response = await request("/api/world-clubs/scan", {method:"POST", headers:{"Content-Type":"application/json"}, body:"{}"});
    if (app.worldNations && response.native_scan) {
      app.worldNations = {...app.worldNations, native_scan:response.native_scan};
      renderWorldNations();
      syncWorldNationScanPolling(app.worldNations);
    }
    const latest = await loadWorldNations({page:1});
    if (latest?.native_scan?.ready && latest.native_scan.addresses_current) {
      app.internationalNations = null;
      app.internationalNationError = "";
      if (app.page === "activity" && app.activityFloor === "international") {
        void loadInternationalNations();
      }
    }
  } catch (error) { toast(error.message || uiText("world.scan_nations_failed")); }
  finally {
    app.worldNationsRebuilding = false;
    renderWorldNations();
  }
}

async function scanWorldClubs() {
  try {
    const response = await request("/api/world-clubs/scan", {method:"POST", headers:{"Content-Type":"application/json"}, body:"{}"});
    if (app.worldClubs && response.native_scan) {
      app.worldClubs = {...app.worldClubs, native_scan:response.native_scan};
      renderWorldClubs();
      syncWorldClubScanPolling(app.worldClubs);
    }
    await loadWorldClubs({page:1});
  } catch (error) { toast(error.message || uiText("world.scan_clubs_failed")); }
}

function worldClubDetailPlayers(players) {
  return (players || []).map((player) => `<div class="world-detail-player-name">${escapeHtml(player.name || String(player.id))}</div>`).join("");
}

function clubIncomeStatementValue(finances, key, period) {
  const rows = finances?.income_statement?.income;
  if (!Array.isArray(rows)) return null;
  const raw = rows.find((row) => row?.key === key)?.[period];
  if (raw == null || raw === "") return null;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

function renderClubIncomeReport(finances, {collapsible = false} = {}) {
  const sourceRows = finances?.income_statement?.income;
  const periods = ["this_month", "last_month", "this_season", "last_season"];
  const rows = Array.isArray(sourceRows)
    ? sourceRows.filter((row) => periods.some((period) => Number(row?.[period] || 0) !== 0))
    : [];
  const money = (raw) => raw == null ? uiText("portfolio.not_read") : formatPounds(raw);
  const total = (period) => rows.reduce((sum, row) => sum + Number(row?.[period] || 0), 0);
  const totals = Object.fromEntries(periods.map((period) => [period, total(period)]));
  const seasonShare = (raw) => totals.this_season > 0
    ? `${(Number(raw || 0) / totals.this_season * 100).toFixed(1)}%`
    : "-";
  const body = rows.length
    ? `${rows.map((row) => `<tr><th scope="row">${escapeHtml(row.name || row.key || uiText("portfolio.unknown_income"))}</th><td>${escapeHtml(money(row.this_month))}</td><td>${escapeHtml(money(row.last_month))}</td><td>${escapeHtml(money(row.this_season))}</td><td>${escapeHtml(money(row.last_season))}</td><td>${escapeHtml(seasonShare(row.this_season))}</td></tr>`).join("")}<tr class="club-income-report-total"><th scope="row">${uiText("portfolio.income.total")}</th><td>${escapeHtml(money(totals.this_month))}</td><td>${escapeHtml(money(totals.last_month))}</td><td>${escapeHtml(money(totals.this_season))}</td><td>${escapeHtml(money(totals.last_season))}</td><td>${totals.this_season > 0 ? "100.0%" : "-"}</td></tr>`
    : `<tr><td colspan="6" class="club-income-report-empty">${uiText("portfolio.income.empty")}</td></tr>`;
  const table = `<div class="club-statement-scroll"><table class="club-income-report-table"><thead><tr><th scope="col">${uiText("portfolio.income.source")}</th><th scope="col">${uiText("portfolio.income.this_month")}</th><th scope="col">${uiText("portfolio.income.last_month")}</th><th scope="col">${uiText("portfolio.income.this_season")}</th><th scope="col">${uiText("portfolio.income.last_season")}</th><th scope="col">${uiText("portfolio.income.season_share")}</th></tr></thead><tbody>${body}</tbody></table></div>`;
  if (collapsible) {
    return `<details class="club-income-report club-income-report-collapsible"><summary><div><small>INCOME REPORT</small><h3>${uiText("portfolio.income.title")}</h3></div><span class="club-income-report-toggle"><span class="club-income-report-expand-label">${uiText("portfolio.income.expand")}</span><span class="club-income-report-collapse-label">${uiText("portfolio.income.collapse")}</span><i data-lucide="chevron-down"></i></span></summary>${table}</details>`;
  }
  return `<section class="club-income-report"><header><div><small>INCOME REPORT</small><h3>${uiText("portfolio.income.title")}</h3></div><i data-lucide="receipt-text"></i></header>${table}</section>`;
}

function renderWorldClubInformation(detail, club, {showIncomeReport = false} = {}) {
  const info = detail.club_information || {};
  const facilities = info.facilities || {};
  const finances = info.finances || {};
  const status = info.status || {};
  const stadium = info.stadium || {};
  const ticketIncomeThisMonth = clubIncomeStatementValue(finances, "gate_receipts", "this_month");
  const ticketIncomeThisSeason = clubIncomeStatementValue(finances, "gate_receipts", "this_season");
  const text = (value, suffix = "") => value == null || value === "" ? uiText("portfolio.not_read") : `${value}${suffix}`;
  const number = (value, suffix = "") => value == null ? uiText("portfolio.not_read") : `${Number(value).toLocaleString(activeUiLocale())}${suffix}`;
  const money = (value) => value == null ? uiText("portfolio.not_read") : formatPounds(value);
  const fact = (label, value) => `<div><dt>${escapeHtml(label)}</dt><dd title="${escapeHtml(String(value))}">${escapeHtml(String(value))}</dd></div>`;
  const section = (title, icon, rows) => `<section class="world-detail-info-section"><header><h3>${escapeHtml(title)}</h3><i data-lucide="${icon}"></i></header><dl>${rows.map(([label, value]) => fact(label, value)).join("")}</dl></section>`;
  const facilitiesSection = section(uiText("portfolio.facilities"), "warehouse", [
    [uiText("portfolio.facility.training"), text(facilities.training, " / 20")],
    [uiText("portfolio.facility.youth"), text(facilities.youth, " / 20")],
    [uiText("portfolio.facility.coaching"), text(facilities.junior_coaching, " / 20")],
    [uiText("portfolio.facility.recruitment"), text(facilities.youth_recruitment, " / 20")],
  ]);
  const financesSection = section(uiText("portfolio.finances"), "badge-pound-sterling", [
    [uiText("portfolio.finance.balance"), money(finances.balance)],
    [uiText("portfolio.finance.transfer_budget"), money(finances.remaining_transfer_budget ?? finances.season_transfer_budget)],
    [uiText("portfolio.finance.wage_budget"), money(finances.wage_budget)],
    [uiText("portfolio.finance.ticket_price"), money(finances.average_match_ticket_price)],
    [uiText("portfolio.finance.ticket_month"), money(ticketIncomeThisMonth)],
    [uiText("portfolio.finance.ticket_season"), money(ticketIncomeThisSeason)],
  ]);
  const statusSection = section(uiText("portfolio.club_status"), "badge-info", [
    [uiText("portfolio.status.nature"), localizedClubNature(status)],
    [uiText("portfolio.status.morale"), text(status.morale)],
    [uiText("portfolio.status.nation"), localizedClubNation(detail.club || club, info.nation)],
    [uiText("portfolio.status.city"), stadium.location?.name || (stadium.location?.id != null ? `ID ${stadium.location.id}` : uiText("portfolio.not_read"))],
  ]);
  const stadiumSection = section(uiText("portfolio.stadium"), "landmark", [
    [uiText("portfolio.stadium"), stadium.name || uiText("portfolio.not_read")],
    [uiText("portfolio.stadium.built"), stadium.build_date || uiText("portfolio.not_read")],
    [uiText("portfolio.stadium.capacity"), number(stadium.capacity)],
    [uiText("portfolio.stadium.state"), localizedStadiumState(stadium)],
    [uiText("portfolio.stadium.pitch_condition"), text(stadium.pitch_condition, " / 200")],
    [uiText("portfolio.stadium.pitch_type"), localizedStadiumPitchType(stadium)],
  ]);
  return `<div class="world-detail-info-layout"><div>${facilitiesSection}${financesSection}</div><div>${statusSection}${stadiumSection}</div></div>${showIncomeReport ? renderClubIncomeReport(finances) : ""}`;
}

function ownedClubAction(label, icon, action, tone = "", disabled = false) {
  const displayLabel = ["sponsorship-coming-soon", "club-meeting-coming-soon"].includes(action)
    ? uiText("portfolio.coming_soon", {label:uiLegacy(label)}) : uiLegacy(label);
  return `<button type="button" class="owned-club-action ${tone}" data-owned-action="${action}" ${disabled ? "disabled" : ""}><i data-lucide="${icon}"></i><span>${escapeHtml(displayLabel)}</span></button>`;
}

function beginOwnedClubOperation(button, label = uiText("portfolio.processing")) {
  if (!button || button.dataset.ownedBusy === "true") return null;
  const original = button.innerHTML;
  button.dataset.ownedBusy = "true";
  button.disabled = true;
  button.setAttribute("aria-busy", "true");
  button.innerHTML = `<i data-lucide="loader-circle"></i><span>${escapeHtml(label)}</span>`;
  renderIcons();
  return () => {
    button.innerHTML = original;
    button.disabled = false;
    button.removeAttribute("aria-busy");
    delete button.dataset.ownedBusy;
    if (button.isConnected) renderIcons();
  };
}

async function runOwnedClubOperation(button, label, task, operationKey = "", {skipDetailScope = false} = {}) {
  if (!skipDetailScope && button?.closest?.("#world-club-detail-content")) {
    return runWorldClubDetailOperation(button, label, task, operationKey);
  }
  if (operationKey && app.ownedClubOperationsInFlight.has(operationKey)) {
    throw new Error(uiText("portfolio.operation_busy"));
  }
  const finish = beginOwnedClubOperation(button, label);
  if (!finish) throw new Error(uiText("portfolio.operation_busy"));
  if (operationKey) app.ownedClubOperationsInFlight.add(operationKey);
  try {
    return await task();
  } finally {
    if (operationKey) app.ownedClubOperationsInFlight.delete(operationKey);
    finish();
  }
}

function syncWorldClubDetailBusy() {
  const dialog = $("#world-club-detail-dialog");
  const content = $("#world-club-detail-content");
  const status = $("#world-club-detail-status");
  const busy = Boolean(app.worldClubDetailBusy);
  dialog?.setAttribute("aria-busy", String(busy));
  content?.setAttribute("aria-busy", String(busy));
  if (status) {
    status.hidden = !busy;
    status.querySelector("span").textContent = busy
      ? app.worldClubDetailBusyLabel || uiText("portfolio.club_syncing")
      : "";
  }
  dialog?.querySelectorAll("button,input,select,textarea").forEach((control) => {
    const remainsAvailable = control.matches(
      ".close-dialog,[data-owned-tab],[data-owned-squad],"
      + '[data-owned-action="player-detail"],'
      + '[data-owned-action="load-staff"],'
      + '[data-owned-action="refresh-results"]',
    );
    if (busy && app.worldClubDetailBlocking && !remainsAvailable) {
      if (!Object.hasOwn(control.dataset, "worldClubDetailWasDisabled")) {
        control.dataset.worldClubDetailWasDisabled = String(control.disabled);
      }
      control.disabled = true;
      return;
    }
    if (!Object.hasOwn(control.dataset, "worldClubDetailWasDisabled")) return;
    control.disabled = control.dataset.worldClubDetailWasDisabled === "true";
    delete control.dataset.worldClubDetailWasDisabled;
  });
}

function beginWorldClubDetailBusy(label, {requestKey = app.worldClubDetailRequestKey, blocking = false} = {}) {
  const dialog = $("#world-club-detail-dialog");
  const content = $("#world-club-detail-content");
  if (!dialog?.open || Number(requestKey) !== Number(app.worldClubDetailRequestKey)
      || Number(content?.dataset.worldClubDetailRequestKey || 0) !== Number(requestKey)) return null;
  if (app.worldClubDetailBlocking && !blocking) return null;
  if (blocking && app.worldClubDetailBlocking) return null;
  const busyToken = Number(app.worldClubDetailBusyToken || 0) + 1;
  app.worldClubDetailBusyToken = busyToken;
  app.worldClubDetailBusyRequestKey = Number(requestKey);
  app.worldClubDetailBusy = true;
  app.worldClubDetailBlocking = Boolean(blocking);
  app.worldClubDetailBusyLabel = label;
  syncWorldClubDetailBusy();
  return () => {
    if (
      Number(app.worldClubDetailBusyRequestKey) !== Number(requestKey)
      || Number(app.worldClubDetailBusyToken || 0) !== busyToken
    ) return;
    app.worldClubDetailBusy = false;
    app.worldClubDetailBlocking = false;
    app.worldClubDetailBusyLabel = "";
    syncWorldClubDetailBusy();
  };
}

async function runWorldClubDetailOperation(button, label, task, operationKey = "") {
  const requestKey = Number(app.worldClubDetailRequestKey || 0);
  const finish = beginWorldClubDetailBusy(label, {requestKey, blocking:true});
  if (!finish) throw new Error(uiText("portfolio.club_busy"));
  try {
    return await runOwnedClubOperation(
      button,
      label,
      task,
      `world-club-detail:${requestKey}:${operationKey || label}`,
      {skipDetailScope:true},
    );
  } finally {
    finish();
  }
}

async function startOwnedClubSponsorship(content, detail, club, teamId, activeTab, button) {
  return runWorldClubDetailOperation(button, uiText("owned.sponsorship.busy"), async () => {
    const players = (detail.players || []).slice(0, 40).map((player) => ({id:Number(player.id || 0), name:String(player.name || player.id || uiText("owned.sponsorship.player"))})).filter((player) => player.id > 0);
    const result = await request("/api/world-clubs/sponsorship/search", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({team_id:Number(teamId), players})});
    detail.sponsorship = {campaign:result.campaign, contract:null};
    renderOwnedClubDetailContent(content, detail, club, teamId, activeTab);
    toast(uiText("owned.sponsorship.started"));
    return result;
  }, `sponsorship:${teamId}`);
}

function ownedClubMetric(label, value, tone = "") {
  return `<div${tone ? ` class="${escapeHtml(tone)}"` : ""}><dt>${escapeHtml(uiLegacy(label))}</dt><dd>${escapeHtml(uiLegacy(String(value ?? uiText("portfolio.not_read"))))}</dd></div>`;
}

function isClubControllerJobType(value) {
  return [4, 66, 70].includes(Number(value));
}

function ownedPlayerInjuryStatus(player) {
  const availability = player.availability || {};
  const injuries = (availability.injuries || [])
    .map((row) => String(row.type || uiText("owned.injury.default")).trim())
    .filter(Boolean);
  if (injuries.length || Number(availability.injury_count || 0) > 0) {
    return {label:[...new Set(injuries)].join(" / ") || uiText("owned.injury.injured"), tone:"injured"};
  }
  if (Number(availability.medical_unavailability_count || 0) > 0) {
    return {label:uiText("owned.injury.medical"), tone:"injured"};
  }
  return {label:uiText("owned.injury.healthy"), tone:"healthy"};
}

function ownedPlayerSeasonRating(player) {
  const rating = Number(player.season_rating);
  return Number.isFinite(rating) && rating > 0 ? rating.toFixed(2) : "-";
}

function ownedManagerRecordText(record) {
  if (!record) return uiText("world.pending");
  return uiText("portfolio.manager.record", {wins:Number(record.wins || 0), draws:Number(record.draws || 0), losses:Number(record.losses || 0)});
}

function ownedManagerSummary(record) {
  return `<div class="owned-manager-summary"><span><small>${uiText("portfolio.manager.current_season")}</small><strong>${escapeHtml(ownedManagerRecordText(record?.season))}</strong></span><span><small>${uiText("portfolio.manager.tenure")}</small><strong>${escapeHtml(ownedManagerRecordText(record?.total))}</strong></span></div>`;
}

function isCurrentWorldClubDetail(content, detail, teamId) {
  const requestKey = Number(detail?.worldClubDetailRequestKey || 0);
  const dialog = $("#world-club-detail-dialog");
  return Boolean(
    requestKey > 0
    && dialog?.open
    && Number(app.worldClubDetailRequestKey || 0) === requestKey
    && Number(content?.dataset.worldClubDetailRequestKey || 0) === requestKey
    && Number(content?.dataset.worldClubDetailTeamId || 0) === Number(teamId)
  );
}

function captureOwnedClubDetailViewState(content) {
  const active = document.activeElement;
  const state = {
    scrollTop:Number(content?.scrollTop || 0),
    scrollLeft:Number(content?.scrollLeft || 0),
    focus:null,
  };
  if (!active || !content?.contains(active)) return state;
  const attribute = [
    "data-owned-action", "data-owned-tab", "data-owned-squad",
    "data-owned-transfer-cancel", "data-owned-sugar-daddy-select",
  ].find((name) => active.hasAttribute?.(name));
  state.focus = {
    id:String(active.id || ""),
    attribute:attribute || "",
    value:attribute ? String(active.getAttribute(attribute) || "") : "",
    playerId:String(active.closest?.("[data-player-id]")?.dataset.playerId || ""),
    staffId:String(active.closest?.("[data-staff-id]")?.dataset.staffId || ""),
  };
  return state;
}

function restoreOwnedClubDetailViewState(content, state) {
  if (!content || !state) return;
  let target = state.focus?.id ? document.getElementById(state.focus.id) : null;
  if (!target && state.focus?.attribute) {
    target = [...content.querySelectorAll(`[${state.focus.attribute}]`)].find((candidate) => (
      String(candidate.getAttribute(state.focus.attribute) || "") === state.focus.value
      && (!state.focus.playerId || String(candidate.closest("[data-player-id]")?.dataset.playerId || "") === state.focus.playerId)
      && (!state.focus.staffId || String(candidate.closest("[data-staff-id]")?.dataset.staffId || "") === state.focus.staffId)
    ));
  }
  target?.focus?.({preventScroll:true});
  content.scrollTop = Number(state.scrollTop || 0);
  content.scrollLeft = Number(state.scrollLeft || 0);
}

async function loadOwnedClubStaff(content, detail, club, teamId, activeTab) {
  const cached = cachedOwnedClubDetail(teamId);
  if (
    detail.ownedStaffLoading
    || (detail.ownedStaffLoaded && ownedClubDetailSectionIsFresh(cached, "staff"))
  ) return;
  const requestedScope = ownedClubDetailScopeKey();
  const requestedRevision = ownedClubDetailSectionRevision(cached, "staff");
  detail.ownedStaffLoading = true;
  detail.ownedStaffError = null;
  renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || activeTab);
  try {
    const staff = await request(`/api/world-clubs/staff?team_id=${Number(teamId)}`);
    const currentCache = cachedOwnedClubDetail(teamId);
    if (
      requestedScope !== ownedClubDetailScopeKey()
      || requestedRevision !== ownedClubDetailSectionRevision(currentCache, "staff")
    ) return;
    detail.ownedStaff = staff.staff || [];
    detail.manager = staff.manager || null;
    detail.managerIsPlayer = Boolean(staff.manager_is_player);
    detail.managerRecord = staff.manager_record || null;
    detail.leadership = staff.leadership || {};
    detail.ownedStaffLoaded = true;
    rememberOwnedClubDetail(teamId, detail, {section:"staff"});
  } catch (error) {
      detail.ownedStaffError = error.message || uiText("owned.error.staff_read");
  } finally {
    detail.ownedStaffLoading = false;
    renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || activeTab);
  }
}

async function loadOwnedClubResults(content, detail, club, teamId, activeTab, force = false) {
  const cached = cachedOwnedClubDetail(teamId);
  if (
    detail.ownedResultsLoading
    || (detail.ownedResultsLoaded && !force
      && ownedClubDetailSectionIsFresh(cached, "results"))
  ) return;
  const requestedScope = ownedClubDetailScopeKey();
  const requestedRevision = ownedClubDetailSectionRevision(cached, "results");
  detail.ownedResultsLoading = true;
  detail.ownedResultsError = null;
  renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || activeTab);
  try {
    const query = new URLSearchParams({team_id:String(Number(teamId))});
    if (force) query.set("refresh", "1");
    const result = await request(`/api/world-clubs/results?${query}`);
    const currentCache = cachedOwnedClubDetail(teamId);
    if (
      requestedScope !== ownedClubDetailScopeKey()
      || requestedRevision !== ownedClubDetailSectionRevision(currentCache, "results")
    ) return;
    detail.club.recent_results = result.recent_results || [];
    detail.club.club_results = result.results || [];
    if (result.manager_record) detail.managerRecord = result.manager_record;
    detail.ownedResultsLoaded = true;
    rememberOwnedClubDetail(teamId, detail, {section:"results"});
    const acquired = (app.worldClubs?.acquired || []).find((row) => Number(row.id) === Number(teamId));
    if (acquired) Object.assign(acquired, result.club || {}, {recent_results:result.recent_results || []});
    renderMyClubs();
  } catch (error) {
      detail.ownedResultsError = error.message || uiText("owned.error.results_read");
  } finally {
    detail.ownedResultsLoading = false;
    renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || activeTab);
  }
}

async function loadOwnedClubSquads(content, detail, club, teamId, activeTab) {
  const cached = cachedOwnedClubDetail(teamId);
  if (
    detail.ownedSquadsLoading
    || (detail.ownedSquadsLoaded && ownedClubDetailSectionIsFresh(cached, "squads"))
  ) return;
  const requestedScope = ownedClubDetailScopeKey();
  const requestedRevision = Number(app.ownedClubDetailRevision || 0);
  const requestedSectionRevision = ownedClubDetailSectionRevision(cached, "squads");
  detail.ownedSquadsLoading = true;
  detail.ownedSquadsError = null;
  renderOwnedClubDetailContent(content, detail, club, teamId, activeTab);
  try {
    const expanded = await requestWorldClubDetail(teamId, {
      includeRelatedSquads:true,
    });
    if (
      requestedScope !== ownedClubDetailScopeKey()
      || requestedRevision !== Number(app.ownedClubDetailRevision || 0)
      || requestedSectionRevision !== ownedClubDetailSectionRevision(
        cachedOwnedClubDetail(teamId), "squads",
      )
    ) return;
    mergeOwnedClubDetail(detail, expanded);
    detail.related_squads_loaded = true;
    detail.ownedSquadsLoaded = true;
    rememberOwnedClubDetail(teamId, detail, {section:"squads"});
  } catch (error) {
      detail.ownedSquadsError = error.message || uiText("owned.error.squads_read");
  } finally {
    detail.ownedSquadsLoading = false;
    renderOwnedClubDetailContent(
      content, detail, club, teamId, detail.activeOwnedTab || activeTab,
    );
  }
}

async function loadOwnedClubFutureTransfers(content, detail, club, teamId) {
  const cached = cachedOwnedClubDetail(teamId);
  if (
    detail.ownedTransfersLoading
    || (detail.ownedTransfersLoaded
      && ownedClubDetailSectionIsFresh(cached, "transfers"))
  ) return;
  const requestedScope = ownedClubDetailScopeKey();
  const requestedRevision = ownedClubDetailSectionRevision(cached, "transfers");
  detail.ownedTransfersLoading = true;
  detail.ownedTransfersError = null;
  renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || "transfers");
  try {
    const result = await request(`/api/world-clubs/future-transfers?team_id=${Number(teamId)}`);
    const currentCache = cachedOwnedClubDetail(teamId);
    if (
      requestedScope !== ownedClubDetailScopeKey()
      || requestedRevision !== ownedClubDetailSectionRevision(currentCache, "transfers")
    ) return;
    detail.futureTransfers = result.transfers || [];
    detail.ownedTransfersLoaded = true;
    detail.ownedTransfersCacheHit = Boolean(result.manager_cache_hit);
    rememberOwnedClubDetail(teamId, detail, {section:"transfers"});
  } catch (error) {
      detail.ownedTransfersError = error.message || uiText("owned.error.transfers_read");
  } finally {
    detail.ownedTransfersLoading = false;
    renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || "transfers");
  }
}

async function cancelOwnedClubFutureTransfer(content, detail, club, teamId, button) {
  const transferId = Number(button.dataset.transferId);
  const offerAddress = button.dataset.offerAddress || "";
  const transfer = (detail.futureTransfers || []).find((row) =>
    Number(row.transfer_id) === transferId && String(row.offer_address) === offerAddress
  );
  if (!transfer) return;
  if (!await fmoddConfirm(uiText("portfolio.transfer.cancel_confirm", {player:transfer.player_name || uiText("portfolio.transfer.player")}), uiText("portfolio.transfer.cancel_title"))) return;
  try {
    await runOwnedClubOperation(button, uiText("portfolio.transfer.cancelling"), () => request("/api/world-clubs/future-transfers/cancel", {
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({
        team_id:Number(teamId),
        transfer_id:transferId,
        offer_address:offerAddress,
      }),
    }));
    detail.futureTransfers = (detail.futureTransfers || []).filter((row) =>
      Number(row.transfer_id) !== transferId || String(row.offer_address) !== offerAddress
    );
    rememberOwnedClubDetailMutation(teamId, detail, ["transfers"]);
    renderOwnedClubDetailContent(content, detail, club, teamId, "transfers");
    toast(uiText("portfolio.transfer.cancelled"));
  } catch (error) {
    renderOwnedClubDetailContent(content, detail, club, teamId, "transfers");
    toast(error.message || uiText("portfolio.transfer.cancel_failed"));
  }
}

function openOwnedClubRenameDialog(content, detail, club, teamId, activeTab, triggerButton) {
  const dialog = $("#owned-club-rename-dialog");
  const form = $("#owned-club-rename-form");
  const shortInput = $("#owned-club-rename-short-name");
  if (!dialog || !form || !shortInput) return;
  const price = Number(detail.owned_actions?.rename_price || toPurchaseInternalMoney(4000000));
  shortInput.value = detail.club?.short_name || club?.short_name || detail.club?.name || club?.name || "";
  $("#owned-club-rename-price").textContent = uiText("owned.rename.price", {price:formatPounds(price)});
  form.onsubmit = async (event) => {
    event.preventDefault();
    const shortName = shortInput.value.trim();
    if (!shortName) return;
    dialog.close();
    if (!await fmoddConfirm(uiText("owned.rename.club_confirm", {name:shortName, price:formatPounds(price)}), uiText("owned.rename.confirm"))) return;
    try {
      const result = await runOwnedClubOperation(triggerButton, uiText("owned.rename.busy"), () => request("/api/world-clubs/rename", {
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({team_id:Number(teamId), short_name:shortName}),
      }));
      detail.club.short_name = result.native?.after?.short_name || shortName;
      if (club) Object.assign(club, result.club || {}, {
        short_name:detail.club.short_name,
      });
      if (result.acquired) app.worldClubs.acquired = result.acquired;
      const directoryClub = (app.worldClubs?.clubs || []).find(
        (row) => Number(row.id) === Number(teamId),
      );
      if (directoryClub) Object.assign(directoryClub, result.club || {}, {
        display_name:detail.club.short_name,
      });
      app.worldClubIndexSource = null;
      app.ownedClubIndexSources = null;
      if (isCurrentWorldClubDetail(content, detail, teamId)) {
        $("#world-club-detail-title").textContent = detail.club.short_name || detail.club.name;
      }
      renderOwnedClubDetailContent(content, detail, club, teamId, activeTab);
      renderMyClubs();
      renderWorldClubs();
      toast(result.warning || uiText("owned.rename.club_done", {price:formatPounds(result.payment?.total || price)}));
    } catch (error) {
      toast(error.message || uiText("owned.rename.club_failed"));
    }
  };
  dialog.showModal();
  shortInput.focus();
  shortInput.select();
}

