async function upgradeOwnedStadium(content, detail, club, teamId, activeTab, action, button) {
  const stadium = detail.club_information?.stadium || {};
  const quote = detail.owned_actions?.stadium?.[action];
  if (!quote) {
    const message = action === "capacity"
    ? uiText("owned.stadium.capacity_max")
    : action === "expansion" ? uiText("owned.stadium.expansion_max")
      : action === "pitch_condition" ? uiText("owned.stadium.pitch_max")
      : uiText("owned.stadium.state_max");
    return toast(message);
  }
  const labels = {
    capacity:uiText("owned.stadium.capacity"), expansion:uiText("owned.stadium.expansion"), state:uiText("owned.stadium.state"), pitch_condition:uiText("owned.stadium.pitch_condition"),
  };
  const before = action === "state" ? localizedStadiumState(stadium) : Number(quote.before).toLocaleString();
  const after = action === "state" ? localizedStadiumStateFromRaw(quote.after) : Number(quote.after).toLocaleString();
  const price = Number(quote.price || 0);
  if (!await fmoddConfirm(
    uiText("owned.stadium.upgrade_confirm", {field:labels[action], before, after, price:formatPounds(price)}),
    uiText("owned.stadium.upgrade_title"),
  )) return;
  try {
    const result = await runOwnedClubOperation(button, uiText("owned.stadium.upgrading"), () => request("/api/world-clubs/stadium", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({team_id:Number(teamId), action}),
    }));
    Object.assign(stadium, result.stadium || result.native?.after || {});
    detail.owned_actions = result.owned_actions || detail.owned_actions;
    renderOwnedClubDetailContent(content, detail, club, teamId, detail.activeOwnedTab || activeTab);
    toast(uiText("owned.stadium.upgrade_done", {price:formatPounds(result.payment?.total || price), field:labels[action]}));
  } catch (error) {
    toast(error.message || uiText("owned.stadium.upgrade_failed", {field:labels[action]}));
  }
}

function applyPlayerMovementTargetRefresh(result) {
  const refreshed = Array.isArray(result?.refreshed_targets) ? result.refreshed_targets : [];
  for (const teamId of result?.affected_team_ids || []) {
    app.ownedClubMetrics.delete(Number(teamId));
  }
  const directories = [app.worldClubs?.clubs, app.worldClubs?.acquired];
  for (const target of refreshed) {
    const teamId = Number(target.id || 0);
    if (!teamId) continue;
    for (const rows of directories) {
      const row = Array.isArray(rows)
        ? rows.find((item) => Number(item.id) === teamId)
        : null;
      if (row && target.address) row.address = target.address;
    }
    app.ownedClubMetrics.delete(teamId);
  }
  app.ownedClubMetricsVersion += 1;
}

function removePlayerFromOwnedClubDetail(detail, playerId) {
  const id = Number(playerId);
  detail.players = (detail.players || []).filter((row) => Number(row.id) !== id);
  detail.squads = (detail.squads || []).map((squad) => {
    const players = (squad.players || []).filter((row) => Number(row.id) !== id);
    return {...squad, players, player_count:players.length};
  });
}

function movePlayerWithinOwnedClubDetail(
  detail, playerId, targetSquadTeamId, targetSquadAddress,
) {
  const id = Number(playerId);
  const player = (detail.players || []).find((row) => Number(row.id) === id);
  const targetSquad = (detail.squads || []).find(
    (row) => Number(row.team_id) === Number(targetSquadTeamId),
  );
  if (!player || !targetSquad) return;
  const updated = {
    ...player,
    squad_team_id:Number(targetSquadTeamId),
    squad_team_address:String(targetSquadAddress || targetSquad.team_address || ""),
    squad_type_code:targetSquad.type_code,
    squad_type:targetSquad.type,
    squad_label:targetSquad.label,
    squad_is_current:Number(targetSquad.type_code) === 0,
  };
  detail.players = (detail.players || []).map((row) => Number(row.id) === id ? updated : row);
  detail.squads = (detail.squads || []).map((squad) => {
    const players = (squad.players || []).filter((row) => Number(row.id) !== id);
    if (Number(squad.team_id) === Number(targetSquadTeamId)) players.push(updated);
    return {...squad, players, player_count:players.length};
  });
}

function ownedPlayerSquadPayload(player) {
  const sourceSquadTeamId = Number(player?.squad_team_id || 0);
  if (!sourceSquadTeamId) return {};
  return {
    source_squad_team_id:sourceSquadTeamId,
    source_squad_team_address:String(player?.squad_team_address || ""),
  };
}


function openOwnedPlayerMoveDialog(content, detail, club, teamId, activeTab, playerId, mode, triggerButton) {
  const dialog = $("#owned-player-move-dialog");
  const form = $("#owned-player-move-form");
  const target = $("#owned-player-move-target");
  const submitButton = $("#owned-player-move-confirm");
  const player = (detail.players || []).find((row) => Number(row.id) === Number(playerId));
  const targets = activeOwnedClubs().filter((row) => Number(row.id) !== Number(teamId));
  if (!dialog || !form || !target || !submitButton || !player) return;
  if (!targets.length) {
    toast(uiText("owned.player.move_minimum"));
    return;
  }
  const loan = mode === "loan";
  const submissionId = globalThis.crypto?.randomUUID?.()
    || `player-move-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  let submitting = false;
  app.ownedPlayerMove = {sourceTeamId:Number(teamId), playerId:Number(playerId), mode};
  $("#owned-player-move-title").textContent = loan ? uiText("owned.player.loan") : uiText("owned.player.transfer");
  $("#owned-player-move-player").textContent = player.name || String(player.id);
  $("#owned-player-move-target-label").textContent = uiText("owned.player.target_club");
  $("#owned-player-move-note").hidden = !loan;
  $("#owned-player-move-note").textContent = loan
    ? uiText("owned.player.loan_note")
    : "";
  submitButton.disabled = false;
  submitButton.textContent = loan ? uiText("owned.player.confirm_loan") : uiText("owned.player.confirm_transfer");
  target.innerHTML = targets.map((row) =>
    `<option value="${Number(row.id)}">${escapeHtml(row.name || row.short_name || String(row.id))}</option>`
  ).join("");
  form.onsubmit = async (event) => {
    event.preventDefault();
    if (submitting) {
      toast(uiText("portfolio.operation_busy"));
      return;
    }
    const targetTeamId = Number(target.value);
    const targetClub = targets.find((row) => Number(row.id) === targetTeamId);
    if (!targetTeamId || !targetClub) return;
    submitting = true;
    submitButton.disabled = true;
    submitButton.textContent = loan ? uiText("owned.player.moving_loan") : uiText("owned.player.moving_transfer");
    dialog.close();
  const verb = loan ? uiText("owned.player.loan_verb") : uiText("owned.player.permanent_transfer");
    if (!await fmoddConfirm(
      uiText("owned.player.confirm_move", {player:player.name || player.id, verb, target:targetClub.name || targetClub.short_name || targetTeamId}),
      loan ? uiText("owned.player.confirm_loan") : uiText("owned.player.confirm_transfer"),
    )) {
      submitting = false;
      submitButton.disabled = false;
      submitButton.textContent = loan ? uiText("owned.player.confirm_loan") : uiText("owned.player.confirm_transfer");
      return;
    }
    try {
      const operationKey = `player-move:${Number(teamId)}:${targetTeamId}:${Number(playerId)}:${mode}`;
      const result = await runOwnedClubOperation(
        triggerButton,
        loan ? uiText("owned.player.move_busy") : uiText("owned.player.transfer_busy"),
        () => request("/api/world-clubs/player-move", {
          method:"POST",
          headers:{"Content-Type":"application/json"},
          body:JSON.stringify({
            source_team_id:Number(teamId),
            ...ownedPlayerSquadPayload(player),
            target_team_id:targetTeamId,
            player_id:Number(playerId),
            mode,
            client_submission_id:submissionId,
          }),
        }),
        operationKey,
      );
      app.ownedPlayerMove = null;
      applyPlayerMovementTargetRefresh(result);
      removePlayerFromOwnedClubDetail(detail, playerId);
      rememberOwnedClubDetailMutation(teamId, detail, ["squads"]);
      invalidateOwnedClubDetailSections(targetTeamId, ["squads"]);
      renderOwnedClubDetailContent(content, detail, club, teamId, activeTab);
      toast(loan
      ? uiText("owned.player.loan_success")
        : (result.warning || result.refresh_warning || uiText("owned.player.move_done", {player:player.name || uiText("owned.player.selected"), target:result.target_team_name || targetClub.name})));
  } catch (error) {
    await fmoddAlert(error.message || uiText("owned.player.move_failed", {verb}));
  }
  };
  dialog.showModal();
  target.focus();
}

async function openOwnedPlayerSquadDialog(
  content, detail, club, teamId, activeTab, playerId, triggerButton,
) {
  const dialog = $("#owned-player-move-dialog");
  const form = $("#owned-player-move-form");
  const target = $("#owned-player-move-target");
  const submitButton = $("#owned-player-move-confirm");
  const player = (detail.players || []).find(
    (row) => Number(row.id) === Number(playerId),
  );
  const squads = Array.isArray(detail.squads) ? detail.squads : [];
  const sourceSquad = squads.find(
    (row) => Number(row.team_id) === Number(player?.squad_team_id),
  );
  if (!dialog || !form || !target || !submitButton || !player || !sourceSquad) {
    toast(uiText("owned.squad.changed"));
    return;
  }
  const promote = Number(sourceSquad.type_code) !== 0;
  const targets = squads.filter((row) => (
    Number(row.team_id) !== Number(sourceSquad.team_id)
    && (promote ? Number(row.type_code) === 0 : Number(row.type_code) !== 0)
  ));
  if (!targets.length) {
    toast(promote ? uiText("owned.squad.no_first_team") : uiText("owned.squad.no_lower"));
    return;
  }
  const verb = promote ? uiText("owned.squad.promote_verb") : uiText("owned.squad.demote_verb");
  const moveToSquad = async (targetSquad) => {
    const targetSquadTeamId = Number(targetSquad?.team_id || 0);
    if (!targetSquadTeamId) return;
    try {
      const result = await runOwnedClubOperation(
        triggerButton, uiText("owned.squad.moving", {verb}),
        () => request("/api/world-clubs/player-squad", {
          method:"POST",
          headers:{"Content-Type":"application/json"},
          body:JSON.stringify({
            team_id:Number(teamId),
            player_id:Number(playerId),
            source_squad_team_id:Number(sourceSquad.team_id),
            source_squad_team_address:String(sourceSquad.team_address || player.squad_team_address || ""),
            target_squad_team_id:targetSquadTeamId,
            target_squad_team_address:String(targetSquad.team_address || ""),
          }),
        }),
        `player-squad:${Number(teamId)}:${Number(playerId)}:${Number(sourceSquad.team_id)}:${targetSquadTeamId}`,
      );
      applyPlayerMovementTargetRefresh(result);
      movePlayerWithinOwnedClubDetail(
        detail, playerId, targetSquadTeamId, targetSquad.team_address,
      );
      rememberOwnedClubDetailMutation(teamId, detail, ["squads"]);
      renderOwnedClubDetailContent(content, detail, club, teamId, activeTab);
      toast(result.refresh_warning || uiText("owned.squad.move_done", {player:player.name || uiText("owned.player.selected"), verb, target:targetSquad.label || targetSquad.type}));
    } catch (error) {
      await fmoddAlert(error.message || uiText("owned.player.move_failed", {verb}));
    }
  };

  if (promote) {
    if (!await fmoddConfirm(
      uiText("owned.squad.promote_confirm", {player:player.name || player.id}),
      uiText("owned.squad.promote_title"),
    )) return;
    await moveToSquad(targets[0]);
    return;
  }

  $("#owned-player-move-title").textContent = uiText("owned.squad.demote_player");
  $("#owned-player-move-player").textContent = player.name || String(player.id);
  $("#owned-player-move-target-label").textContent = uiText("owned.squad.target");
  $("#owned-player-move-note").hidden = true;
  $("#owned-player-move-note").textContent = "";
  submitButton.disabled = false;
  submitButton.textContent = uiText("owned.squad.demote_title");
  target.innerHTML = targets.map((row) =>
    `<option value="${Number(row.team_id)}">${escapeHtml(row.label || row.type || String(row.team_id))}</option>`
  ).join("");
  form.onsubmit = async (event) => {
    event.preventDefault();
    const targetSquadTeamId = Number(target.value);
    const targetSquad = targets.find(
      (row) => Number(row.team_id) === targetSquadTeamId,
    );
    if (!targetSquadTeamId || !targetSquad) return;
    dialog.close();
    if (!await fmoddConfirm(
      uiText("owned.squad.demote_confirm", {player:player.name || player.id, squad:targetSquad.label || targetSquad.type || targetSquadTeamId}),
      uiText("owned.squad.demote_title"),
    )) return;
    await moveToSquad(targetSquad);
  };
  dialog.showModal();
  target.focus();
}

