  $("#owned-player-move-note").textContent = uiText("owned.staff.move_note");
  $("#owned-player-move-confirm").textContent = uiText("owned.player.confirm_transfer");
  target.innerHTML = targets.map((row) =>
    `<option value="${Number(row.id)}">${escapeHtml(row.name || row.short_name || String(row.id))}</option>`
  ).join("");
