      <p>
        <span>${escapeHtml(legacyPositions(player))}</span>
        <span>${escapeHtml(localizedNationName(snapshot.nationality) || uiText("legacy.profile.nationality_not_read"))}</span>
        ${snapshot.age != null ? `<span>${escapeHtml(uiText("legacy.profile.age", {count:snapshot.age}))}</span>` : ""}
        ${retirement ? `<span>${escapeHtml(retirement)}</span>` : ""}
      </p>
