function renderLegacyProfile(player) {
  if (!player) {
    return `<div class="legacy-hof-empty legacy-hof-profile-empty"><i data-lucide="landmark"></i><strong>${uiText("legacy.profile.choose_player")}</strong></div>`;
  }
  const backLabel = uiText(app.clubLegacyReturnPage === "club-transfers" ? "legacy.profile.back_transfers" : "legacy.profile.back_players");
  return `<article class="legacy-hof-profile" data-legacy-profile="${player.uid}">
    <div class="legacy-hof-profile-nav"><button type="button" class="legacy-hof-back" data-legacy-back><i data-lucide="arrow-left"></i><span>${backLabel}</span></button><span>${uiText("legacy.profile.permanent_archive", {uid:player.uid})}</span></div>
    ${renderLegacyProfileHeader(player)}
    ${renderLegacyProfileGlance(player)}
    <div class="legacy-hof-profile-columns">
      <main class="legacy-hof-profile-primary">
        ${renderLegacySeasonSection(player)}
        ${renderLegacyAttributeSection(player)}
        ${renderLegacyValueSection(player)}
      </main>
      <aside class="legacy-hof-profile-secondary">
        ${renderLegacyMatchMomentsSection(player)}
        ${renderLegacyShirtSection(player)}
        ${renderLegacyInjurySection(player)}
        ${renderLegacyTransferSection(player)}
      </aside>
    </div>
    <div class="legacy-hof-profile-foot">
      ${renderLegacyTimelineSection(player)}
      ${renderLegacyCurationSection(player)}
    </div>
  </article>`;
}

function renderClubLegacy() {
  if ((app.clubLegacyLoading || app.clubLegacyStatus?.refreshing) && !Object.keys(app.clubLegacyPool || {}).length) {
    return `<div class="legacy-hof-loading" role="status" aria-live="polite"><i data-lucide="loader-circle"></i><strong>${uiText("legacy.home.loading_title")}</strong><span>${uiText("legacy.home.loading_note")}</span><div><i></i><i></i><i></i></div></div>`;
  }
  if (app.clubLegacyError && !Object.keys(app.clubLegacyPool || {}).length) {
    return `<div class="legacy-hof-error" role="alert"><i data-lucide="circle-alert"></i><strong>${uiText("legacy.home.read_failed")}</strong><span>${escapeHtml(app.clubLegacyError)}</span><button type="button" data-legacy-retry><i data-lucide="refresh-cw"></i><span>${uiText("legacy.home.retry")}</span></button></div>`;
  }
  if (app.clubLegacyIndex && !(app.clubLegacyIndex.clubs || []).length) {
    return `<div class="legacy-hof-empty"><i data-lucide="landmark"></i><strong>${uiText("legacy.home.empty_title")}</strong><span>${uiText("legacy.home.empty_note")}</span></div>`;
  }
  const players = legacyMergedPlayers();
  const selected = players.find((player) => player.uid === Number(app.clubLegacySelectedUid)) || null;
  if (selected && Number(app.clubLegacyPreferredTeamId || 0) > 0) {
    selected.navigationTeamId = Number(app.clubLegacyPreferredTeamId);
    if (selected.clubs.some((club) => Number(club.teamId) === Number(app.clubLegacyPreferredTeamId))) {
      selected.prefTeamId = Number(app.clubLegacyPreferredTeamId);
    }
  }
  if (selected) return `<div class="legacy-hof legacy-hof-detail-view">${renderLegacyProfile(selected)}</div>`;
  const view = legacyActiveView(players);
  const viewPlayers = legacyViewPlayers(players, view);
  const currentTeamId = Number(app.clubLegacyIndex?.current_team_id || 0);
  const currentClub = app.clubLegacyIndex?.clubs?.find((club) => Number(club.id) === currentTeamId)?.name
    || players.find((player) => player.active)?.clubs?.find((club) => club.active)?.teamName || uiText("legacy.home.current_club");
  const updated = app.clubLegacyIndex?.clubs?.map((club) => club.coverage?.last_synced_game_date || club.summary?.last_synced_game_date).filter(Boolean).sort().at(-1) || uiText("legacy.home.not_synced");
  const viewLabels = {roster:"legacy.view.roster", watch:"legacy.view.watch", hall:"legacy.view.hall", best:"legacy.view.best"};
  const viewCounts = legacyViewCounts(players);
  const viewNav = Object.entries(viewLabels).map(([key, labelKey]) => `<button type="button" role="tab" aria-selected="${view === key}" class="${view === key ? "active" : ""}" data-legacy-view="${key}"><span>${uiText(labelKey)}</span><b>${key === "best" ? `${viewCounts[key]}/11` : viewCounts[key]}</b></button>`).join("");
  const body = view === "best"
    ? renderLegacyBestTeam(players)
    : `<div class="legacy-hof-home-top">${renderLegacyRecentChanges(players)}${renderLegacySeasonLeaders(players)}</div>
      ${view === "watch" ? renderLegacyWorldSearch(players) : ""}
      <section class="legacy-hof-player-data legacy-hof-panel"><header><div><small>${uiText(view === "roster" ? "legacy.home.roster_eyebrow" : view === "watch" ? "legacy.home.watch_eyebrow" : "legacy.home.hall_eyebrow")}</small><h2>${uiText(viewLabels[view] || "legacy.view.hall")}</h2></div><span>${uiText("legacy.home.people_count", {count:viewPlayers.length})}</span></header>${renderLegacyPlayerTable(viewPlayers)}</section>`;
  return `<div class="legacy-hof legacy-hof-home">
    <section class="legacy-hof-toolbar"><div class="legacy-hof-scope"><small>${uiText("legacy.home.current_club")}</small><strong>${escapeHtml(currentClub)}</strong><span>${uiText("legacy.home.last_synced", {date:escapeHtml(updated)})}</span></div><nav class="legacy-hof-views" role="tablist" aria-label="${uiText("legacy.home.scope_aria")}">${viewNav}</nav></section>
    ${body}
  </div>`;
}

async function searchLegacyWorldPlayers(query) {
  const normalized = String(query || "").trim();
  const requestKey = ++app.clubLegacyWorldRequestKey;
  if (normalized.length < 2) {
    app.clubLegacyWorldResults = [];
    app.clubLegacyWorldError = null;
    app.clubLegacyWorldLoading = false;
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
    return;
  }
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  app.clubLegacyWorldLoading = true;
  app.clubLegacyWorldError = null;
  app.clubLegacyRenderSignature = null;
  renderHallOfFame();
  try {
    const params = new URLSearchParams({search:normalized, page:"1", page_size:"12", sort_by:"pa", sort_order:"desc", gender:"all"});
    const response = await request(`/api/world-players?${params}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (requestKey !== app.clubLegacyWorldRequestKey || requestedScope !== currentScope) return;
    app.clubLegacyWorldResults = (response.players || []).slice(0, 12);
  } catch (error) {
    if (requestKey !== app.clubLegacyWorldRequestKey) return;
    app.clubLegacyWorldResults = [];
    app.clubLegacyWorldError = error.message || uiText("legacy.world_search.search_failed");
  } finally {
    if (requestKey === app.clubLegacyWorldRequestKey) {
      app.clubLegacyWorldLoading = false;
      app.clubLegacyRenderSignature = null;
      renderHallOfFame();
      const input = document.querySelector("[data-legacy-world-search]");
      input?.focus();
      if (input) input.setSelectionRange(input.value.length, input.value.length);
    }
  }
}

function scheduleLegacyWorldPlayerSearch(query) {
  const normalized = String(query || "");
  if (app.clubLegacyWorldSearchTimer) clearTimeout(app.clubLegacyWorldSearchTimer);
  app.clubLegacyWorldSearchTimer = null;
  if (normalized.trim().length < 2) {
    searchLegacyWorldPlayers(normalized);
    return;
  }
  app.clubLegacyWorldSearchTimer = setTimeout(() => {
    app.clubLegacyWorldSearchTimer = null;
    searchLegacyWorldPlayers(normalized);
  }, 300);
}

async function followLegacyWorldPlayer(uid) {
  const playerId = Number(uid || 0);
  if (!playerId || legacyPreferenceBusy(playerId)) return;
  app.clubLegacyPreferenceBusy.add(playerId);
  app.clubLegacyRenderSignature = null;
  renderHallOfFame();
  try {
    const payload = await request("/api/club-legacy/preference", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({team_id:-1, player_id:playerId, favorite:true}),
    });
    if (Number(payload?.club?.id || 0) === -1) {
      app.clubLegacyPool = {...app.clubLegacyPool, [-1]:payload};
      if (!app.clubLegacyIndex) app.clubLegacyIndex = {clubs:[], summary:{}};
      if (!(app.clubLegacyIndex.clubs || []).some((club) => Number(club.id) === -1)) {
        app.clubLegacyIndex.clubs.push({...payload.club, summary:payload.summary, coverage:payload.coverage});
      }
      app.clubLegacyRevision += 1;
    }
  } catch (error) {
    toast(error.message || uiText("legacy.world_search.follow_failed"));
  } finally {
    app.clubLegacyPreferenceBusy.delete(playerId);
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }
}

async function loadLegacyPlayerLiveProfile(uid, {force = false} = {}) {
  const playerId = Number(uid || 0);
  const scope = String(app.state?.data_scope_id || output().save_instance_id || "");
  if (!playerId || app.clubLegacyLiveLoading.has(playerId)
      || (!force && app.clubLegacyLivePlayers.has(playerId))) return;
  app.clubLegacyLiveLoading.add(playerId);
  try {
    const response = await request(`/api/world-players/detail?player_id=${playerId}`);
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (!response?.player || scope !== currentScope || String(response.data_scope_id || "") !== scope) return;
    app.clubLegacyLivePlayers.set(playerId, response.player);
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  } catch (_error) {
    // Keep the permanent archive visible when a live player lookup is unavailable.
  } finally {
    app.clubLegacyLiveLoading.delete(playerId);
  }
}

function beginLegacyPlayerNameEdit(uid) {
  const playerId = Number(uid || 0);
  const player = legacyMergedPlayers().find((row) => row.uid === playerId);
  const row = document.querySelector(".legacy-hof-name-row");
  if (!player || !row) return;
  row.innerHTML = `<input class="legacy-hof-name-input" maxlength="40" value="${escapeHtml(player.name)}" placeholder="${uiText("legacy.name.placeholder")}" aria-label="${uiText("legacy.name.input_aria")}"><button type="button" class="legacy-hof-name-save" aria-label="${uiText("legacy.name.save_aria")}" title="${uiText("legacy.name.save_title")}"><i data-lucide="check"></i></button><button type="button" class="legacy-hof-name-cancel" aria-label="${uiText("legacy.name.cancel_aria")}" title="${uiText("legacy.name.cancel_title")}"><i data-lucide="x"></i></button>`;
  const input = row.querySelector("input");
  const cancel = () => {
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  };
  const save = async () => {
    const name = input.value.trim();
    row.querySelectorAll("button, input").forEach((control) => { control.disabled = true; });
    try {
      const result = await request("/api/world-players/name", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({player_id:playerId, name}),
      });
      Object.values(app.clubLegacyPool || {}).forEach((payload) => {
        (payload?.players || []).filter((item) => Number(item.id) === playerId).forEach((item) => {
          item.snapshot = {...(item.snapshot || {}), name:result.name};
        });
      });
      const live = app.clubLegacyLivePlayers.get(playerId);
      if (live) app.clubLegacyLivePlayers.set(playerId, {...live, name:result.name});
      app.clubLegacyRenderSignature = null;
      renderHallOfFame();
      toast(result.custom_name ? uiText("legacy.name.saved") : uiText("legacy.name.restored"));
    } catch (error) {
      toast(error.message || uiText("legacy.name.save_failed"));
      row.querySelectorAll("button, input").forEach((control) => { control.disabled = false; });
      input.focus();
    }
  };
  row.querySelector(".legacy-hof-name-save").addEventListener("click", save);
  row.querySelector(".legacy-hof-name-cancel").addEventListener("click", cancel);
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") save();
    if (event.key === "Escape") cancel();
  });
  renderIcons(row);
  input.focus();
  input.select();
}

function applyClubLegacyStatus(status) {
  if (!status || String(status.data_scope_id || "") !== String(app.state?.data_scope_id || "")) return;
  const previousRevision = Number(app.clubLegacyStatus?.revision || 0);
  app.clubLegacyStatus = {...status};
  if (!status.refreshing && previousRevision !== Number(status.revision || 0)) {
    app.pageDataVersions?.delete("club-legacy");
    if (typeof schedulePageIntentPrewarm === "function") {
      schedulePageIntentPrewarm("hall-of-fame");
    }
  }
  if (app.page === "hall-of-fame") {
    renderHallOfFame();
    if (!status.refreshing && !app.clubLegacyLoading
        && app.clubLegacyConsumedRevision !== Number(status.revision || 0)) {
      loadClubLegacyIndex({force:true});
    }
  }
  if (
    app.page === "club" && app.clubTab === "transfers"
    && !status.refreshing && !app.transferHistoryLoading
    && app.transferHistoryLegacyRevision !== Number(status.revision || 0)
  ) loadTransferHistory({force:true});
}

async function loadClubLegacyIndex({force = false, background = false, includeDetails = null} = {}) {
  if (app.clubLegacyStatus?.refreshing) return app.clubLegacyIndex;
  const loadDetails = includeDetails == null ? !background : Boolean(includeDetails);
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  const requestedVersion = Number(app.state?.data_version || 0);
  const requestedRevision = Number(app.clubLegacyStatus?.revision || 0);
  const requestedResourceVersion = typeof dataResourceVersionKey === "function"
    ? dataResourceVersionKey("club-legacy")
    : `${requestedScope}|${requestedVersion}|${requestedRevision}`;
  if (String(app.clubLegacyScope || "") !== requestedScope) {
    app.clubLegacyIndex = null;
    app.clubLegacyPool = {};
    app.clubLegacyBestTeamKey = "all_time";
    app.clubLegacyBestTeamSelectedSlot = "";
    app.clubLegacySelectedUid = null;
    app.clubLegacyWorldSearch = "";
    app.clubLegacyWorldResults = [];
    app.clubLegacyWorldError = null;
  }
  const cachedClubIds = (app.clubLegacyIndex?.clubs || [])
    .map((club) => Number(club.id)).filter((teamId) => teamId > 0 || teamId === -1);
  const detailsReady = cachedClubIds.every((teamId) => app.clubLegacyPool?.[teamId]);
  if (!force && app.clubLegacyIndex && app.clubLegacyConsumedRevision === requestedRevision
      && (!loadDetails || detailsReady)) return app.clubLegacyIndex;
  const requestSignature = `club-legacy:${requestedResourceVersion}:${loadDetails ? "details" : "index"}`;
  const shareRequest = typeof sharePageDataRequest === "function"
    ? sharePageDataRequest : (_key, runner) => runner();
  const task = shareRequest(requestSignature, async () => {
  const requestKey = ++app.clubLegacyRequestKey;
  const requestCurrent = () => requestKey === app.clubLegacyRequestKey
    && requestedScope === String(app.state?.data_scope_id || output().save_instance_id || "")
    && requestedVersion === Number(app.state?.data_version || 0)
    && (typeof dataResourceVersionKey !== "function"
      || requestedResourceVersion === dataResourceVersionKey("club-legacy"))
    && requestedRevision === Number(app.clubLegacyStatus?.revision || 0)
    && !app.clubLegacyStatus?.refreshing;
  app.clubLegacyLoading = true;
  app.clubLegacyError = null;
  app.clubLegacyRenderSignature = null;
  if (app.page === "hall-of-fame") renderHallOfFame();
  try {
    const result = await request("/api/club-legacy?team_id=0");
    if (!requestCurrent()) return null;
    const clubIds = (result.clubs || []).map((club) => Number(club.id)).filter((teamId) => teamId > 0 || teamId === -1);
    if (!background) void loadTransferHistory({force});
    let payloads = [];
    if (loadDetails && background) {
      for (const teamId of clubIds) {
        payloads.push(await request(`/api/club-legacy?team_id=${teamId}`));
        await waitForDataPrewarmIdle();
      }
    } else if (loadDetails) {
      payloads = await Promise.all(clubIds.map((teamId) => request(`/api/club-legacy?team_id=${teamId}`)));
    }
    if (!requestCurrent()) return null;
    const pool = {};
    payloads.forEach((payload) => {
      const teamId = Number(payload?.club?.id || 0);
      if (teamId) pool[teamId] = payload;
    });
    app.clubLegacyScope = requestedScope;
    app.clubLegacyIndex = result;
    app.clubLegacyPool = pool;
    app.clubLegacyConsumedRevision = requestedRevision;
    app.clubLegacyRevision += 1;
    if (typeof rememberPageDataVersion === "function") rememberPageDataVersion("club-legacy");
    return result;
  } catch (error) {
    if (!requestCurrent()) return null;
    app.clubLegacyError = error.message || uiText("legacy.status.service_unavailable");
    if (!background) toast(error.message || uiText("legacy.status.index_read_failed"));
    return null;
  } finally {
    if (requestKey === app.clubLegacyRequestKey) {
      app.clubLegacyLoading = false;
      if (app.page === "hall-of-fame") renderHallOfFame();
    }
  }
  });
  app.clubLegacyLoadPromise = task;
  try {
    return await task;
  } finally {
    if (app.clubLegacyLoadPromise === task) app.clubLegacyLoadPromise = null;
  }
}

async function refreshHallOfFame() {
  try {
    await request("/api/club/refresh", {
      method:"POST", headers:{"Content-Type":"application/json"}, body:"{}",
    });
    app.clubStatus = {...(app.clubStatus || {}), refreshing:true, error:null};
    renderHallOfFame();
    await loadClub();
  } catch (error) {
    toast(error.message || uiText("legacy.status.refresh_failed"));
  }
}

async function openLegacyMatchMomentDialog(uid) {
  const player = legacyMergedPlayers().find((row) => row.uid === Number(uid));
  const teamId = legacyMomentTeamId(player);
  const dialog = document.querySelector("#legacy-match-moment-dialog");
  if (!player || !teamId || !dialog) return;
  const tagGroupKeys = {attack:"legacy.moment.group_attack", defence:"legacy.moment.group_defence", impact:"legacy.moment.group_impact"};
  const tagKeys = {
    "进球":"legacy.moment.tag.goal", "世界波":"legacy.moment.tag.wonder_goal", "倒钩":"legacy.moment.tag.bicycle_kick",
    "凌空抽射":"legacy.moment.tag.volley", "任意球破门":"legacy.moment.tag.free_kick_goal", "远射破门":"legacy.moment.tag.long_range_goal",
    "头球破门":"legacy.moment.tag.header_goal", "单骑闯关":"legacy.moment.tag.solo_run", "游龙":"legacy.moment.tag.mazy_run",
    "关键防守":"legacy.moment.tag.key_defence", "关键解围":"legacy.moment.tag.clearance", "门线救险":"legacy.moment.tag.goal_line_clearance",
    "关键扑点":"legacy.moment.tag.penalty_save", "关键封堵":"legacy.moment.tag.key_block", "关键扑救":"legacy.moment.tag.key_save",
    "助攻":"legacy.moment.tag.assist", "绝妙助攻":"legacy.moment.tag.brilliant_assist", "制胜助攻":"legacy.moment.tag.winning_assist",
    "关键传球":"legacy.moment.tag.key_pass", "制胜球":"legacy.moment.tag.winning_goal", "扳平球":"legacy.moment.tag.equaliser",
    "逆转进球":"legacy.moment.tag.comeback_goal", "造点":"legacy.moment.tag.won_penalty", "全场最佳":"legacy.moment.tag.player_of_match",
    "首秀":"legacy.moment.tag.debut", "里程碑":"legacy.moment.tag.milestone",
  };
  const tagGroups = [
    ["attack", ["进球", "世界波", "倒钩", "凌空抽射", "任意球破门", "远射破门", "头球破门", "单骑闯关", "游龙"]],
    ["defence", ["关键防守", "关键解围", "门线救险", "关键扑点", "关键封堵", "关键扑救"]],
    ["impact", ["助攻", "绝妙助攻", "制胜助攻", "关键传球", "制胜球", "扳平球", "逆转进球", "造点", "全场最佳", "首秀", "里程碑"]],
  ];
  dialog.innerHTML = `<div class="dialog-head"><div><small>${uiText("legacy.moment.eyebrow")}</small><h2>${uiText("legacy.moment.title")}</h2><p>${escapeHtml(player.name)}</p></div><button class="icon-button" type="button" data-legacy-moment-close aria-label="${uiText("legacy.moment.close")}"><i data-lucide="x"></i></button></div><div class="legacy-moment-dialog-body" aria-busy="true"><div class="legacy-hof-empty-block"><i data-lucide="loader-circle"></i><span>${uiText("legacy.moment.loading")}</span></div></div>`;
  dialog.showModal();
  dialog.querySelector("[data-legacy-moment-close]")?.addEventListener("click", () => dialog.close());
  renderIcons(dialog);
  try {
    const [response, seasonResponse] = await Promise.all([
      request(`/api/team-results?team_id=${teamId}&limit=40`),
      request("/api/results").catch(() => ({season_results:[]})),
    ]);
    const currentFixtures = (seasonResponse.season_results || []).map((row) => ({
      ...row, competition_id: row.competition_id ?? row.competition?.id,
      competition_name: row.competition_name ?? row.competition?.name,
      home: row.home ?? row.home_team, away: row.away ?? row.away_team,
    }));
    const fixtureMap = new Map();
    [...(response.team_results || []), ...currentFixtures].forEach((row) => {
      if (!row?.date || !row.home || !row.away) return;
      const homeId = Number(row.home.id || 0); const awayId = Number(row.away.id || 0);
      if (![homeId, awayId].includes(teamId)) return;
      const key = `${String(row.date).slice(0, 10)}|${row.competition_id || row.competition?.id || 0}|${homeId}|${awayId}`;
      fixtureMap.set(key, row);
    });
    const fixtures = [...fixtureMap.values()].sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 40);
    const options = fixtures.map((fixture, index) => `<option value="${index}">${escapeHtml(`${String(fixture.date).slice(0, 10)} · ${fixture.competition_name || uiText("legacy.moment.fixture_fallback")} · ${fixture.home.name || fixture.home.id} ${fixture.home_goals ?? 0}–${fixture.away_goals ?? 0} ${fixture.away.name || fixture.away.id}`)}</option>`).join("");
    dialog.querySelector(".legacy-moment-dialog-body").innerHTML = fixtures.length
      ? `<form id="legacy-match-moment-form" class="legacy-moment-form"><label><span>${uiText("legacy.moment.select_fixture")}</span><select name="fixture" required>${options}</select></label><fieldset><legend>${uiText("legacy.moment.contribution_legend", {max:5})}</legend><div class="legacy-moment-tag-groups">${tagGroups.map(([group, groupTags]) => `<section><h4>${uiText(tagGroupKeys[group])}</h4><div class="legacy-moment-tags">${groupTags.map((tag) => `<label><input type="checkbox" name="tag" value="${escapeHtml(tag)}"><span>${uiText(tagKeys[tag])}</span></label>`).join("")}</div></section>`).join("")}</div></fieldset><div class="legacy-moment-form-grid"><label><span>${uiText("legacy.moment.minute")}</span><input name="minute" type="number" min="0" max="130" step="1" placeholder="${uiText("legacy.moment.minute_placeholder")}"><small class="legacy-moment-native-hint" data-legacy-native-goal-hint></small></label><label><span>${uiText("legacy.moment.note")}</span><input name="note" type="text" maxlength="240" placeholder="${uiText("legacy.moment.note_placeholder")}"></label></div><footer><button type="button" class="secondary" data-legacy-moment-close>${uiText("legacy.moment.cancel")}</button><button type="submit" class="primary">${uiText("legacy.moment.save")}</button></footer></form>`
      : `<div class="legacy-hof-empty-block"><i data-lucide="calendar-off"></i><span>${uiText("legacy.moment.no_fixtures")}</span><button type="button" class="secondary" data-legacy-moment-close>${uiText("legacy.moment.close")}</button></div>`;
    dialog.querySelectorAll("[data-legacy-moment-close]").forEach((button) => button.addEventListener("click", () => dialog.close()));
    const momentForm = dialog.querySelector("#legacy-match-moment-form");
    const minuteField = momentForm?.elements?.minute;
    const nativeHint = momentForm?.querySelector("[data-legacy-native-goal-hint]");
    const syncNativeGoalHint = () => {
      if (!momentForm || !minuteField || !nativeHint) return;
      const fixture = fixtures[Number(momentForm.elements.fixture?.value || 0)];
      const checked = [...momentForm.querySelectorAll('input[name="tag"]:checked')].map((input) => input.value);
      const events = Array.isArray(fixture?.goal_events) ? fixture.goal_events : [];
      const goals = events.filter((event) => {
        const scorer = event?.scorer || {};
        const rawMinute = event?.time?.minute ?? event?.minute;
        return !event?.own_goal && Number(scorer.id || scorer.player_id || 0) === Number(player.uid)
          && Number.isFinite(Number(rawMinute));
      });
      const lateGoals = goals.filter((event) => Number(event?.time?.minute ?? event?.minute) >= 85);
      if (!checked.includes("进球")) {
        nativeHint.textContent = "";
        if (minuteField.dataset.autofilled === "true") { minuteField.value = ""; delete minuteField.dataset.autofilled; }
        return;
      }
      if (lateGoals.length === 1) {
        const value = Number(lateGoals[0]?.time?.minute ?? lateGoals[0]?.minute);
        if (!minuteField.value || minuteField.dataset.autofilled === "true") { minuteField.value = String(value); minuteField.dataset.autofilled = "true"; }
        nativeHint.textContent = uiText("legacy.moment.native_goal_single", {minute:value});
      } else if (lateGoals.length > 1) {
        nativeHint.textContent = uiText("legacy.moment.native_goal_multiple", {count:lateGoals.length});
      } else {
        nativeHint.textContent = events.length ? uiText("legacy.moment.native_goal_missing") : uiText("legacy.moment.native_goal_verify");
      }
    };
    momentForm?.elements?.fixture?.addEventListener("change", syncNativeGoalHint);
    const syncTagLimit = (event) => {
      const checked = [...(momentForm?.querySelectorAll('input[name="tag"]:checked') || [])];
      if (checked.length > 5 && event?.target) {
        event.target.checked = false;
        toast(uiText("legacy.moment.tag_limit", {max:5}));
      }
      syncNativeGoalHint();
    };
    momentForm?.querySelectorAll('input[name="tag"]').forEach((input) => input.addEventListener("change", syncTagLimit));
    syncNativeGoalHint();
    dialog.querySelector("#legacy-match-moment-form")?.addEventListener("submit", async (event) => {
      event.preventDefault();
      const form = event.currentTarget;
      const fixture = fixtures[Number(form.fixture.value)];
      const selectedTags = [...form.querySelectorAll('input[name="tag"]:checked')].map((input) => input.value);
      if (!fixture || !selectedTags.length) { toast(uiText("legacy.moment.contribution_required")); return; }
      const submit = form.querySelector('button[type="submit"]');
      submit.disabled = true;
      try {
        const payload = await request("/api/club-legacy/match-moment", {
          method:"POST", headers:{"Content-Type":"application/json"},
          body:JSON.stringify({team_id:teamId, player_id:player.uid, moment:{
            game_date:String(fixture.date).slice(0, 10), competition_id:fixture.competition_id,
            competition_name:fixture.competition_name, home:fixture.home, away:fixture.away,
            home_goals:fixture.home_goals, away_goals:fixture.away_goals, tags:selectedTags,
            player_team_id:teamId,
            goal_events:Array.isArray(fixture.goal_events) ? fixture.goal_events : undefined,
            minute:form.minute.value || null, note:form.note.value || "",
          }}),
        });
        if (payload?.club?.id) app.clubLegacyPool = {...app.clubLegacyPool, [Number(payload.club.id)]:payload};
        app.clubLegacyRevision += 1;
        dialog.close();
        toast(uiText("legacy.moment.saved"));
        renderHallOfFame();
      } catch (error) {
        submit.disabled = false;
        toast(error.message || uiText("legacy.moment.save_failed"));
      }
    });
    renderIcons(dialog);
  } catch (error) {
    dialog.querySelector(".legacy-moment-dialog-body").innerHTML = `<div class="legacy-hof-error" role="alert"><i data-lucide="circle-alert"></i><strong>${uiText("legacy.moment.read_failed")}</strong><span>${escapeHtml(error.message || uiText("legacy.moment.read_failed_default"))}</span><button type="button" class="secondary" data-legacy-moment-close>${uiText("legacy.moment.close")}</button></div>`;
    dialog.querySelectorAll("[data-legacy-moment-close]").forEach((button) => button.addEventListener("click", () => dialog.close()));
    renderIcons(dialog);
  }
}

async function updateLegacyPreference(uid, changes) {
  if (legacyPreferenceBusy(uid)) return;
  const player = legacyMergedPlayers().find((row) => row.uid === Number(uid));
  if (!player) return;
  const teamId = Number(player.prefTeamId || 0);
  if (!teamId) return;
  app.clubLegacyPreferenceBusy.add(Number(uid));
  app.clubLegacyRenderSignature = null;
  renderHallOfFame();
  try {
    const payload = await request("/api/club-legacy/preference", {
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({team_id:teamId, player_id:Number(uid), ...changes}),
    });
    if (payload?.club?.id) {
      app.clubLegacyPool = {...app.clubLegacyPool, [Number(payload.club.id)]: payload};
      const indexed = (app.clubLegacyIndex?.clubs || []).find((club) => Number(club.id) === Number(payload.club.id));
      if (indexed) indexed.summary = {...payload.summary};
    }
    app.clubLegacyRevision += 1;
  } catch (error) {
    toast(error.message || uiText("legacy.preference.save_failed"));
  } finally {
    app.clubLegacyPreferenceBusy.delete(Number(uid));
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }
}

function renderHallOfFame() {
  const node = $("#hall-of-fame-content");
  if (!node) return;
  const refreshButton = $("#hall-of-fame-refresh");
  const refreshing = Boolean(app.clubLegacyLoading || app.clubLegacyStatus?.refreshing || app.clubStatus?.refreshing || app.state?.club_status?.refreshing);
  $("#page-hall-of-fame")?.setAttribute("aria-busy", String(refreshing));
  node.setAttribute("aria-busy", String(refreshing));
  if (refreshButton) {
    refreshButton.disabled = refreshing;
    refreshButton.classList.toggle("is-refreshing", refreshing);
    refreshButton.querySelector("span").textContent = refreshing ? uiText("legacy.status.refreshing") : uiText("legacy.status.refresh");
  }
  if (
    app.clubLegacyWorldComposing
    && document.activeElement?.matches?.("[data-legacy-world-search]")
  ) return;
  const signature = JSON.stringify([String(app.clubLegacyScope || ""), app.clubLegacyRevision, app.clubLegacyView, app.clubLegacySearch, app.clubLegacyStatsScope, app.clubLegacyStatsPeriod, app.clubLegacyLeadersScope, app.clubLegacyBestTeamKey, app.clubLegacyBestTeamSelectedSlot, app.clubLegacyBestTeamBusy, Number(app.clubLegacySelectedUid || 0), Boolean(app.showHiddenAttributes), refreshing, app.clubLegacyError, app.clubLegacyStatus?.error, app.clubLegacyWorldSearch, app.clubLegacyWorldLoading, app.clubLegacyWorldError, app.clubLegacyWorldResults, [...app.clubLegacyPreferenceBusy].sort((a, b) => a - b)]);
  if (signature !== app.clubLegacyRenderSignature) {
    const archiveError = app.clubLegacyStatus?.error;
    node.innerHTML = (archiveError ? `<div class="legacy-hof-error" role="alert"><strong>${uiText("legacy.status.update_incomplete")}</strong><span>${escapeHtml(archiveError)}</span><span>${uiText("legacy.status.keep_records")}</span></div>` : "") + renderClubLegacy();
    app.clubLegacyRenderSignature = signature;
    bindClubLegacyControls();
    renderIcons();
  }
}

function bindClubLegacyControls() {
  if (Number(app.clubLegacySelectedUid || 0)) {
    void loadLegacyPlayerLiveProfile(Number(app.clubLegacySelectedUid));
  }
  document.querySelector("[data-legacy-retry]")?.addEventListener("click", () => loadClubLegacyIndex({force:true}));
  document.querySelectorAll("[data-legacy-view]").forEach((button) => button.addEventListener("click", () => {
    app.clubLegacyView = button.dataset.legacyView;
    app.clubLegacySelectedUid = null;
    app.clubLegacyPreferredTeamId = null;
    app.clubLegacyReturnPage = null;
    app.clubLegacyBestTeamSelectedSlot = "";
    renderHallOfFame();
  }));
  document.querySelectorAll("[data-legacy-best-period]").forEach((button) => button.addEventListener("click", () => {
    app.clubLegacyBestTeamKey = String(button.dataset.legacyBestPeriod || "all_time");
    app.clubLegacyBestTeamSelectedSlot = "";
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }));
  document.querySelectorAll("[data-legacy-best-formation]").forEach((button) => button.addEventListener("click", () => {
    const lineup = legacyBestTeamLineup();
    const nextFormation = String(button.dataset.legacyBestFormation || "4231");
    if (nextFormation === lineup.formation) return;
    saveLegacyBestTeam(nextFormation, legacyBestTeamRemapAssignments(lineup, nextFormation), "阵型已保存");
  }));
  document.querySelector("[data-legacy-best-recommend]")?.addEventListener("click", () => recommendLegacyBestTeam());
  document.querySelectorAll("[data-legacy-best-slot]").forEach((button) => button.addEventListener("click", () => {
    app.clubLegacyBestTeamSelectedSlot = String(button.dataset.legacyBestSlot || "");
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }));
  document.querySelectorAll("[data-legacy-best-player]").forEach((button) => button.addEventListener("click", () => {
    if (button.disabled) return;
    assignLegacyBestTeamPlayer(app.clubLegacyBestTeamSelectedSlot, Number(button.dataset.legacyBestPlayer));
  }));
  document.querySelectorAll("[data-legacy-best-remove]").forEach((button) => button.addEventListener("click", () => {
    assignLegacyBestTeamPlayer(String(button.dataset.legacyBestRemove || ""), 0);
  }));
  document.querySelectorAll("[data-legacy-stats-scope]").forEach((button) => button.addEventListener("click", () => {
    app.clubLegacyStatsScope = button.dataset.legacyStatsScope === "career" ? "career" : "season";
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }));
  document.querySelectorAll("[data-legacy-stats-period]").forEach((button) => button.addEventListener("click", () => {
    app.clubLegacyStatsPeriod = String(button.dataset.legacyStatsPeriod || "all_time");
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }));
  document.querySelectorAll("[data-legacy-leaders-scope]").forEach((button) => button.addEventListener("click", () => {
    app.clubLegacyLeadersScope = ["all", "league", "cup"].includes(button.dataset.legacyLeadersScope) ? button.dataset.legacyLeadersScope : "all";
    app.clubLegacyRenderSignature = null;
    renderHallOfFame();
  }));
  document.querySelector("[data-legacy-search]")?.addEventListener("input", (event) => {
    app.clubLegacySearch = event.target.value;
    renderHallOfFame();
    const input = document.querySelector("[data-legacy-search]");
    input?.focus();
    if (input) input.setSelectionRange(input.value.length, input.value.length);
  });
  const worldSearchInput = document.querySelector("[data-legacy-world-search]");
  worldSearchInput?.addEventListener("compositionstart", () => {
    app.clubLegacyWorldComposing = true;
    if (app.clubLegacyWorldSearchTimer) clearTimeout(app.clubLegacyWorldSearchTimer);
    app.clubLegacyWorldSearchTimer = null;
  });
  worldSearchInput?.addEventListener("input", (event) => {
    app.clubLegacyWorldSearch = event.target.value;
    if (event.isComposing || app.clubLegacyWorldComposing) return;
    scheduleLegacyWorldPlayerSearch(app.clubLegacyWorldSearch);
  });
  worldSearchInput?.addEventListener("compositionend", (event) => {
    app.clubLegacyWorldComposing = false;
    app.clubLegacyWorldSearch = event.target.value;
    scheduleLegacyWorldPlayerSearch(app.clubLegacyWorldSearch);
  });
  document.querySelectorAll("[data-legacy-world-follow]").forEach((button) => button.addEventListener("click", () => {
    followLegacyWorldPlayer(Number(button.dataset.legacyWorldFollow));
  }));
  document.querySelectorAll("[data-legacy-select]").forEach((target) => target.addEventListener("click", (event) => {
    if (event.target.closest("[data-legacy-favorite]")) return;
    app.clubLegacyPreferredTeamId = null;
    app.clubLegacyReturnPage = null;
    app.clubLegacySelectedUid = Number(target.dataset.legacySelect);
    app.clubLegacyReturnUid = app.clubLegacySelectedUid;
    renderHallOfFame();
    void loadLegacyPlayerLiveProfile(app.clubLegacySelectedUid, {force:true});
  }));
  document.querySelectorAll(".legacy-hof-player-card[data-legacy-select]").forEach((card) => card.addEventListener("keydown", (event) => {
    if ((event.key === "Enter" || event.key === " ") && !event.target.closest("button")) {
      event.preventDefault();
      card.click();
    }
  }));
  document.querySelector("[data-legacy-back]")?.addEventListener("click", () => {
    const returnUid = Number(app.clubLegacyReturnUid || app.clubLegacySelectedUid || 0);
    if (app.clubLegacyReturnPage === "club-transfers") {
      app.clubLegacySelectedUid = null;
      app.clubLegacyPreferredTeamId = null;
      app.clubLegacyReturnPage = null;
      app.clubTab = "transfers";
      showPage("club");
      app.clubRenderSignature = null;
      renderClub();
      requestAnimationFrame(() => document.querySelector(`[data-transfer-history-player="${returnUid}"]`)?.focus());
      return;
    }
    app.clubLegacySelectedUid = null;
    app.clubLegacyPreferredTeamId = null;
    renderHallOfFame();
    document.querySelector(`[data-legacy-select="${returnUid}"]`)?.focus();
  });
  document.querySelectorAll("[data-legacy-favorite]").forEach((button) => {
    button.addEventListener("click", () => {
      const player = legacyMergedPlayers().find((row) => row.uid === Number(button.dataset.legacyFavorite));
      if (player) updateLegacyPreference(player.uid, {favorite:!player.favorite});
    });
  });
  document.querySelector("[data-legacy-name-edit]")?.addEventListener("click", (event) => {
    beginLegacyPlayerNameEdit(Number(event.currentTarget.dataset.legacyNameEdit));
  });
  document.querySelectorAll("[data-legacy-induct]").forEach((button) => button.addEventListener("click", () => {
    const player = legacyMergedPlayers().find((row) => row.uid === Number(button.dataset.legacyInduct));
    if (player) updateLegacyPreference(player.uid, {inducted:!player.inducted});
  }));
  document.querySelectorAll("[data-legacy-tier]").forEach((select) => select.addEventListener("change", (event) => {
    updateLegacyPreference(Number(event.target.dataset.legacyTier), {tier:event.target.value});
  }));
  document.querySelectorAll("[data-legacy-record-moment]").forEach((button) => button.addEventListener("click", () => {
    openLegacyMatchMomentDialog(Number(button.dataset.legacyRecordMoment));
  }));
  document.querySelector("[data-legacy-record-save]")?.addEventListener("click", (event) => {
    const uid = Number(event.currentTarget.dataset.legacyRecordSave);
    const readNumber = (key, integer = true) => {
      const raw = document.querySelector(`[data-legacy-record="${key}"]`)?.value?.trim() || "";
      if (!raw) return null;
      return integer ? Number.parseInt(raw, 10) : Number(raw);
    };
    const textValue = (key) => document.querySelector(`[data-legacy-record="${key}"]`)?.value || "";
    const note = document.querySelector(`[data-legacy-note="${uid}"]`)?.value || "";
    updateLegacyPreference(uid, {
      note,
      career_record:{
        appearances:readNumber("appearances"), goals:readNumber("goals"),
        assists:readNumber("assists"), average_rating:readNumber("average_rating", false),
        transfer_in_fee:readNumber("transfer_in_fee"), transfer_out_fee:readNumber("transfer_out_fee"),
        honors_text:textValue("honors_text"), post_departure_text:textValue("post_departure_text"),
      },
    });
  });
}


function transferHistoryMoney(value, feeStatus = "") {
  if (feeStatus === "loan") return uiText("owned.detail.loan");
  if (feeStatus === "free") return uiText("owned.detail.free_transfer");
  return value === null || value === undefined ? uiText("world.not_read") : formatPounds(Number(value));
}

function transferHistoryRows() {
  const query = String(app.transferHistorySearch || "").trim().toLocaleLowerCase();
  const teamId = Number(app.transferHistoryClubId || 0);
  const direction = app.transferHistoryDirection === "out" ? "out" : "in";
  const year = String(app.transferHistoryYear || "all");
  return (app.transferHistory?.transfers || []).filter((row) => {
    if (row.direction !== direction) return false;
    if (teamId > 0 && Number(row.team_id || 0) !== teamId) return false;
    if (year === "unknown" && row.year) return false;
    if (year !== "all" && year !== "unknown" && String(row.year || "") !== year) return false;
    if (!query) return true;
    return `${row.player_name || ""} ${row.counterparty_name || ""} ${row.team_name || ""}`.toLocaleLowerCase().includes(query);
  });
}

function renderTransferHistory() {
  if (app.transferHistoryLoading && !app.transferHistory) {
    return `<div class="transfer-history-state" role="status" aria-live="polite"><i data-lucide="loader-circle"></i><strong>${uiText("world.transfer.loading")}</strong><span>${uiText("world.transfer.loading_note")}</span></div>`;
  }
  if (app.transferHistoryError && !app.transferHistory) {
    return `<div class="transfer-history-state error" role="alert"><i data-lucide="circle-alert"></i><strong>${uiText("world.transfer.read_failed")}</strong><span>${escapeHtml(app.transferHistoryError)}</span><button type="button" data-transfer-history-retry>${uiText("world.transfer.retry")}</button></div>`;
  }
  if (!app.transferHistory && !app.transferHistoryLoading) {
    void loadTransferHistory();
    return `<div class="transfer-history-state" role="status"><i data-lucide="loader-circle"></i><strong>${uiText("world.transfer.loading")}</strong></div>`;
  }
  const data = app.transferHistory || {};
  const rows = transferHistoryRows();
  const direction = app.transferHistoryDirection === "out" ? "out" : "in";
  const directionLabel = uiText(direction === "out" ? "world.transfer.direction_out" : "world.transfer.direction_in");
  const allTransfers = data.transfers || [];
  const years = Array.from(new Set([
    ...(data.years || []),
    ...allTransfers.map((row) => row.year).filter(Boolean),
  ].map(String))).sort((left, right) => right.localeCompare(left));
  const hasUnknownYear = allTransfers.some((row) => !row.year);
  const yearOptions = years.map((year) => `<option value="${escapeHtml(year)}" ${String(app.transferHistoryYear) === year ? "selected" : ""}>${uiText("world.transfer.year_option", {year:escapeHtml(year)})}</option>`).join("");
  const unknownYearOption = hasUnknownYear ? `<option value="unknown" ${app.transferHistoryYear === "unknown" ? "selected" : ""}>${uiText("world.transfer.year_unread")}</option>` : "";
  const clubOptions = (data.clubs || []).map((club) => `<option value="${Number(club.id || 0)}" ${Number(app.transferHistoryClubId || 0) === Number(club.id || 0) ? "selected" : ""}>${uiText("world.transfer.club_option", {name:escapeHtml(club.name || String(club.id)), count:Number(club.players || 0)})}</option>`).join("");
  const body = rows.length ? rows.map((row) => {
    const counterparty = row.counterparty_kind === "free_agent" ? uiText("legacy.free_agent") : (row.counterparty_name || uiText("world.not_read"));
    return `<tr data-transfer-history-row="${escapeHtml(row.id || "")}"><td><strong>${escapeHtml(row.date || uiText("world.not_read"))}</strong></td><td><button type="button" class="transfer-history-player" data-transfer-history-player="${Number(row.player_id || 0)}" data-transfer-history-team="${Number(row.team_id || 0)}"><strong>${escapeHtml(row.player_name || uiText("world.transfer.player_fallback", {id:Number(row.player_id || 0)}))}</strong></button></td><td>${escapeHtml(counterparty)}</td><td><strong>${escapeHtml(transferHistoryMoney(row.fee, row.fee_status))}</strong></td></tr>`;
  }).join("") : `<tr><td colspan="4" class="transfer-history-empty">${uiText("world.transfer.empty", {direction:directionLabel})}</td></tr>`;
  return `<section class="transfer-history" aria-busy="${Boolean(app.transferHistoryLoading)}">
    <header class="transfer-history-header"><div><small>${uiText("world.transfer.eyebrow")}</small><h2>${uiText("world.transfer.title")}</h2></div></header>
    <nav class="transfer-history-directions" aria-label="${uiText("world.transfer.direction_aria")}"><button type="button" data-transfer-history-direction="in" class="${direction === "in" ? "active" : ""}" aria-pressed="${direction === "in"}">${uiText("world.transfer.direction_in")} <span>${Number(data.summary?.incoming || 0)}</span></button><button type="button" data-transfer-history-direction="out" class="${direction === "out" ? "active" : ""}" aria-pressed="${direction === "out"}">${uiText("world.transfer.direction_out")} <span>${Number(data.summary?.outgoing || 0)}</span></button></nav>
    <div class="transfer-history-tools"><label><span>${uiText("world.transfer.year_label")}</span><select data-transfer-history-year><option value="all">${uiText("world.transfer.all_years")}</option>${yearOptions}${unknownYearOption}</select></label><label><span>${uiText("world.transfer.club_label")}</span><select data-transfer-history-club><option value="0">${uiText("world.transfer.all_clubs")}</option>${clubOptions}</select></label><label class="transfer-history-search"><span>${uiText("world.transfer.player_search")}</span><input type="search" data-transfer-history-search value="${escapeHtml(app.transferHistorySearch || "")}" placeholder="${uiText("world.transfer.player_search_placeholder")}"></label><button type="button" data-transfer-history-refresh ${app.transferHistoryLoading ? "disabled" : ""}><i data-lucide="refresh-cw"></i><span>${app.transferHistoryLoading ? uiText("world.transfer.refreshing") : uiText("world.transfer.refresh")}</span></button></div>
    <div class="transfer-history-table-wrap"><table class="transfer-history-table"><thead><tr><th scope="col">${uiText("world.transfer.date", {direction:directionLabel})}</th><th scope="col">${uiText("world.transfer.player")}</th><th scope="col">${uiText(direction === "in" ? "world.transfer.from_club" : "world.transfer.to_club")}</th><th scope="col">${uiText("world.transfer.fee", {direction:directionLabel})}</th></tr></thead><tbody>${body}</tbody></table></div>
  </section>`;
}

function bindTransferHistoryControls(node) {
  node.querySelector("[data-transfer-history-retry]")?.addEventListener("click", () => loadTransferHistory({force:true}));
  node.querySelector("[data-transfer-history-refresh]")?.addEventListener("click", () => loadTransferHistory({force:true}));
  node.querySelectorAll("[data-transfer-history-direction]").forEach((button) => button.addEventListener("click", () => {
    app.transferHistoryDirection = button.dataset.transferHistoryDirection === "out" ? "out" : "in";
    app.clubRenderSignature = null;
    renderClub();
  }));
  node.querySelector("[data-transfer-history-year]")?.addEventListener("change", (event) => {
    app.transferHistoryYear = event.target.value || "all";
    app.clubRenderSignature = null;
    renderClub();
  });
  node.querySelector("[data-transfer-history-club]")?.addEventListener("change", (event) => {
    app.transferHistoryClubId = Number(event.target.value || 0);
    app.clubRenderSignature = null;
    renderClub();
  });
  node.querySelector("[data-transfer-history-search]")?.addEventListener("input", (event) => {
    app.transferHistorySearch = event.target.value;
    app.clubRenderSignature = null;
    renderClub();
    const input = document.querySelector("[data-transfer-history-search]");
    input?.focus();
    if (input) input.setSelectionRange(input.value.length, input.value.length);
  });
  node.querySelectorAll("[data-transfer-history-player]").forEach((button) => button.addEventListener("click", () => {
    openTransferHistoryPlayer(
      Number(button.dataset.transferHistoryPlayer),
      Number(button.dataset.transferHistoryTeam),
    );
  }));
}

async function loadTransferHistory({force = false} = {}) {
  const requestedScope = String(app.state?.data_scope_id || output().save_instance_id || "");
  if (!requestedScope) return null;
  if (app.transferHistoryLoading) return app.transferHistory;
  if (!force && app.transferHistory && String(app.transferHistoryScope || "") === requestedScope) {
    return app.transferHistory;
  }
  const requestKey = ++app.transferHistoryRequestKey;
  app.transferHistoryLoading = true;
  app.transferHistoryError = null;
  app.clubRenderSignature = null;
  if (app.page === "club" && app.clubTab === "transfers") renderClub();
  try {
    const response = await request("/api/club/transfer-history");
    const currentScope = String(app.state?.data_scope_id || output().save_instance_id || "");
    if (requestKey !== app.transferHistoryRequestKey || requestedScope !== currentScope || String(response.data_scope_id || "") !== requestedScope) return null;
    app.transferHistory = response;
    app.transferHistoryScope = requestedScope;
    app.transferHistoryLegacyRevision = Number(app.clubLegacyStatus?.revision || 0);
    const validClubIds = new Set((response.clubs || []).map((club) => Number(club.id || 0)));
    if (app.transferHistoryClubId && !validClubIds.has(Number(app.transferHistoryClubId))) app.transferHistoryClubId = 0;
    const validYears = new Set(["all", "unknown", ...(response.years || []).map(String)]);
    if (!validYears.has(String(app.transferHistoryYear || "all"))) app.transferHistoryYear = "all";
    return response;
  } catch (error) {
    if (requestKey === app.transferHistoryRequestKey) app.transferHistoryError = error.message || uiText("world.transfer.read_failed");
    return null;
  } finally {
    if (requestKey === app.transferHistoryRequestKey) {
      app.transferHistoryLoading = false;
      app.clubRenderSignature = null;
      if (app.page === "club" && app.clubTab === "transfers") renderClub();
      if (app.page === "hall-of-fame") {
        app.clubLegacyRenderSignature = null;
        renderHallOfFame();
      }
    }
  }
}

async function openTransferHistoryPlayer(playerId, teamId) {
  if (!playerId || app.clubLegacyStatus?.refreshing) {
    toast(app.clubLegacyStatus?.refreshing ? uiText("world.transfer.player_busy") : uiText("world.transfer.player_invalid"));
    return;
  }
  if (!Object.keys(app.clubLegacyPool || {}).length) await loadClubLegacyIndex();
  const player = legacyMergedPlayers().find((row) => row.uid === Number(playerId));
  if (!player) {
    toast(uiText("world.transfer.player_not_found"));
    return;
  }
  app.clubLegacyPreferredTeamId = Number(teamId || 0) || null;
  app.clubLegacyReturnPage = "club-transfers";
  app.clubLegacySelectedUid = Number(playerId);
  app.clubLegacyReturnUid = Number(playerId);
  app.clubLegacyRenderSignature = null;
  showPage("hall-of-fame");
  renderHallOfFame();
}

function clubRenderStateSignature(index, status, club) {
  return JSON.stringify([
    String(app.state?.data_scope_id || output().save_instance_id || ""),
    index.version, Number(club?.team?.id || 0), Number(app.clubTeamId || 0),
    Number(app.clubSquadTeamId || 0), app.clubTab, Boolean(app.showHiddenAttributes),
    moneyRenderSignature(), app.state?.economy?.salary || {},
    Boolean(status.refreshing), Boolean(status.ready), String(status.error || ""),
    refreshBlocksPublishedState(),
  ]);
}

function syncClubPageStatus(status, club) {
  const selectedTeam = managedTeams().find((team) => Number(team.id) === Number(app.clubTeamId)) || null;
  const teamTypeLabel = selectedTeam?.team_type === "national"
    ? uiText("world.club.my_national_team") : uiText("world.club.my_club");
  const busy = Boolean(status.refreshing || refreshBlocksPublishedState());
  $("#club-title").textContent = club?.team?.name ? `${teamTypeLabel} · ${club.team.name}` : uiText("world.club.title");
  const page = $("#page-club");
  const node = $("#club-content");
  page?.setAttribute("aria-busy", String(busy));
  node?.setAttribute("aria-busy", String(busy));
  const statusNode = $("#club-sync-status");
  if (statusNode) {
    statusNode.hidden = !busy;
    const label = statusNode.querySelector("span");
    if (label) label.textContent = status.refreshing
      ? uiText("world.club.reading_progress", {progress:Math.round(Number(status.progress || 0))})
      : uiText("world.club.syncing_save");
  }
  const refreshButton = $("#club-refresh-button");
  if (refreshButton) {
    refreshButton.disabled = busy;
    refreshButton.classList.toggle("is-refreshing", busy);
    const label = refreshButton.querySelector("span");
    if (label) label.textContent = status.refreshing
      ? uiText("world.club.refreshing_button") : uiText("world.club.refresh_button");
  }
  app.clubProgress = status.refreshing
    ? Math.max(0, Math.min(100, Number(status.progress || 0)))
    : status.ready ? 100 : 0;
  const progressLabel = node?.querySelector("[data-club-progress-label]");
  const progressValue = node?.querySelector("[data-club-progress-value]");
  const progressFill = node?.querySelector("[data-club-progress-fill]");
  const progressNote = node?.querySelector("[data-club-progress-note]");
  if (progressLabel) progressLabel.textContent = uiText("world.club.scan_progress");
  if (progressValue) progressValue.textContent = `${Math.round(app.clubProgress)}%`;
  if (progressFill) progressFill.style.width = `${Math.round(app.clubProgress)}%`;
  const waitingForBackground = status.refreshing && Number(status.progress || 0) === 1;
  if (progressNote) progressNote.textContent = waitingForBackground
    ? uiText("world.club.progress_wait_note") : uiText("world.club.progress_memory_note");
}

function renderClub() {
  const index = clubDataIndex();
  const club = index.profilesByTeamId.get(Number(app.clubTeamId || 0)) || app.club;
  app.club = club || null;
  const liveStatus = app.state?.club_status || {};
  const status = app.clubStatus || liveStatus;
  syncClubPageStatus(status, club);
  renderClubTeamNav();
  document.querySelectorAll("[data-club-tab]").forEach((button) => {
    const selected = button.dataset.clubTab === app.clubTab;
    button.classList.toggle("active", selected);
    button.setAttribute("aria-selected", String(selected));
  });
  const node = $("#club-content");
  if (!status.refreshing) {
    if (app.clubProgressTimer) { clearInterval(app.clubProgressTimer); app.clubProgressTimer = null; }
    app.clubProgressStartedAt = null;
  }
  if (club && app.clubTab === "players") {
    const selectedSquad = selectedClubSquad(club, app.clubSquadTeamId);
    app.clubSquadTeamId = Number(selectedSquad?.team_id || 0) || null;
  }
  const signature = clubRenderStateSignature(index, status, club);
  if (app.clubRenderSignature === signature && node?.childElementCount) return;
  app.clubRenderSignature = signature;
  const waitingForBackground = status.refreshing && Number(status.progress || 0) === 1;
  const progressPanel = status.refreshing ? `<section class="club-scan-progress" role="status" aria-live="polite"><div class="club-scan-progress-head"><strong data-club-progress-label>${uiText("world.club.scan_progress")}</strong><b data-club-progress-value>${Math.round(app.clubProgress)}%</b></div><div class="club-scan-progress-track" aria-hidden="true"><span data-club-progress-fill style="width:${Math.round(app.clubProgress)}%"></span></div><p data-club-progress-note>${waitingForBackground ? uiText("world.club.progress_wait_note") : uiText("world.club.progress_memory_note")}</p></section>` : "";
  if (app.clubTab === "transfers") {
    node.innerHTML = `${progressPanel}${renderTransferHistory()}`;
    bindTransferHistoryControls(node);
    syncClubPageStatus(status, club);
    renderIcons(node);
    return;
  }
  if (!club) { node.innerHTML = status.refreshing ? progressPanel : `<div class="empty-feature">${uiText("world.club.empty_no_profile")}</div>`; syncClubPageStatus(status, club); renderIcons(); return; }
  if (app.clubTab === "players") {
    const groups = [
      ["forwards", "world.club.players.forwards"], ["midfielders", "world.club.players.midfielders"],
      ["defenders", "world.club.players.defenders"], ["goalkeepers", "world.club.players.goalkeepers"],
    ];
    const squads = clubProfileSquads(club);
    const selectedSquad = selectedClubSquad(club, app.clubSquadTeamId);
    app.clubSquadTeamId = Number(selectedSquad?.team_id || 0) || null;
    const profileView = index.profileViewsByTeamId.get(Number(club.team?.id || 0));
    const selectedView = profileView?.squadsByTeamId.get(Number(app.clubSquadTeamId || 0));
    const playerGroups = selectedView?.playerGroups || {forwards:[],midfielders:[],defenders:[],goalkeepers:[]};
    if (!app.clubGroupState) app.clubGroupState = {};
    node.innerHTML = `${String(club.team?.team_type || "club") === "club" ? clubSquadTabs(squads, app.clubSquadTeamId, "data-club-squad") : ""}<div class="player-groups">${groups.map(([key, labelKey]) => {
      const players = playerGroups[key];
      const stateKey = `player:${Number(app.clubSquadTeamId || club.team?.id || 0)}:${key}`;
      if (app.clubGroupState[stateKey] === undefined) app.clubGroupState[stateKey] = true;
      const expanded = app.clubGroupState[stateKey];
      const body = expanded
        ? `<div class="people-card-grid player-card-grid">${players.map(renderPlayerCard).join("") || `<div class="empty-position-group">${uiText("world.club.players.empty")}</div>`}</div>`
        : "";
      return `<section class="player-group"><header class="activity-roster-group main-group" data-club-group="${escapeHtml(stateKey)}" aria-expanded="${expanded}"><span>${uiText(labelKey)} (${players.length})</span><i data-lucide="${expanded ? "chevron-down" : "chevron-right"}"></i></header>${body}</section>`;
    }).join("")}</div>`;
  } else if (app.clubTab === "staff") {
    const staffRows = club.staff || [];
    const renderStaffCard = (staff) => {
      const chairmanAttributeKeys = {
        business:"world.club.staff.attribute.business",
        interference:"world.club.staff.attribute.interference",
        patience:"world.club.staff.attribute.patience",
        resources:"world.club.staff.attribute.resources",
      };
      const abilities = {...(staff.abilities || {})};
      Object.entries(staff.chairman_attributes || {}).forEach(([key,value]) => {
        const labelKey = chairmanAttributeKeys[key];
        if (labelKey && value != null) abilities[uiText(labelKey)] = value;
      });
      const pairs = Object.entries(abilities);
      const rawKeyNames = staffKeyAttributes(staff);
      const keyNames = new Set([...rawKeyNames, ...rawKeyNames.map(uiLegacy)]);
      const keyPairs = pairs.filter(([name]) => keyNames.has(name));
      const keyAbilities = keyPairs.map(([name,value]) => {
        const displayName = uiLegacy(name) || uiText("world.not_read");
        return `<span class="staff-key-attr" title="${escapeHtml(displayName)} ${value}"><b>${escapeHtml(displayName)}</b><i>${value}</i></span>`;
      }).join("");
      const hasManagerRelation = staff.manager_relation_reason != null
        || Number(staff.manager_intimacy || 0) !== 0
        || Number(staff.manager_relation_permanence) === 79;
      const relationText = hasManagerRelation
        ? managerRelationshipText(staff,true)
        : `0 · ${uiText(staffJobCategory(staff) === STAFF_JOB_CATEGORY_GROUPS[0].label ? "world.club.staff.leader" : "world.club.staff.colleague")}`;
      const staffName = staff.name || uiText("world.club.staff.role_fallback");
      return `<button type="button" class="person-card staff-card" data-staff-detail="${staff.id}" aria-label="${uiText("world.club.staff.aria", {staff:escapeHtml(staffName)})}"><div class="staff-monogram">${escapeHtml(String(staff.name || "?").slice(0,1))}</div><div class="person-card-main"><h3>${escapeHtml(staff.name)}</h3><strong>${escapeHtml(staff.role || uiText("world.club.staff.role_fallback"))}<span class="staff-card-relation"> · ${escapeHtml(relationText)}</span></strong></div><div class="staff-abilities">${keyAbilities || `<span class="staff-ability-empty">${uiText("world.club.staff.attributes_empty")}</span>`}</div><div class="staff-contract"><span>${uiText("world.club.staff.weekly_wage", {amount:formatPounds(staff.wage_display)})}</span><small>${uiText("world.club.staff.expires", {date:escapeHtml(staff.contract_expiry_date || uiText("world.not_read"))})}</small></div></button>`;
    };
    if (!app.clubGroupState) app.clubGroupState = {};
    const groups = [...STAFF_JOB_CATEGORY_GROUPS.map((group) => group.label), staffJobCategory({})];
    node.innerHTML = groups.map((label) => {
      const rows = staffRows.filter((staff) => staffJobCategory(staff) === label).sort(staffSortInCategory);
      if (!rows.length) return "";
      const stateKey = `staff:${label}`;
      if (app.clubGroupState[stateKey] === undefined) app.clubGroupState[stateKey] = true;
      const expanded = app.clubGroupState[stateKey];
      return `<section class="player-group staff-group"><header class="activity-roster-group main-group" data-club-group="${escapeHtml(stateKey)}" aria-expanded="${expanded}"><span>${escapeHtml(relationshipStaffCategoryText(label))} (${rows.length})</span><i data-lucide="${expanded ? "chevron-down" : "chevron-right"}"></i></header>${expanded ? `<div class="people-card-grid">${rows.map(renderStaffCard).join("")}</div>` : ""}</section>`;
    }).join("") || `<div class="empty-feature">${uiText("world.club.staff.empty")}</div>`;
  } else {
  const c = club.contract;
    const salary = app.state?.economy?.salary || {};
    const salaryTaxRate = `${Math.round(Number(salary.tax_rate ?? 0.30) * 100)}%`;
    const salaryTransfer = `<div class="salary-transfer-setting"><strong>${uiText("world.club.contract.salary_policy")}</strong><div class="salary-payday"><span>${uiText("world.club.contract.salary_breakdown", {gross:formatPounds(salary.gross_weekly || 0), rate:salaryTaxRate, net:formatPounds(salary.next_payday_amount || 0)})}</span><strong>${uiText("world.club.contract.next_payday", {date:escapeHtml(salary.next_payday || uiText("world.not_read"))})}</strong></div></div>`;
    const managerRecord = club.manager_record?.total;
    const recordPanel = managerRecord ? `<section class="contract-manager-record"><header><strong>${uiText("world.club.record.title")}</strong><span>${uiText("world.club.record.matches", {count:Number(managerRecord.played || 0)})}</span></header><div><span class="record-win"><small>${uiText("world.club.record.wins")}</small><b>${Number(managerRecord.wins || 0)}</b></span><span class="record-draw"><small>${uiText("world.club.record.draws")}</small><b>${Number(managerRecord.draws || 0)}</b></span><span class="record-loss"><small>${uiText("world.club.record.losses")}</small><b>${Number(managerRecord.losses || 0)}</b></span><span class="record-rate"><small>${uiText("world.club.record.win_rate")}</small><b>${Number(managerRecord.win_rate || 0).toFixed(1)}%</b></span></div></section>` : "";
    node.innerHTML = c ? `<div class="contract-layout"><article class="contract-card"><h2>${uiText("world.club.contract.title")}</h2><dl class="contract-facts"><div><dt>${uiText("world.club.contract.team")}</dt><dd>${escapeHtml(club.team.name)}</dd></div><div><dt>${uiText("world.club.contract.reputation")}</dt><dd>${club.team.reputation != null ? `${Number(club.team.reputation)} / 10000` : uiText("world.not_read")}</dd></div><div><dt>${uiText("world.club.contract.type")}</dt><dd>${escapeHtml(c.contract_type)}</dd></div><div><dt>${uiText("world.club.contract.start_date")}</dt><dd>${escapeHtml(c.start_date || "-")}</dd></div><div><dt>${uiText("world.club.contract.expiry_date")}</dt><dd>${escapeHtml(c.expiry_date || "-")}</dd></div></dl>${recordPanel}</article><article class="contract-card"><h2>${uiText("world.club.contract.salary_title")}</h2><span>${uiText("world.club.contract.salary_weekly")}</span><div class="salary-amount">${formatPounds(c.gross_weekly_display)}</div>${salaryTransfer}</article></div>` : `<div class="empty-feature">${uiText("world.club.contract.no_valid")}</div>`;
  }
  if (progressPanel) node.insertAdjacentHTML("afterbegin", progressPanel);
  node.querySelectorAll("[data-club-group]").forEach((header) => header.addEventListener("click", () => {
    const key = String(header.dataset.clubGroup || "");
    app.clubGroupState[key] = !app.clubGroupState[key];
    app.clubRenderSignature = null;
    renderClub();
  }));
  node.querySelectorAll("[data-club-squad]").forEach((button) => button.addEventListener("click", () => {
    app.clubSquadTeamId = Number(button.dataset.clubSquad);
    renderClub();
  }));
  document.querySelectorAll("[data-player-position-cycle]").forEach((badge) => {
    const cycle = (event) => {
      event.preventDefault();
      event.stopPropagation();
      cyclePlayerCardPosition(Number(badge.dataset.playerPositionCycle));
    };
    badge.addEventListener("click", cycle);
    badge.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") cycle(event);
    });
  });
  document.querySelectorAll("[data-player-detail]").forEach((card) => {
    const open = () => openClubDetail(
      "player", Number(card.dataset.playerDetail),
      {players:clubProfileSquadPlayers(club)},
    );
    card.addEventListener("click", open);
    card.addEventListener("keydown", (event) => {
      if (event.target === card && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        open();
      }
    });
  });
  document.querySelectorAll("[data-staff-detail]").forEach((button) => button.addEventListener("click", () => openClubDetail("staff", Number(button.dataset.staffDetail))));
  document.querySelectorAll("[data-salary-schedule]").forEach((checkbox) => checkbox.addEventListener("change", () => updateSalarySchedule(checkbox)));
  syncClubPageStatus(status, club);
  renderIcons();
}

async function updateSalarySchedule(checkbox) {
  const schedule = checkbox.checked ? checkbox.dataset.salarySchedule : null;
  document.querySelectorAll("[data-salary-schedule]").forEach((input) => { input.disabled = true; });
  try {
    const result = await request("/api/salary/schedule", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({schedule})});
    app.state.economy.salary = result;
    renderClub();
    toast(schedule ? uiText(schedule === "weekly" ? "economy.salary.schedule_weekly" : "economy.salary.schedule_monthly") : uiText("economy.salary.stopped"));
  } catch (error) {
    toast(error.message || uiText("economy.salary.save_failed"));
    renderClub();
  }
}

