function syncWorldPlayerEditorBusy() {
  const dialog = $("#world-player-editor-dialog");
  const form = $("#world-player-editor-form");
  const content = $("#world-player-editor-content");
  const status = $("#world-player-editor-status");
  const busy = Boolean(app.worldPlayerEditorBusy);
  [dialog, form, content].forEach((node) => node?.setAttribute("aria-busy", String(busy)));
  if (status) {
    status.hidden = !busy;
    status.querySelector("span").textContent = busy
      ? app.worldPlayerEditorBusyLabel || uiText("world.editor.busy_default")
      : "";
  }
  dialog?.querySelectorAll("button,input,select").forEach((control) => {
    if (busy) {
      if (!Object.hasOwn(control.dataset, "worldPlayerEditorWasDisabled")) {
        control.dataset.worldPlayerEditorWasDisabled = String(control.disabled);
      }
      control.disabled = true;
      return;
    }
    if (!Object.hasOwn(control.dataset, "worldPlayerEditorWasDisabled")) return;
    control.disabled = control.dataset.worldPlayerEditorWasDisabled === "true";
    delete control.dataset.worldPlayerEditorWasDisabled;
  });
}

async function runWorldPlayerEditorAction(label, action) {
  if (app.worldPlayerEditorBusy) return null;
  app.worldPlayerEditorBusy = true;
  app.worldPlayerEditorBusyLabel = label;
  syncWorldPlayerEditorBusy();
  try {
    return await action();
  } finally {
    app.worldPlayerEditorBusy = false;
    app.worldPlayerEditorBusyLabel = "";
    syncWorldPlayerEditorBusy();
  }
}

function applyWorldPlayerEditorResponse(response, options = {}) {
  const updated = response?.player;
  if (!updated) return;
  app.worldPlayerEditorPlayer = updated;
  const cached = worldPlayerDataIndex().playersById.get(Number(updated.id));
  if (cached) Object.assign(cached, {name:updated.name,age:updated.age,ca:updated.ca,pa:updated.pa,nationality:updated.nationality,team_name:updated.team_name,asking_price:updated.asking_price,positions:updated.positions});
  rememberWorldPlayerSummary(cached || updated);
  invalidateWorldPlayerDataIndex();
  openClubDetail("player", Number(updated.id), {players:[updated]}, options);
  openWorldPlayerEditor(updated, options);
  renderWorldPlayers();
}

