async function saveWorldPlayerPreferredMoves(player, options) {
  if (app.worldPlayerEditorBusy) return;
  const selected = new Set([...document.querySelectorAll("[data-world-player-preferred-move]:checked")].map((input) => Number(input.dataset.worldPlayerPreferredMove)));
  const current = new Set((player.preferred_moves || []).map((row) => Number(row.bit)));
  const changes = [
    ...[...selected].filter((bit) => !current.has(bit)).map((bit) => ({bit,operation:"learn"})),
    ...[...current].filter((bit) => !selected.has(bit)).map((bit) => ({bit,operation:"unlearn"})),
  ];
  if (!changes.length) { toast(uiText("world.editor.preferred_no_changes")); return; }
  if (!await fmoddConfirm(`${uiText("world.editor.confirm_preferred", {count:changes.length})}${uiText("world.editor.memory_warning")}`, uiText("world.editor.confirm_preferred_title"))) return;
  try {
    const response = await runWorldPlayerEditorAction(uiText("world.editor.busy_preferred"), async () => {
      let result = null;
      for (const change of changes) {
        result = await request("/api/world-players/preferred-move", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({player_id:Number(player.id),...change})});
        player = result.player || player;
      }
      return result;
    });
    if (!response) return;
    applyWorldPlayerEditorResponse(response, options);
    toast(uiText("world.editor.preferred_saved"));
  } catch (error) { toast(error.message || uiText("world.editor.preferred_failed")); }
}

