async function saveWorldPlayerContract(player, options = {}) {
  const contract = player.player_contract;
  const content = $("#world-player-editor-content");
  if (!contract || !content || app.worldPlayerEditorBusy) return;
  const changes = {};
  const expected = {
    expected_raw: player.editor?.expected_raw?.contract || "",
    contract: {},
  };
  content.querySelectorAll("[data-world-player-contract-field]").forEach((input) => {
    const field = input.dataset.worldPlayerContractField;
    const before = contract[field];
    const after = input.type === "date" ? input.value : Number(input.value);
    if (String(after) !== String(before)) {
      changes[field] = after;
      expected.contract[field] = before;
    }
  });
  const beforeStatus = Number(contract.transfer_status_raw || 0);
  let afterStatus = beforeStatus;
  content.querySelectorAll("[data-world-player-contract-status-bit]").forEach((input) => {
    const bit = Number(input.dataset.worldPlayerContractStatusBit);
    if (input.checked) afterStatus |= bit;
    else afterStatus &= ~bit;
  });
  if (afterStatus !== beforeStatus) {
    changes.transfer_status_raw = afterStatus;
    expected.contract.transfer_status_raw = beforeStatus;
  }
  const bonusChanges = [];
  const expectedBonuses = [];
  content.querySelectorAll("[data-world-player-contract-bonus-amount]").forEach((input) => {
    const index = Number(input.dataset.worldPlayerContractBonusAmount);
    const beforeRow = (contract.bonuses_and_clauses || []).find((row) => Number(row.index) === index);
    if (!beforeRow) return;
    const amount = Number(input.value);
    const requested = {index, amount};
    const numberInput = content.querySelector(`[data-world-player-contract-bonus-number="${index}"]`);
    if (numberInput) requested.number = Number(numberInput.value);
    if (amount !== Number(beforeRow.amount) || (numberInput && requested.number !== Number(beforeRow.number))) {
      bonusChanges.push(requested);
    }
    expectedBonuses.push({index, type:Number(beforeRow.type), amount:Number(beforeRow.amount), number:beforeRow.number == null ? null : Number(beforeRow.number)});
  });
  if (bonusChanges.length) {
    changes.bonuses_and_clauses = bonusChanges;
    expected.contract.bonuses_and_clauses = expectedBonuses;
    expected.expected_raw = {
      contract: player.editor?.expected_raw?.contract || "",
      contract_bonuses: player.editor?.expected_raw?.contract_bonuses || "",
    };
  }
  if (!Object.keys(changes).length) {
    toast(uiText("world.editor.contract_no_changes"));
    return;
  }
  if (!await fmoddConfirm(`${uiText("world.editor.confirm_contract", {player:player.name})}${uiText("world.editor.memory_warning")}`, uiText("world.editor.confirm_contract_title"))) return;
  try {
    const response = await runWorldPlayerEditorAction(uiText("world.editor.busy_contract"), () => request("/api/world-players/contract", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({player_id:Number(player.id),changes,expected})}));
    if (!response) return;
    applyWorldPlayerEditorResponse(response, options);
    toast(uiText("world.editor.contract_saved"));
  } catch (error) { toast(error.message || uiText("world.editor.contract_failed")); }
}

