function collectWorldPlayerEdits(player) {
  const content = $("#world-player-editor-content");
  const changes = {};
  const expected = {expected_raw:{...(player.editor?.expected_raw || {})}};
  content.querySelectorAll("[data-world-player-field]").forEach((input) => {
    const field = input.dataset.worldPlayerField;
    const before = field === "joined_club_date"
      ? player.player_contract?.joined_club_date
      : player[field];
    const after = input.type === "date" ? input.value : Number(input.value);
    if (String(after) !== String(before)) {
      changes[field] = after;
      expected[field] = before;
    }
  });
  const nested = [
    ["positions", "[data-world-player-position]", "worldPlayerPosition", player.editor?.positions || {}],
    ["attributes", "[data-world-player-attribute]", "worldPlayerAttribute", Object.fromEntries(Object.entries(player.attributes || {}).flatMap(([group, values]) => Object.entries(values || {}).map(([name, value]) => [`${group}:${name}`, value])))],
    ["hidden_attributes", "[data-world-player-hidden]", "worldPlayerHidden", player.hidden_attributes || {}],
  ];
  nested.forEach(([field, selector, datasetKey, original]) => {
    const updates = {};
    const oldValues = {};
    content.querySelectorAll(selector).forEach((input) => {
      const key = input.dataset[datasetKey];
      const after = Number(input.value);
      if (after !== Number(original[key])) {
        updates[key] = after;
        oldValues[key] = Number(original[key]);
      }
    });
    if (Object.keys(updates).length) {
      changes[field] = updates;
      expected[field] = oldValues;
    }
  });
  return {changes, expected};
}

async function saveWorldPlayerEditor(event) {
  event.preventDefault();
  if (app.worldPlayerEditorBusy) return;
  const player = app.worldPlayerEditorPlayer;
  const options = app.worldPlayerEditorOptions || {};
  if (!player) return;
  const {changes, expected} = collectWorldPlayerEdits(player);
  if (!Object.keys(changes).length) {
    toast(uiText("world.editor.no_changes"));
    return;
  }
  if (!await fmoddConfirm(`${uiText("world.editor.confirm_changes", {player:player.name, count:Object.keys(changes).length})}${uiText("world.editor.memory_warning")}`, uiText("world.editor.confirm_changes_title"))) return;
  try {
    const response = await runWorldPlayerEditorAction(uiText("world.editor.busy_changes"), () => request("/api/world-players/edit", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({player_id:Number(player.id),changes,expected})}));
    if (!response) return;
    const updated = response.player;
    app.worldPlayerEditorPlayer = updated;
    const cached = worldPlayerDataIndex().playersById.get(Number(updated.id));
    if (cached) Object.assign(cached, {name:updated.name,age:updated.age,ca:updated.ca,pa:updated.pa,nationality:updated.nationality,team_name:updated.team_name,asking_price:updated.asking_price,positions:updated.positions});
    rememberWorldPlayerSummary(cached || updated);
    invalidateWorldPlayerDataIndex();
    $("#world-player-editor-dialog").close();
    openClubDetail("player", Number(updated.id), {players:[updated]}, options);
    renderWorldPlayers();
    toast(uiText("world.editor.changes_saved"));
  } catch (error) {
    toast(error.message || uiText("world.editor.changes_failed"));
  }
}

