async function saveUiLocaleSelection(select, {settingsMutation = false, notify = true} = {}) {
  if (!select) return false;
  const previous = activeUiLocale();
  const next = window.FMODDI18n?.SUPPORTED_LOCALES?.includes(select.value) ? select.value : previous;
  if (next === previous) {
    const persisted = Boolean(window.FMODDI18n?.syncAuthoritativeLocale(next));
    if (!persisted && notify) toast(uiText("settings.locale_failed"));
    return persisted;
  }
  const noticeConfirm = select.id === "usage-notice-language" ? $("#usage-notice-confirm") : null;
  select.disabled = true;
  if (noticeConfirm) noticeConfirm.disabled = true;
  if (settingsMutation) setSettingsMutationBusy("ui-locale", true);
  try {
    const settings = await request("/api/settings/ui-locale", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({locale:next}),
    });
    if (app.state) app.state.settings = {...(app.state.settings || {}), ...settings};
    if (!window.FMODDI18n?.syncAuthoritativeLocale(next)) throw new Error(uiText("settings.locale_failed"));
    document.querySelectorAll("#ui-locale, #usage-notice-language").forEach((localeSelect) => {
      localeSelect.value = next;
    });
    app.shellRenderSignature = null;
    app.shellRenderParts = {};
    renderShellControls(output(), isSaveConnected(), isWalletReady(), {force:true});
    window.FMODDI18n?.apply(document.body);
    syncSettingsDialogStatus();
    syncCustomSelects(document);
    if (notify) toast(uiText("settings.locale_saved"));
    return true;
  } catch (error) {
    select.value = previous;
    syncCustomSelects(select.closest("label, .ui-locale-setting") || document);
    toast(error.message || uiText("settings.locale_failed"));
    return false;
  } finally {
    select.disabled = false;
    if (noticeConfirm) noticeConfirm.disabled = false;
    if (settingsMutation) setSettingsMutationBusy("ui-locale", false);
  }
}

