function fontOptionLabel(fontKey) {
  const option = FONT_OPTIONS[fontKey];
  if (!option) return fontKey;
  return option.labelKey ? uiText(option.labelKey) : option.label;
}

function syncLocaleFontControls(locale = activeUiLocale()) {
  const config = localeFontConfig(locale);
  const selectedKey = storedLocaleFontKey(locale);
  for (const selectId of ["chinese-font", "english-font"]) {
    const select = $(`#${selectId}`);
    const label = select?.closest("label");
    if (!select || !label) continue;
    const isLocaleControl = selectId === config.selectId;
    const isLatinControl = CJK_FONT_LOCALES.has(locale) && selectId === "english-font";
    const active = isLocaleControl || isLatinControl;
    label.hidden = !active;
    if (!active) continue;
    const fontLocale = isLatinControl ? "en-GB" : locale;
    const availableKeys = availableLocaleFontKeys(fontLocale);
    const controlKey = isLatinControl ? storedLocaleFontKey("en-GB") : selectedKey;
    const labelKey = isLatinControl ? "settings.font.latin_and_numbers" : "settings.font.language";
    const labelText = label.querySelector("span");
    if (labelText) {
      labelText.dataset.i18n = labelKey;
      labelText.textContent = uiText(labelKey);
    }
    select.setAttribute("aria-label", uiText(labelKey));
    select.dataset.fontLocale = fontLocale;
    const currentKeys = [...select.options].map((option) => option.value);
    if (JSON.stringify(currentKeys) !== JSON.stringify(availableKeys)) {
      select.replaceChildren(...availableKeys.map((fontKey) => {
        const font = FONT_OPTIONS[fontKey];
        const option = new Option(fontOptionLabel(fontKey), fontKey);
        if (font.labelKey) option.dataset.i18n = font.labelKey;
        return option;
      }));
    }
    select.value = controlKey;
  }
  app.interfaceFontLocale = locale;
  app.interfaceFont = selectedKey;
  return selectedKey;
}

