async function savePortraitSourceSelection(mode, path) {
  const setting = $(".portrait-source-setting");
  const buttons = [...(setting?.querySelectorAll("button") || [])];
  setting?.setAttribute("aria-busy", "true");
  buttons.forEach((button) => { button.disabled = true; });
  try {
    const result = await request("/api/player-portraits/settings", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({
        graphics_root: mode === "graphics" ? path : "",
        xml_path: mode === "xml" ? path : "",
        clear_all: mode === "clear",
      }),
    });
    if (app.state) app.state.settings = {...(app.state.settings || {}), ...result};
    app.clubLegacyRevision += 1;
    app.clubLegacyRenderSignature = null;
    if (app.page === "hall-of-fame") renderHallOfFame();
    if (mode === "clear") toast(uiText("settings.portraits.cleared"));
    else if (mode === "graphics") toast(uiText("settings.portraits.graphics_selected"));
    else {
      const xmlCount = Array.isArray(result.portrait_xml_paths) ? result.portrait_xml_paths.length : 1;
      toast(uiText("settings.portraits.xml_added", {count:xmlCount}));
    }
  } catch (error) {
    toast(error.message || uiText("settings.portraits.save_failed"));
  } finally {
    setting?.setAttribute("aria-busy", "false");
    buttons.forEach((button) => { button.disabled = false; });
  }
}

