function renderUpdateCheckResult() {
  const status = $("#update-check-status");
  const button = $("#check-for-updates");
  const ignore = $("#ignore-update");
  const download = $("#update-download-link");
  if (!status || !button || !ignore || !download) return;
  const latestVersion = String(app.updateCheckResult?.latest_version || "").trim();
  const updateAvailable = Boolean(
    app.updateCheckResult?.update_available
    && latestVersion
    && localStorage.getItem(IGNORED_UPDATE_VERSION_STORAGE_KEY) !== latestVersion
  );
  $("#settings-button")?.classList.toggle("update-available", updateAvailable);
  download.classList.toggle("update-available", updateAvailable);
  button.disabled = app.updateCheckBusy;
  button.hidden = false;
  status.className = "";
  ignore.hidden = true;
  download.hidden = true;
  if (app.updateCheckBusy) {
    status.hidden = false;
    status.textContent = uiText("settings.update.checking");
    download.hidden = true;
    return;
  }
  if (app.updateCheckFailed) {
    status.hidden = false;
    status.className = "failed";
    status.textContent = uiText("settings.update.failed");
    download.hidden = true;
    return;
  }
  const result = app.updateCheckResult;
  if (!result) {
    status.hidden = true;
    status.textContent = "";
    download.hidden = true;
    return;
  }
  status.hidden = false;
  status.className = result.update_available ? "available" : "current";
  status.textContent = result.update_available
    ? uiText("settings.update.versions", {
      current:String(result.current_version || "-"),
      latest:String(result.latest_version || "-"),
    })
    : uiText("settings.update.current", {version:String(result.current_version || "-")});
  download.href = String(result.download_page || "https://fmodd.com/download");
  button.hidden = Boolean(result.update_available);
  download.hidden = !result.update_available;
  ignore.hidden = !updateAvailable;
}

async function checkForUpdates({silent = false} = {}) {
  if (app.updateCheckBusy) return;
  app.updateCheckBusy = true;
  app.updateCheckFailed = false;
  renderUpdateCheckResult();
  try {
    app.updateCheckResult = await request("/api/update-check", {
      timeoutMs:8000,
      timeoutMessage:uiText("settings.update.failed"),
    });
  } catch (_error) {
    app.updateCheckResult = null;
    app.updateCheckFailed = !silent;
  } finally {
    app.updateCheckBusy = false;
    renderUpdateCheckResult();
  }
}

function operationRecordTime(value) {
  const date = new Date(String(value || ""));
  if (Number.isNaN(date.getTime())) return uiText("time.unknown");
  return date.toLocaleString(activeUiLocale(), {
    month:"2-digit", day:"2-digit", hour:"2-digit", minute:"2-digit", second:"2-digit", hour12:false,
  });
}

function operationRecordDuration(record) {
  const started = new Date(String(record.started_at || "")).getTime();
  const finished = record.finished_at ? new Date(String(record.finished_at)).getTime() : Date.now();
  if (!Number.isFinite(started) || !Number.isFinite(finished) || finished < started) return "";
  const seconds = Math.max(0, Math.round((finished - started) / 1000));
  return seconds < 60
    ? uiText("time.seconds", {seconds})
    : uiText("time.minutes_seconds", {minutes:Math.floor(seconds / 60), seconds:seconds % 60});
}

function operationLogIsVisible() {
  const dialog = $("#settings-dialog");
  const panel = $('[data-settings-panel="operations"]');
  return Boolean(dialog?.open && panel && !panel.hidden);
}

function renderOperationRecords({visibleOnly = false} = {}) {
  if (visibleOnly && !operationLogIsVisible()) return;
  const root = $("#operation-log-content");
  const summary = $("#operation-log-summary");
  const clearButton = $("#clear-operation-log");
  if (!root || !summary) return;
  summary.setAttribute("role", "status");
  summary.setAttribute("aria-live", "polite");
  root.setAttribute("role", "list");
  root.setAttribute("aria-label", uiText("operations.aria"));
  const records = app.operationRecords || [];
  const running = records.filter((record) => record.status === "running").length;
  const failed = records.filter((record) => ["failed", "interrupted"].includes(record.status)).length;
  const success = records.filter((record) => record.status === "success").length;
  summary.innerHTML = `<span class="running">${uiText("operations.running")} <b>${running}</b></span><span class="success">${uiText("operations.success")} <b>${success}</b></span><span class="failed">${uiText("operations.failed_summary")} <b>${failed}</b></span>`;
  if (clearButton) clearButton.disabled = records.length === 0 || running > 0;
  const statusCopy = {
    running:[uiText("operations.running"), "loader-circle"],
    success:[uiText("operations.completed"), "circle-check"],
    failed:[uiText("operations.failed"), "circle-x"],
    interrupted:[uiText("operations.unconfirmed"), "circle-help"],
  };
  root.innerHTML = records.map((record) => {
    const [statusLabel, icon] = statusCopy[record.status] || statusCopy.interrupted;
    const duration = operationRecordDuration(record);
    const location = String(record.location || operationRouteLocation(record.path) || "");
    const locationRow = location ? `<small class="operation-log-location">${escapeHtml(uiText("operations.location", {location}))}</small>` : "";
    return `<article class="operation-log-row ${escapeHtml(record.status)}" role="listitem"><i data-lucide="${icon}" aria-hidden="true"></i><div class="operation-log-main"><div><strong>${escapeHtml(record.title)}</strong><span>${escapeHtml(statusLabel)}</span></div><small>${escapeHtml(record.save_name || uiText("operations.no_save"))} · ${escapeHtml(operationRecordTime(record.started_at))}${duration ? ` · ${escapeHtml(duration)}` : ""}</small>${record.detail ? `<p>${escapeHtml(record.detail)}</p>` : ""}${locationRow}</div></article>`;
  }).join("") || `<div class="operation-log-empty"><i data-lucide="list-checks"></i><strong>${uiText("operations.empty")}</strong><span>${uiText("operations.empty_note")}</span></div>`;
  renderIcons(root);
}

