function activateSettingsTab(key, {focus = false} = {}) {
  const tabs = [...document.querySelectorAll("[data-settings-tab]")];
  const selected = tabs.some((tab) => tab.dataset.settingsTab === key)
    ? key : SETTINGS_TAB_GROUPS[0].key;
  const settings = $("#settings-dialog .settings-content");
  if (settings) settings.dataset.activeTab = selected;
  const dialog = $("#settings-dialog");
  if (dialog) dialog.dataset.activeTab = selected;
  tabs.forEach((tab) => {
    const active = tab.dataset.settingsTab === selected;
    tab.classList.toggle("active", active);
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
    if (active && focus) tab.focus();
  });
  document.querySelectorAll("[data-settings-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.settingsPanel !== selected;
  });
  localStorage.setItem("fmodd-settings-tab", selected);
  if (selected === "operations" && $("#settings-dialog")?.open) renderOperationRecords();
}

function ensureSettingsTabs() {
  const settings = $("#settings-dialog .settings-content");
  const dialog = $("#settings-dialog");
  if (!settings || !dialog) return;
  const title = dialog.querySelector(".dialog-head h2");
  if (title) title.id = "settings-dialog-title";
  dialog.setAttribute("aria-labelledby", "settings-dialog-title");
  dialog.setAttribute("aria-busy", "false");
  settings.setAttribute("aria-busy", "false");
  if (!$("#settings-sync-status")) {
    const status = document.createElement("p");
    status.id = "settings-sync-status";
    status.className = "settings-sync-status";
    status.setAttribute("role", "status");
    status.setAttribute("aria-live", "polite");
    status.hidden = true;
    dialog.querySelector(".dialog-head > div")?.append(status);
  }
  if (settings.querySelector(".settings-tabs")) return;
  const originalItems = [...settings.children];
  const tabs = document.createElement("nav");
  const panelStack = document.createElement("div");
  tabs.className = "settings-tabs";
  panelStack.className = "settings-panels";
  tabs.setAttribute("role", "tablist");
  tabs.setAttribute("aria-label", uiText("settings.tabs.aria"));
  const panels = new Map();
  SETTINGS_TAB_GROUPS.forEach((group) => {
    const tab = document.createElement("button");
    tab.type = "button";
    tab.id = `settings-tab-${group.key}`;
    tab.dataset.settingsTab = group.key;
    tab.dataset.i18n = group.labelKey;
    tab.setAttribute("role", "tab");
    tab.setAttribute("aria-controls", `settings-panel-${group.key}`);
    tab.textContent = uiText(group.labelKey);
    tabs.append(tab);
    const panel = document.createElement("section");
    panel.id = `settings-panel-${group.key}`;
    panel.className = "settings-panel";
    panel.dataset.settingsPanel = group.key;
    panel.setAttribute("role", "tabpanel");
    panel.setAttribute("aria-labelledby", tab.id);
    panels.set(group.key, panel);
    panelStack.append(panel);
  });
  const assigned = new Set();
  SETTINGS_TAB_GROUPS.forEach((group) => {
    const panel = panels.get(group.key);
    group.selectors.forEach((selector) => {
      let item = settings.querySelector(selector);
      while (item && item.parentElement !== settings) item = item.parentElement;
      if (!item || assigned.has(item)) return;
      assigned.add(item);
      panel.append(item);
    });
  });
  originalItems.forEach((item) => {
    if (!assigned.has(item)) panels.get("general").append(item);
  });
  settings.replaceChildren(tabs, panelStack);
  tabs.addEventListener("click", (event) => {
    const tab = event.target.closest("[data-settings-tab]");
    if (tab) activateSettingsTab(tab.dataset.settingsTab);
  });
  tabs.addEventListener("keydown", (event) => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    const buttons = [...tabs.querySelectorAll("[data-settings-tab]")];
    const current = Math.max(0, buttons.indexOf(event.target.closest("[data-settings-tab]")));
    const index = event.key === "Home" ? 0
      : event.key === "End" ? buttons.length - 1
      : (current + (event.key === "ArrowRight" ? 1 : -1) + buttons.length) % buttons.length;
    event.preventDefault();
    activateSettingsTab(buttons[index].dataset.settingsTab, {focus:true});
  });
  const stored = localStorage.getItem("fmodd-settings-tab");
  activateSettingsTab(
    SETTINGS_TAB_GROUPS.some((group) => group.key === stored)
      ? stored : SETTINGS_TAB_GROUPS[0].key,
  );
}

