  $("#place-button").addEventListener("click", async () => {
    const button = $("#place-button");
    if (button.disabled || app.betSubmissionBusy) return;
    const idleContent = button.innerHTML;
    app.betSubmissionBusy = true;
    renderSlip();
    button.textContent = uiText("betting.submitting");
    try {
      const championships = app.selections.length > 0 && app.selections.every((selection) => selection.type === "championship") ? app.selections : null;
      const path = championships ? "/api/championship-bets" : "/api/bets";
      const payload = championships
        ? {stake:Number(app.stake),selections:championships.map((selection) => ({competition_id:selection.competition_id,team_id:selection.team_id,market_version:selection.market_version,odds:selection.odds}))}
        : {mode:app.mode,pass_code:systemParlaySummary().passCode,stake:Number(app.stake),selections:app.selections,data_version:app.state?.data_version,save_instance_id:output().save_instance_id};
      const fingerprint = `${path}|${JSON.stringify(payload)}`;
      if (app.betSubmissionRetry?.fingerprint !== fingerprint) {
        app.betSubmissionRetry = {fingerprint, id:clientSubmissionId()};
      }
      payload.client_submission_id = app.betSubmissionRetry.id;
      const result = await request(path, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify(payload), timeoutMs:15000,
        timeoutMessage:uiText("betting.submit_timeout"),
      });
      app.betSubmissionRetry = null;
      app.selections = [];
      if (Number.isFinite(Number(result.balance))) {
        applyEconomySnapshot(
          {casino_balance:Number(result.balance)},
          {merge:true},
        );
      }
      if (app.state && Array.isArray(result.bets)) {
        const acceptedIds = new Set(result.bets.map((bet) => String(bet.bet_id || "")));
        const previousBets = (app.state.bets || []).filter(
          (bet) => !acceptedIds.has(String(bet.bet_id || "")),
        );
        app.state.bets = [...result.bets].reverse().concat(previousBets);
      }
      refreshSelectionUI();
      if (result.repriced) await loadState({fresh:true});
      toast(result.duplicate
        ? uiText("betting.duplicate_confirmed", {count:result.records})
        : result.repriced
          ? uiText("betting.repriced_recorded", {count:result.records})
          : uiText("betting.recorded", {count:result.records}));
    } catch (error) {
      const message = error.message || uiText("betting.submit_failed");
      if (error.code !== "REQUEST_TIMEOUT") app.betSubmissionRetry = null;
      if (/盘口|刷新|存档已变化/.test(message)) {
        await loadState({fresh:true});
        if (app.state?.refreshing || app.state?.reconciling) beginPolling(1000, "status");
      }
      toast(message);
    } finally {
      app.betSubmissionBusy = false;
      button.innerHTML = idleContent;
      renderSlip();
      renderIcons();
    }
  });
