  $("#money-input-form").addEventListener("submit", async (event) => {
    event.preventDefault();
    const displayedAmount = Number($("#money-input-amount").value || 0);
    let amount = Math.min(toInternalMoney(displayedAmount), app.moneyMaximum);
    if (!(amount > 0)) { toast(uiText("money.invalid_amount")); return; }
    const direction = app.moneyDirection;
    const ownedClubFinance = app.ownedClubFinance;
    $("#money-input-dialog").close();
    try {
      const budgetTransfer = direction.startsWith("transfer_budget_");
      const clubBalanceTransfer = direction.startsWith("club_balance_");
      const clubFundsTransfer = budgetTransfer || clubBalanceTransfer;
      if (clubFundsTransfer) amount = Math.max(1, Math.round(amount));
      const endpoint = ownedClubFinance ? "/api/world-clubs/finance-transfer" : direction === "repay" ? "/api/bank/repay" : budgetTransfer ? "/api/bank/transfer-budget" : clubBalanceTransfer ? "/api/bank/club-balance" : "/api/bank/transfer";
      const body = ownedClubFinance
        ? {team_id:ownedClubFinance.teamId, field:ownedClubFinance.field, direction:ownedClubFinance.direction, amount}
        : direction === "repay" ? {amount} : clubFundsTransfer ? {direction: direction.endsWith("_in") ? "in" : "out", amount} : {direction, amount, data_scope_id:String(app.state?.data_scope_id || "")};
      const operation = async () => {
        const response = await request(endpoint, {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)});
        await applyStatePatchOrReload(response);
        if (response.operation_applied === false) {
          toast(response.operation_status || response.transfer_budget?.status || uiText("money.previous_budget_shown"));
          return;
        }
        if (ownedClubFinance && response.owned_club_finance) {
          const finances = ownedClubFinance.detail.club_information?.finances || {};
          const value = Number(response.owned_club_finance.amount || 0);
          const teamId = Number(ownedClubFinance.teamId);
          const metrics = {
            ...(app.ownedClubMetrics.get(teamId) || {}),
          };
          if (ownedClubFinance.field === "transfer_budget") {
            finances.remaining_transfer_budget = value;
            finances.transfer_budget = value;
            metrics.transfer_budget = value;
          } else {
            finances.balance = value;
            metrics.balance = value;
          }
          app.ownedClubMetrics.set(teamId, metrics);
          updateOwnedClubCachedMetrics(
            teamId,
            ownedClubFinance.field === "transfer_budget"
              ? {transfer_budget:value} : {balance:value},
          );
          app.ownedClubMetricsVersion += 1;
          rebuildOwnedClubPortfolioSummaryFromCache();
          renderMyClubs();
          renderOwnedClubDetailContent(
            ownedClubFinance.content, ownedClubFinance.detail,
            ownedClubFinance.club, ownedClubFinance.teamId,
            ownedClubFinance.activeTab,
          );
        }
      };
      const runFinanceOperation = () => ownedClubFinance?.triggerButton
        ? runOwnedClubOperation(
          ownedClubFinance.triggerButton,
          direction === "club_balance_out" ? uiText("money.busy.club_balance_out")
            : direction === "transfer_budget_out" ? uiText("money.busy.transfer_budget_out")
              : direction === "club_balance_in" ? uiText("money.busy.club_balance_in") : uiText("money.busy.transfer_budget_in"),
          operation,
          `finance:${ownedClubFinance.teamId}:${ownedClubFinance.field}:${ownedClubFinance.direction}`,
        )
        : ["transfer_budget_out","club_balance_out"].includes(direction)
          ? runItemOperation(
            direction,
            direction === "club_balance_out" ? uiText("money.busy.club_balance_out") : uiText("money.busy.transfer_budget_out"),
            operation,
            uiText("money.diversion_done"),
          )
          : operation();
      if (["transfer_budget_out","club_balance_out"].includes(direction)) {
        const clubBalance = direction === "club_balance_out";
        await runFinanceOperation();
        toast(uiText("money.diversion_done"));
      } else {
        await runFinanceOperation();
        toast(direction === "recharge" ? uiText("money.transfer.recharge_done") : direction === "withdraw" ? uiText("money.transfer.withdraw_done") : direction === "transfer_budget_in" ? uiText("money.transfer.transfer_budget_in_done") : direction === "club_balance_in" ? uiText("money.transfer.club_balance_in_done") : uiText("money.transfer.repay_done"));
      }
    } catch (error) { toast(error.message); }
    finally { app.ownedClubFinance = null; }
  });
