    Object.values(LEGACY_FONT_STORAGE_KEYS).forEach((key) => localStorage.removeItem(key));
    const locale = activeUiLocale();
    app.interfaceFontLocale = locale;
    app.interfaceFont = localeFontConfig(locale).defaultKey;
    app.fontSizeStep = DEFAULT_FONT_SIZE_STEP;
    localStorage.removeItem(FONT_SIZE_STORAGE_KEY);
    localStorage.removeItem(FONT_SIZE_SCHEMA_KEY);
    applyLocaleFontPreference(locale, app.interfaceFont);
    applyFontSizePreference(app.fontSizeStep);
    renderSettingsControls({force:true});
    syncCustomSelects($(".font-settings"));
    toast(uiText("settings.font.restored"));
