function configureOfficialNewsLink() {
  const link = $(".author-update-note");
  if (!link) return;
  link.href = "https://fmodd.com/";
  const icon = document.createElement("i");
  icon.dataset.lucide = "globe-2";
  const label = document.createElement("span");
  label.dataset.i18n = "settings.latest_news";
  label.textContent = uiText("settings.latest_news");
  link.replaceChildren(icon, label);
}

